const restoreSession = async () => {
    const today = dinhDangNgayISO(new Date());

    // 1. Fetch Today's Report to restore UI
    try {
        const reports = await apiCall(`report?q={"ngayBaoCao": "${today}"}`);
        if (reports.length > 0) {
            const report = reports[0];
            // Only show status if we are actually restoring something significant
            if(report.baoCaoFOS && report.baoCaoFOS.length > 0) {
                 showStatus(`Đã tìm thấy báo cáo đã lưu trên server.`, 'info');
            }

            // Map report data back to danhSachFOS
            report.baoCaoFOS.forEach(item => {
                const fos = danhSachFOS.find(f => f.ten === item.tenNhanVien);
                if (fos) {
                    // New OFF field Logic for Restore
                    const offState = item.OFF;
                    if (offState !== undefined) {
                        if (offState === 0) {
                            fos.trangThai = 'Đã báo cáo';
                            if (item.rawReport) {
                                fos.baoCao = item.rawReport;
                            } else {
                                 // Fallback if rawReport missing but reported
                                 const mtd = item.chiSoHieuSuat.saleTrongThang;
                                 const todaySale = item.chiSoHieuSuat.saleHomNay;
                                 fos.baoCao = `Fos ${item.tenNhanVien} (Khôi phục)\nTổng MC: ${todaySale}\nMTD MC: ${mtd}`;
                            }
                        } else {
                            fos.trangThai = 'Off';
                            // 1 is default OFF, otherwise it's the reason text
                            const reason = (offState === 1 || offState === '1') ? 'OFF' : offState;
                            // Reconstruct the OFF report text so UI displays it correctly
                            fos.baoCao = `Fos ${item.tenNhanVien} ${reason}`;
                        }
                    } else {
                        // Fallback for old records without OFF field
                        if (item.rawReport) {
                            fos.baoCao = item.rawReport;
                            fos.trangThai = item.rawReport.includes('OFF') ? 'Off' : 'Đã báo cáo';
                        } else {
                            const mtd = item.chiSoHieuSuat.saleTrongThang;
                            const todaySale = item.chiSoHieuSuat.saleHomNay;
                            if (todaySale === 0 && mtd === 0) {
                                 fos.baoCao = `Fos ${item.tenNhanVien} (Khôi phục)\nTổng MC: ${todaySale}\nMTD MC: ${mtd}`;
                                 fos.trangThai = 'Đã báo cáo';
                            } else {
                                fos.baoCao = `Fos ${item.tenNhanVien} (Khôi phục)\nTổng MC: ${todaySale}\nMTD MC: ${mtd}`;
                                fos.trangThai = 'Đã báo cáo';
                            }
                        }
                    }
                }
            });
            veLaiDanhSachFOS();
            // Re-generate the text view but DO NOT SAVE (Dry Run)
            taoBaoCao(null, true);
        }
    } catch (e) { console.warn("Không thể khôi phục phiên hôm nay", e); }

    // 2. Fetch Nearest Previous Report for MTD Check
    try {
        // Fetch 1 report where date < today, sorted by date descending to get the nearest one
        const query = `{"ngayBaoCao": {"$lt": "${today}"}}`;
        const hint = `{"$orderby": {"ngayBaoCao": -1}}`;
        const oldReports = await apiCall(`report?q=${query}&h=${hint}&max=1`);

        if (oldReports.length > 0) {
            baoCaoHomQua = oldReports[0];
            const dateOfOldReport = baoCaoHomQua.ngayBaoCao;

            // Convert structure for compatibility with existing MTD check logic
            // We need an array map of {ten, mtdMC}
            const formattedOldData = baoCaoHomQua.baoCaoFOS.map(item => ({
                ten: item.tenNhanVien,
                mtdMC: item.chiSoHieuSuat.saleTrongThang
            }));

            // Wrap it to match expected structure in checkMTD
            baoCaoHomQua.fosData = formattedOldData; 

            // Set text for modal
            let textBaoCaoCu = `Dữ liệu ngày ${dateOfOldReport} (Gần nhất):\n`;
            formattedOldData.forEach(f => {
                 textBaoCaoCu += `${f.ten}: MTD ${f.mtdMC || 0}\n`;
            });
            $('#bao-cao-cu-ket-qua').val(textBaoCaoCu);
            showStatus(`Đã tải dữ liệu MTD từ ngày ${dateOfOldReport}.`, "info");
        }
    } catch (e) { console.warn("Không tìm thấy báo cáo cũ", e); }
};

const kiemTraMTD = () => {
    $('#mtd-warning-icon').hide();
    if (!baoCaoHomQua || !baoCaoHomQua.fosData) return;

    const danhSachLoi = [];
    const fosDataHomQuaMap = new Map(baoCaoHomQua.fosData.map(fos => [fos.ten, fos]));
    const dateLabel = ngayBaoCaoGanNhat ? dinhDangNgay(ngayBaoCaoGanNhat) : 'trước';

    danhSachFOS.forEach(fosHienTai => {
        const fosHomQua = fosDataHomQuaMap.get(fosHienTai.ten);
        if (!fosHomQua) return; 

        const mtdHomQua = fosHomQua.mtdMC || 0;
        // Robust MC calculation: NTB + ETB. If not present, try parsing "Tổng MC".
        let mcHomNay = layGiaTri(fosHienTai.baoCao, 'NTB') + layGiaTri(fosHienTai.baoCao, 'ETB');
        if (mcHomNay === 0) {
            mcHomNay = layGiaTri(fosHienTai.baoCao, 'Tổng MC');
        }

        const mtdHomNay = layGiaTri(fosHienTai.baoCao, 'MTD MC');

        if (fosHienTai.trangThai === 'Off') {
            // If OFF, check if user manually entered an MTD that contradicts the previous MTD
            // Note: If mtdHomNay is 0, it means user didn't enter it, which is fine (auto-fill handles it)
            if (mtdHomNay !== 0 && mtdHomNay !== mtdHomQua) { 
                 danhSachLoi.push({
                    ten: fosHienTai.ten,
                    lyDo: `Sai MTD (OFF)`,
                    chiTiet: `Cũ (${dateLabel}): ${mtdHomQua}. Nhập: ${mtdHomNay}. (OFF nên giữ nguyên MTD)`
                });
            }
        } else if (fosHienTai.trangThai === 'Đã báo cáo') { 
            const mtdDuKien = mtdHomQua + mcHomNay;
            if (mtdHomNay !== mtdDuKien) {
                danhSachLoi.push({
                    ten: fosHienTai.ten,
                    lyDo: `Cộng dồn MTD không chính xác.`,
                    chiTiet: `Dự kiến: ${mtdHomQua} (${dateLabel}) + ${mcHomNay} (nay) = ${mtdDuKien}. Thực tế: ${mtdHomNay}`
                });
            }
        }
    });

    if (danhSachLoi.length > 0) {
        let htmlLoi = `<p>Phát hiện sai sót MTD so với dữ liệu ngày ${dateLabel}:</p><ul class="list-group">`;
        danhSachLoi.forEach(loi => {
            htmlLoi += `
                <li class="list-group-item">
                    <div class="fw-bold">${loi.ten}</div>
                    <small>${loi.lyDo}</small>
                    <div class="text-muted" style="font-size: 0.8em;">${loi.chiTiet}</div>
                </li>
            `;
        });
        htmlLoi += '</ul>';
        $('#mtd-warning-list').html(htmlLoi);
        $('#mtd-warning-icon').show();
    }
};

// --- LOAD DATA ---
const loadFosFromRestDB = async () => {
    showLoading("Đang tải dữ liệu hệ thống...");
    try {
        // 1. Load Personnel (Blocking UI - Essential)
        const data = await apiCall('nhanvien?h={"$orderby": {"Ten": 1}}');
        appMode = 'online'; // Connection success

        // Map DB fields (Ten, GioiTinh, ChiTieu) to App structure
        danhSachFOS = data.map(item => ({
            _id: item._id,
            ten: item.Ten,
            gioiTinh: item.GioiTinh,
            chiTieu: parseInt(item.ChiTieu, 10) || 50,
            baoCao: '',
            trangThai: 'Chưa báo cáo',
            kiemTraTen: null
        }));
        veLaiDanhSachFOS();

        // 2. Load Local Storage immediately (Fast & Sync)
        // We do this before unblocking so user sees their unsaved work immediately
        loadLocalCache();

        // 3. UNBLOCK UI NOW - User can start interacting
        hideLoading();

        // 4. Background Synchronization
        $('#bg-processing-indicator').css('display', 'flex').find('span').text('Đang đồng bộ...');

        refreshDbStats();

        // 5. Restore Session from Server & Previous Report (Background)
        await restoreSession();

    } catch (error) {
        console.warn("RestDB failed, trying local backup", error);
        appMode = 'offline'; // Connection failed, switch to offline
        updateDbWidget(false, null, null);

        try {
            const response = await fetch('fos.txt');
            if (!response.ok) throw new Error("File not found");
            const text = await response.text();
            danhSachFOS = text.split('\n')
                .map(line => line.trim())
                .filter(line => line.length > 0)
                .map((line, index) => {
                    // format: Name|Gender|Target
                    const parts = line.split('|');
                    return {
                        _id: `local_${index}`,
                        ten: parts[0]?.trim() || 'Unknown',
                        gioiTinh: parts[1]?.trim() || 'Nam',
                        chiTieu: parseInt(parts[2]?.trim() || '50', 10),
                        baoCao: '',
                        trangThai: 'Chưa báo cáo',
                        kiemTraTen: null
                    };
                });

            showStatus("Chế độ Offline: Đã tải dữ liệu từ file backup.", "info");
            veLaiDanhSachFOS();
            loadLocalCache();
            hideLoading(); // Hide here in catch block if successful
        } catch (fileErr) {
             hideLoading(); // Hide if everything fails
             $fosListArea.html('<div class="text-center py-3 text-danger"><i class="bi bi-exclamation-triangle me-1"></i>Lỗi kết nối & Không có dữ liệu backup</div>');
             showStatus("Lỗi tải dữ liệu: " + error.message, "error");
        }
    } finally {
        // Cleanup
        hideLoading(); 
        $('#bg-processing-indicator').hide();
        $('#bg-processing-indicator').find('span').text('Đang lưu...'); // Reset text
    }
};

const restoreSession = async () => {
    const today = dinhDangNgayISO(new Date());

    // 1. Fetch Today's Report to restore UI
    try {
        const reports = await apiCall(`report?q={"ngayBaoCao": "${today}"}`);
        if (reports.length > 0) {
            const report = reports[0];
            let restoredCount = 0;

            // Map report data back to danhSachFOS
            report.baoCaoFOS.forEach(item => {
                const fos = danhSachFOS.find(f => f.ten === item.tenNhanVien);
                // IMPORTANT: Only restore if user hasn't modified the data locally yet (baoCao is empty)
                // This prevents overwriting user input during background sync
                if (fos && fos.baoCao === '') {
                    // New OFF field Logic for Restore
                    const offState = item.OFF;
                    if (offState !== undefined) {
                        if (offState === 0) {
                            fos.trangThai = 'Đã báo cáo';
                            if (item.rawReport) {
                                fos.baoCao = item.rawReport;
                            } else {
                                 // Fallback if rawReport missing but reported
                                 const mtd = item.chiSoHieuSuat.saleTrongThang;
                                 const todaySale = item.chiSoHieuSuat.saleHomNay;
                                 fos.baoCao = `Fos ${item.tenNhanVien} (Khôi phục)\nTổng MC: ${todaySale}\nMTD MC: ${mtd}`;
                            }
                        } else {
                            fos.trangThai = 'Off';
                            // 1 is default OFF, otherwise it's the reason text
                            const reason = (offState === 1 || offState === '1') ? 'OFF' : offState;
                            // Reconstruct the OFF report text so UI displays it correctly
                            fos.baoCao = `Fos ${item.tenNhanVien} ${reason}`;
                        }
                    } else {
                        // Fallback for old records without OFF field
                        if (item.rawReport) {
                            fos.baoCao = item.rawReport;
                            fos.trangThai = item.rawReport.includes('OFF') ? 'Off' : 'Đã báo cáo';
                        } else {
                            const mtd = item.chiSoHieuSuat.saleTrongThang;
                            const todaySale = item.chiSoHieuSuat.saleHomNay;
                            if (todaySale === 0 && mtd === 0) {
                                 fos.baoCao = `Fos ${item.tenNhanVien} (Khôi phục)\nTổng MC: ${todaySale}\nMTD MC: ${mtd}`;
                                 fos.trangThai = 'Đã báo cáo';
                            } else {
                                fos.baoCao = `Fos ${item.tenNhanVien} (Khôi phục)\nTổng MC: ${todaySale}\nMTD MC: ${mtd}`;
                                fos.trangThai = 'Đã báo cáo';
                            }
                        }
                    }
                    restoredCount++;
                }
            });

            if (restoredCount > 0) {
                showStatus(`Đã đồng bộ ${restoredCount} báo cáo từ server.`, 'info');
                veLaiDanhSachFOS();
                // Re-generate the text view but DO NOT SAVE (Dry Run)
                taoBaoCao(null, true);
            }
        }
    } catch (e) { console.warn("Không thể khôi phục phiên hôm nay", e); }

    // 2. Fetch Nearest Previous Report for MTD Check
    try {
        // Fetch 1 report where date < today, sorted by date descending to get the nearest one
        const query = `{"ngayBaoCao": {"$lt": "${today}"}}`;
        const hint = `{"$orderby": {"ngayBaoCao": -1}}`;
        const oldReports = await apiCall(`report?q=${query}&h=${hint}&max=1`);

        if (oldReports.length > 0) {
            baoCaoHomQua = oldReports[0];
            ngayBaoCaoGanNhat = baoCaoHomQua.ngayBaoCao;
            const dateOfOldReport = dinhDangNgay(ngayBaoCaoGanNhat);

            // Convert structure for compatibility with existing MTD check logic
            // We need an array map of {ten, mtdMC}
            const formattedOldData = baoCaoHomQua.baoCaoFOS.map(item => ({
                ten: item.tenNhanVien,
                mtdMC: item.chiSoHieuSuat.saleTrongThang
            }));

            // Wrap it to match expected structure in checkMTD
            baoCaoHomQua.fosData = formattedOldData; 

            // Set text for modal
            let textBaoCaoCu = `Dữ liệu ngày ${dateOfOldReport} (Gần nhất):\n`;
            formattedOldData.forEach(f => {
                 textBaoCaoCu += `${f.ten}: MTD ${f.mtdMC || 0}\n`;
            });
            $('#bao-cao-cu-ket-qua').val(textBaoCaoCu);
            // showStatus(`Đã tải dữ liệu MTD từ ngày ${dateOfOldReport}.`, "info"); // Optional: reduce noise
        }
    } catch (e) { console.warn("Không tìm thấy báo cáo cũ", e); }
};

