    "content-type": "application/json",
    "x-apikey": MA_X_API,
    "cache-control": "no-cache"
};
export const KHOA_BO_NHO_TAM_CUC_BO = 'kho_du_lieu_bao_cao_hang_ngay';

export const hienThiThongBao = (noiDung, loai = 'success') => {
    let mauNen = "linear-gradient(to right, #00b09b, #96c93d)"; // Thành công
    if (loai === 'danger' || loai === 'error') {
        mauNen = "linear-gradient(to right, #ff5f6d, #ffc371)"; // Lỗi
    } else if (loai === 'info') {
        mauNen = "linear-gradient(to right, #2193b0, #6dd5ed)"; // Thông tin
    }

    if (window.Toastify) {
        window.Toastify({
            text: noiDung,
            duration: 3000,
            gravity: "bottom",
            position: "right",
            stopOnFocus: true,
            style: {
                background: mauNen,
                borderRadius: "12px",
                boxShadow: "0 5px 15px rgba(0,0,0,0.15)",
                fontFamily: "'Poppins', sans-serif",
                padding: "12px 20px",
                fontWeight: "500",
                fontSize: "0.9rem"
            }
        }).showToast();
    } else {
        console.log(`[${loai}] ${noiDung}`);
    }
};

