};

import { DUONG_DAN_CSDL, TIEU_DE_TRUY_VAN } from './config.js';
import { dinhDangNgayISO } from './utils.js';

let cheDoUngDung = 'online';

export const datCheDoUngDung = (cheDo) => {
    cheDoUngDung = cheDo;
};

export const layCheDoUngDung = () => {
    return cheDoUngDung;
};

export const thucHienGoiApi = async (diemCuoi, phuongThuc = 'GET', duLieu = null) => {
    const tuyChon = {
        method: phuongThuc,
        headers: TIEU_DE_TRUY_VAN
    };
    if (duLieu) {
        tuyChon.body = JSON.stringify(duLieu);
    }
    const phanHoi = await fetch(`${DUONG_DAN_CSDL}/${diemCuoi}`, tuyChon);
    if (!phanHoi.ok) {
        const noiDungLoi = await phanHoi.text();
        throw new Error(`Lỗi API: ${phanHoi.status} - ${noiDungLoi}`);
    }
    return phanHoi.json();
};

export const ghiNhanTuongTacApi = async () => {
    if (cheDoUngDung === 'offline') return;

    const homNayStr = dinhDangNgayISO(new Date());

    try {
        const danhSachCaiDat = await thucHienGoiApi(`setting?max=1`);

        if (danhSachCaiDat.length > 0) {
            const caiDat = danhSachCaiDat[0];
            let soLuotMoi = (caiDat.connectionCount || 0) + 1;

            if (caiDat.date !== homNayStr) {
                soLuotMoi = 1;
            }

            $('#luong-truy-cap-api').text(`(${soLuotMoi})`);

            await thucHienGoiApi(`setting/${caiDat._id}`, 'PUT', { 
                connectionCount: soLuotMoi,
                date: homNayStr 
            });
        } else {
             $('#luong-truy-cap-api').text(`(1)`);
            await thucHienGoiApi('setting', 'POST', {
                connectionCount: 1,
                date: homNayStr
            });
        }
    } catch (e) {
        console.warn("Ghi nhận tương tác thất bại:", e);
    }
};

export const lamMoiThongKeCsdl = async (hamCapNhatWidget) => {
    try {
        const tieuDe = { ...TIEU_DE_TRUY_VAN };

        const phanHoiBaoCao = await fetch(`${DUONG_DAN_CSDL}/report?q={}&h={"$fields":{"_id":1}}`, {method: 'GET', headers: tieuDe});
        if (!phanHoiBaoCao.ok) throw new Error("Kết nối thất bại");
        const dsIdBaoCao = await phanHoiBaoCao.json();

        const phanHoiNv = await fetch(`${DUONG_DAN_CSDL}/nhanvien?q={}&h={"$fields":{"_id":1}}`, {method: 'GET', headers: tieuDe});
        const dsIdNv = await phanHoiNv.json();

        const phanHoiCaiDat = await fetch(`${DUONG_DAN_CSDL}/setting?max=1`, {method: 'GET', headers: tieuDe});
        const dsCaiDat = await phanHoiCaiDat.json();
        let soLuotKetNoi = 0;
        if(dsCaiDat.length > 0) {
            const c = dsCaiDat[0];
            const homNayStr = dinhDangNgayISO(new Date());
            if (c.date === homNayStr) {
                 soLuotKetNoi = c.connectionCount || 0;
            }
        }

        if (hamCapNhatWidget) {
            hamCapNhatWidget(true, dsIdNv.length, dsIdBaoCao.length, soLuotKetNoi);
        }
    } catch (e) {
        console.warn("Lấy thống kê DB thất bại", e);
    }
};

import { dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu } from './utils.js';

export const kiemTraTenTrongBaoCao = (duLieuNv, noiDungBaoCao) => {
    if (!noiDungBaoCao.trim()) {
        duLieuNv.kiemTraTen = null;
        return;
    }
    const tenDaEscape = duLieuNv.ten.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
    const bieuThuc = new RegExp(`^(fos\\s+)?${tenDaEscape}(?=\\s|$)`, 'i');
    duLieuNv.kiemTraTen = bieuThuc.test(noiDungBaoCao.trim());
};

export const kiemTraChiSoMtd = (danhSachNhanVien, baoCaoLichSu, ngayBaoCaoLichSu) => {
    $('#bieu-tuong-canh-bao-mtd').hide();
    // baoCaoLichSu PHẢI là báo cáo của ngày gần nhất trong quá khứ (< hôm nay)
    if (!baoCaoLichSu || !baoCaoLichSu.duLieuNvLichSu) return;

    const danhSachLoi = [];
    const banDoNvLichSu = new Map(baoCaoLichSu.duLieuNvLichSu.map(nv => [nv.ten, nv]));
    const nhanNgay = ngayBaoCaoLichSu ? dinhDangNgayHienThi(ngayBaoCaoLichSu) : 'trước';

    danhSachNhanVien.forEach(nvNay => {
        const nvCu = banDoNvLichSu.get(nvNay.ten);
        if (!nvCu) return; 

        const mtdLichSu = nvCu.mtdMC || 0;
        let mcHomNay = trichXuatSoLieu(nvNay.baoCao, 'NTB') + trichXuatSoLieu(nvNay.baoCao, 'ETB');
        if (mcHomNay === 0) {
            mcHomNay = trichXuatSoLieu(nvNay.baoCao, ['Tổng MC', 'MC']);
        }

        const mtdHomNay = trichXuatSoLieu(nvNay.baoCao, 'MTD MC');

        if (nvNay.trangThai === 'Off') {
            // Khi OFF, MTD nhập vào (nếu có và khác 0) phải khớp với lịch sử (ngày < hôm nay)
            if (mtdHomNay !== mtdLichSu && mtdHomNay !== 0) { 
                 danhSachLoi.push({
                    ten: nvNay.ten,
                    lyDo: `Sai MTD (Nghỉ)`,
                    chiTiet: `Dữ liệu ngày gần nhất (${nhanNgay}) là ${mtdLichSu}. Bạn nhập: ${mtdHomNay}. (Nghỉ nên giữ nguyên MTD)`
                });
            }
        } else if (nvNay.trangThai === 'Đã báo cáo') { 
            const mtdDuKien = mtdLichSu + mcHomNay;
            // Chỉ cảnh báo nếu người dùng nhập MTD khác 0 và khác với mốc cộng dồn từ quá khứ
            if (mtdHomNay !== 0 && mtdHomNay !== mtdDuKien) {
                danhSachLoi.push({
                    ten: nvNay.ten,
                    lyDo: `Cộng dồn MTD sai lệch.`,
                    chiTiet: `Dự kiến: ${mtdLichSu} (${nhanNgay}) + ${mcHomNay} (nay) = ${mtdDuKien}. Thực tế nhập: ${mtdHomNay}`
                });
            }
        }
    });

    if (danhSachLoi.length > 0) {
        let htmlLoi = `<p>Phát hiện sai lệch MTD so với mốc lịch sử (${nhanNgay}):</p><ul class="list-group">`;
        danhSachLoi.forEach(loi => {
            htmlLoi += `
                <li class="list-group-item">
                    <div class="fw-bold">${loi.ten}</div>
                    <small class="text-danger">${loi.lyDo}</small>
                    <div class="text-muted" style="font-size: 0.8em;">${loi.chiTiet}</div>
                </li>
            `;
        });
        htmlLoi += '</ul>';
        $('#vung-danh-sach-loi-mtd').html(htmlLoi);
        $('#bieu-tuong-canh-bao-mtd').show();
    }
};

export const taoCauTrucGuiBaoCao = (danhSachNhanVien, baoCaoLichSu, thongKe) => {
     const homNayStr = dinhDangNgayISO(new Date());

     const tongKetToanDoi = {
         tongSoFOS: thongKe.tongFOS,
         tongSoMC: thongKe.tongMC,
         tongSoNTB: thongKe.tongNTB,
         NSBQ_NTB: parseFloat(thongKe.nsbqNTB),
         tongSoETB: thongKe.tongETB,
         NSBQ_ETB: parseFloat(thongKe.nsbqETB),
         tongSoAEPlus: thongKe.tongAEPlus,
         tyLePOS: `${thongKe.tongPosThucHien}/${thongKe.posChiTieu}`,
         tyLeActiveFOS: `${thongKe.activeFOS}/${thongKe.tongFOS}`
     };

     const baoCaoNhanVien = danhSachNhanVien.map(nv => {
         const noiDung = nv.baoCao || '';
         let mtd = trichXuatSoLieu(noiDung, 'MTD MC');
         let mcHomNay = trichXuatSoLieu(noiDung, 'NTB') + trichXuatSoLieu(noiDung, 'ETB');
         if (mcHomNay === 0) {
            mcHomNay = trichXuatSoLieu(noiDung, ['Tổng MC', 'MC']);
         }

         let giaTriOff = 0;
         if (nv.trangThai === 'Off') {
             const khopLyDo = noiDung.match(/^Fos\s+\S+\s+(.*)$/i);
             const chuLyDo = (khopLyDo && khopLyDo[1]) ? khopLyDo[1].trim() : 'OFF';
             giaTriOff = chuLyDo.toUpperCase() === 'OFF' ? 1 : chuLyDo;
         }

         // LOGIC MTD: Nếu nhân viên OFF hoặc 0 sale, và mtd hiện tại vẫn là 0 (chưa nhập mới)
         // Luôn lấy từ baoCaoLichSu (ngày gần nhất TRƯỚC HÔM NAY)
         if ((nv.trangThai === 'Off' || mcHomNay === 0) && mtd === 0 && baoCaoLichSu && baoCaoLichSu.duLieuNvLichSu) {
             const nvCu = baoCaoLichSu.duLieuNvLichSu.find(f => f.ten === nv.ten);
             if (nvCu) {
                 mtd = nvCu.mtdMC || 0;
             }
         }

         return {
             tenNhanVien: nv.ten,
             OFF: giaTriOff,
             chiSoHieuSuat: {
                 saleHomNay: nv.trangThai === 'Off' ? 0 : mcHomNay,
                 saleTrongThang: mtd,
                 chiTieu: nv.chiTieu
             },
             rawReport: nv.baoCao 
         };
     });

     return {
         ngayBaoCao: homNayStr,
         tongKetToanDoi: tongKetToanDoi,
         baoCaoFOS: baoCaoNhanVien
     };
};

import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';
import { hienThiThongBao, hienThiTaiTrang, anTaiTrang, dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien, apDungGiaoDien, luuCauHinhGiaoDien, apDungGiaoDienNgauNhien } from './theme.js';
import { thucHienGoiApi, ghiNhanTuongTacApi, lamMoiThongKeCsdl, datCheDoUngDung, layCheDoUngDung } from './api.js';
import { kiemTraTenTrongBaoCao, kiemTraChiSoMtd, taoCauTrucGuiBaoCao } from './report.js';

$(function() {
    // --- TRẠNG THÁI ỨNG DỤNG ---
    let danhSachNhanVien = []; 
    let baoCaoLichSuGanNhat = null; // Báo cáo ngày gần nhất TRƯỚC HÔM NAY
    let ngayBaoCaoLichSu = null; 
    let nhanVienHienTai = null;
    let nhanVienCanXoa = null;

    // --- HÀM HỖ TRỢ GIAO DIỆN ---
    const capNhatWidgetDb = (trucTuyen, slNv, slBaoCao, slTruyCap) => {
        const $cham = $('#cham-trang-thai-db');
        const $chu = $('#chu-trang-thai-db');
        const $nv = $('#so-luong-nv-db');
        const $bc = $('#so-luong-bao-cao-db');
        const $luong = $('#luong-truy-cap-api');

        if (trucTuyen) {
            $cham.removeClass('offline').addClass('online');
            $chu.text('Đã kết nối DB');
        } else {
            $cham.removeClass('online').addClass('offline');
            $chu.text('Chế độ Offline');
        }
        if (slNv !== null) $nv.text(`NV: ${slNv}`);
        if (slBaoCao !== null) $bc.text(`Rpt: ${slBaoCao}`);
        if (slTruyCap !== null) {
            $luong.text(`(${slTruyCap})`);
            $luong.removeClass('text-danger fw-bold').addClass('text-muted');
        }
    }

    const $vungDsNv = $('#vung-danh-sach-nv');
    const modalThemNv = new bootstrap.Modal('#modalThemNhanVien');
    const modalDanBaoCao = new bootstrap.Modal('#modalDanBaoCao');
    const modalSuaBaoCao = new bootstrap.Modal('#modalSuaBaoCao');
    const modalDanNhieuBaoCao = new bootstrap.Modal('#modalDanNhieuBaoCao');
    const modalXacNhanXoa = new bootstrap.Modal('#modalXacNhanXoa');
    const modalXemBaoCaoCu = new bootstrap.Modal('#modalXemBaoCaoCu');
    const modalCanhBaoMtd = new bootstrap.Modal('#modalCanhBaoMtd');

    const capNhatNutTaoBaoCao = () => {
        const daBaoCao = danhSachNhanVien.filter(nv => nv.trangThai !== 'Chưa báo cáo').length;
        const tongSo = danhSachNhanVien.length;
        $('#nut-tao-bao-cao').html(`Tạo & Lưu Báo Cáo (${daBaoCao}/${tongSo})`);
    };

    const hienThiDanhSachNhanVien = () => {
        if (danhSachNhanVien.length === 0) {
             $vungDsNv.html('<div class="text-center py-3 text-muted">Danh sách trống. Vui lòng thêm nhân viên.</div>');
             capNhatNutTaoBaoCao();
             return;
        }

        let html = '<div class="row g-2">';
        danhSachNhanVien.forEach(nv => {
            let lopNut = '';
            if (nv.kiemTraTen === false) {
                lopNut = 'name-mismatch';
            } else if (nv.trangThai === 'Đã báo cáo') {
                lopNut = 'reported';
            } else if (nv.trangThai === 'Off') {
                lopNut = 'off';
            }

            html += `
                <div class="col-6">
                    <div class="input-group">
                        <button class="btn fos-name-btn ${lopNut}" data-nv-id="${nv._id}" data-nv-ten="${nv.ten}">
                            ${nv.ten}
                        </button>
                        <button class="btn edit-fos-btn nut-sua-nhanh-nv" data-nv-ten="${nv.ten}" title="Sửa báo cáo của ${nv.ten}">
                            <i class="fa-solid fa-pen-to-square"></i>
                        </button>
                        <button class="btn delete-fos-btn nut-xoa-nv" data-nv-id="${nv._id}" data-nv-ten="${nv.ten}" title="Xóa ${nv.ten}">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </div>
            `;
        });
        html += '</div>';
        $vungDsNv.html(html);
        capNhatNutTaoBaoCao();
    };

    // --- LƯU TRỮ CỤC BỘ ---
    const luuVaoBoNhoTam = () => {
        const homNayStr = dinhDangNgayISO(new Date());
        const duLieu = {
            ngay: homNayStr,
            duLieuNv: danhSachNhanVien.map(n => ({
                _id: n._id,
                baoCao: n.baoCao,
                trangThai: n.trangThai,
                kiemTraTen: n.kiemTraTen
            })),
            vanBanKetQua: $('#vung-ket-qua-bao-cao').val()
        };
        localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify(duLieu));
    };

    const khoiPhuTuBoNhoTam = () => {
        const duLieuTho = localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO);
        if (!duLieuTho) return false;

        try {
            const duLieu = JSON.parse(duLieuTho);
            const homNayStr = dinhDangNgayISO(new Date());

            if (duLieu.ngay !== homNayStr) {
                localStorage.removeItem(KHOA_BO_NHO_TAM_CUC_BO);
                return false;
            }

            let soLuongKhoiPhu = 0;
            duLieu.duLieuNv.forEach(itemTam => {
                const nv = danhSachNhanVien.find(n => n._id === itemTam._id);
                if (nv && itemTam.baoCao) {
                    nv.baoCao = itemTam.baoCao;
                    nv.trangThai = itemTam.trangThai;
                    nv.kiemTraTen = itemTam.kiemTraTen;
                    soLuongKhoiPhu++;
                }
            });

            if (soLuongKhoiPhu > 0) {
                hienThiDanhSachNhanVien();
                if(duLieu.vanBanKetQua) {
                     $('#vung-ket-qua-bao-cao').val(duLieu.vanBanKetQua);
                     kiemTraChiSoMtd(danhSachNhanVien, baoCaoLichSuGanNhat, ngayBaoCaoLichSu);
                } else {
                     thucHienTaoBaoCao(null, true);
                }
                hienThiThongBao(`Đã khôi phục ${soLuongKhoiPhu} báo cáo từ bộ nhớ tạm.`, 'info');
                return true;
            }
        } catch (e) {
            console.error("Lỗi khôi phục cache", e);
            localStorage.removeItem(KHOA_BO_NHO_TAM_CUC_BO);
        }
        return false;
    };

    // --- TẢI DỮ LIỆU ---
    const taiDuLieuTuServer = async () => {
        hienThiTaiTrang("Đang tải dữ liệu hệ thống...");
        try {
            await ghiNhanTuongTacApi();
            const duLieuGốc = await thucHienGoiApi('nhanvien?h={"$orderby": {"Ten": 1}}');
            datCheDoUngDung('online');

            danhSachNhanVien = duLieuGốc.map(item => ({
                _id: item._id,
                ten: item.Ten,
                gioiTinh: item.GioiTinh,
                chiTieu: parseInt(item.ChiTieu, 10) || 50,
                baoCao: '',
                trangThai: 'Chưa báo cáo',
                kiemTraTen: null
            }));
            hienThiDanhSachNhanVien();
            khoiPhuTuBoNhoTam();
            anTaiTrang();

            $('#chi-bao-dang-luu').css('display', 'flex').find('span').text('Đang đồng bộ...');
            lamMoiThongKeCsdl(capNhatWidgetDb);
            await khoiPhuPhienLamViec();

        } catch (error) {
            console.warn("Dữ liệu dự phòng", error);
            datCheDoUngDung('offline');
            capNhatWidgetDb(false, null, null);

            try {
                const phanHoi = await fetch('fos.txt');
                const text = await phanHoi.text();
                danhSachNhanVien = text.split('\n')
                    .map(line => line.trim())
                    .filter(line => line.length > 0)
                    .map((line, index) => {
                        const parts = line.split('|');
                        return {
                            _id: `local_${index}`, ten: parts[0]?.trim() || 'Vô danh',
                            gioiTinh: parts[1]?.trim() || 'Nam', chiTieu: parseInt(parts[2]?.trim() || '50', 10),
                            baoCao: '', trangThai: 'Chưa báo cáo', kiemTraTen: null
                        };
                    });
                hienThiDanhSachNhanVien();
                khoiPhuTuBoNhoTam();
            } catch (fileErr) {
                 $vungDsNv.html('<div class="text-center py-3 text-danger">Lỗi kết nối</div>');
            }
        } finally {
            anTaiTrang(); 
            $('#chi-bao-dang-luu').hide().find('span').text('Đang lưu...');
        }
    };

    const khoiPhuPhienLamViec = async () => {
        const homNayStr = dinhDangNgayISO(new Date());

        // 1. Khôi phục dữ liệu đã nhập TRONG NGÀY hôm nay
        try {
            const bcHomNay = await thucHienGoiApi(`report?q={"ngayBaoCao": "${homNayStr}"}`);
            if (bcHomNay.length > 0) {
                const baoCao = bcHomNay[0];
                let soNvKhoiPhu = 0;

                baoCao.baoCaoFOS.forEach(item => {
                    const nv = danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
                    if (nv && nv.baoCao === '') {
                        if (item.OFF === 0 || item.OFF === '0') {
                            nv.trangThai = 'Đã báo cáo';
                            nv.baoCao = item.rawReport || `Fos ${item.tenNhanVien}\nTổng MC: ${item.chiSoHieuSuat.saleHomNay}\nMTD MC: ${item.chiSoHieuSuat.saleTrongThang}`;
                        } else {
                            nv.trangThai = 'Off';
                            const lyDo = (item.OFF === 1 || item.OFF === '1') ? 'OFF' : item.OFF;
                            nv.baoCao = `Fos ${item.tenNhanVien} ${lyDo}`;
                        }
                        soNvKhoiPhu++;
                    }
                });

                if (soNvKhoiPhu > 0) {
                    hienThiDanhSachNhanVien();
                }
            }
        } catch (e) { console.warn("Lỗi khôi phục phiên hôm nay", e); }

        // 2. Tải mốc lịch sử (ngày gần nhất TRƯỚC HÔM NAY) để làm mốc MTD chuẩn
        try {
            const truyVanLichSu = `{"ngayBaoCao": {"$lt": "${homNayStr}"}}`;
            const sapXepLichSu = `{"$orderby": {"ngayBaoCao": -1}}`;
            const dsBcCu = await thucHienGoiApi(`report?q=${truyVanLichSu}&h=${sapXepLichSu}&max=1`);

            if (dsBcCu.length > 0) {
                baoCaoLichSuGanNhat = dsBcCu[0];
                ngayBaoCaoLichSu = baoCaoLichSuGanNhat.ngayBaoCao;
                const ngayHienThi = dinhDangNgayHienThi(ngayBaoCaoLichSu);

                baoCaoLichSuGanNhat.duLieuNvLichSu = baoCaoLichSuGanNhat.baoCaoFOS.map(item => ({
                    ten: item.tenNhanVien,
                    mtdMC: item.chiSoHieuSuat.saleTrongThang
                }));

                let textBcCu = `Dữ liệu lịch sử mốc ngày ${ngayHienThi}:\n`;
                baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => {
                     textBcCu += `${n.ten}: MTD ${n.mtdMC || 0}\n`;
                });
                $('#vung-ket-qua-bao-cao-cu').val(textBcCu);

                // Tự động tính toán lại báo cáo dựa trên mốc lịch sử mới tải
                thucHienTaoBaoCao(null, true);
            }
        } catch (e) { console.warn("Lỗi tải lịch sử", e); }
    };

    const luuBaoCaoLenServer = async (cauTruc, chayNgam = false) => {
        if (layCheDoUngDung() === 'offline') {
            hienThiThongBao("Đã lưu cục bộ (Offline).", "info");
            return;
        }

        if (chayNgam) $('#chi-bao-dang-luu').css('display', 'flex'); else hienThiTaiTrang("Đang lưu báo cáo...");

        try {
            const kiemTra = await thucHienGoiApi(`report?q={"ngayBaoCao": "${cauTruc.ngayBaoCao}"}`);
            if (kiemTra.length > 0) {
                await thucHienGoiApi(`report/${kiemTra[0]._id}`, 'PUT', cauTruc);
                hienThiThongBao("Đã cập nhật báo cáo thành công!");
            } else {
                await thucHienGoiApi('report', 'POST', cauTruc);
                hienThiThongBao("Đã tạo báo cáo mới!");
            }
            lamMoiThongKeCsdl(capNhatWidgetDb);
        } catch (error) {
            hienThiThongBao(`Lỗi lưu DB: ${error.message}`, 'error');
        } finally {
            if (chayNgam) $('#chi-bao-dang-luu').hide(); else anTaiTrang();
        }
    };

    // --- LOGIC CHÍNH ---
    const xuLyBaoCaoHangLoat = () => {
        const vanBan = $('#noi-dung-nhieu-bao-cao-nhap').val().trim();
        if (!vanBan) {
            hienThiThongBao('Vui lòng dán nội dung báo cáo.', 'error');
            return;
        }
        const khoiBaoCao = vanBan.split(/(?=^Fos\s)/im); 
        let slThanhCong = 0;
        let dsTenLoi = [];
        const dsTenDaCapNhat = new Set();

        khoiBaoCao.forEach(khoi => {
            const khoiTrim = khoi.trim();
            if (khoiTrim.length === 0) return;
            const matchTen = khoiTrim.match(/^Fos\s+([^\s]+)/i);
            const tenTrongBc = matchTen ? matchTen[1] : null;

            let nvTimThay = danhSachNhanVien.find(n => {
                const tenEscape = n.ten.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
                const regexTen = new RegExp(`^Fos\\s+${tenEscape}(?=\\s|$)`, 'i');
                return regexTen.test(khoiTrim);
            });

            if (nvTimThay) {
                nvTimThay.baoCao = khoiTrim;
                nvTimThay.trangThai = 'Đã báo cáo';
                kiemTraTenTrongBaoCao(nvTimThay, khoiTrim);
                if (!dsTenDaCapNhat.has(nvTimThay.ten)) {
                    slThanhCong++;
                    dsTenDaCapNhat.add(nvTimThay.ten);
                }
            } else if (tenTrongBc) {
                 dsTenLoi.push(tenTrongBc);
            }
        });

        modalDanNhieuBaoCao.hide();
        hienThiDanhSachNhanVien();
        luuVaoBoNhoTam(); 

        let thongBao = `Xử lý hoàn tất!<br>- Thành công: ${slThanhCong} nhân viên.`;
        if (dsTenLoi.length > 0) {
            const tenDuyNhat = [...new Set(dsTenLoi)];
            thongBao += `<br>- Không nhận diện được: ${tenDuyNhat.join(', ')}.`;
        }
        hienThiThongBao(thongBao, dsTenLoi.length > 0 ? 'info' : 'success');
        $('#noi-dung-nhieu-bao-cao-nhap').val('');
    };

    const thucHienTaoBaoCao = (e, chiXem = false) => {
        danhSachNhanVien.sort((a, b) => b.chiTieu - a.chiTieu);
        hienThiDanhSachNhanVien();

        const quanLy = 'TNH';
        const ngayHienThi = dinhDangNgayHienThi(new Date());

        let tMC = 0, tNTB = 0, tETB = 0, nvActive = 0, tPos = 0, tAE = 0;
        const chiTieuPos = danhSachNhanVien.length * 3;
        let dsChiTiet = [];

        const banDoLichSu = new Map();
        if (baoCaoLichSuGanNhat && baoCaoLichSuGanNhat.duLieuNvLichSu) {
            baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => banDoLichSu.set(n.ten, n));
        }

        danhSachNhanVien.forEach(nv => {
            const bieuTuong = nv.gioiTinh === 'Nữ' ? '👵' : '👨';
            const bc = nv.baoCao;

            let mtd = trichXuatSoLieu(bc, 'MTD MC');
            let ntb = trichXuatSoLieu(bc, 'NTB'), etb = trichXuatSoLieu(bc, 'ETB');
            let mcNay = ntb + etb;
            if (mcNay === 0) mcNay = trichXuatSoLieu(bc, ['Tổng MC', 'MC']);

            // LOGIC MTD: Ưu tiên mốc lịch sử (trước hôm nay) nếu nghỉ hoặc 0 sale mà ko nhập mới
            if ((nv.trangThai === 'Off' || mcNay === 0) && mtd === 0) {
                const nvLichSu = banDoLichSu.get(nv.ten);
                mtd = nvLichSu ? (nvLichSu.mtdMC || 0) : 0;
            }

            if (nv.trangThai === 'Off') {
                const matchLyDo = bc.match(/^Fos\s+\S+\s+(.*)$/i);
                const lyDo = (matchLyDo && matchLyDo[1] && matchLyDo[1].toUpperCase() !== 'OFF') ? matchLyDo[1] : 'OFF';
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${lyDo}/${mtd}/${nv.chiTieu}`);
            } else {
                nvActive++;
                const pos = trichXuatSoLieu(bc, 'Pos'), ae = trichXuatSoLieu(bc, ['AE+', 'AE Plus']);
                tMC += mcNay; tNTB += ntb; tETB += etb; tPos += pos; tAE += ae;
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${mcNay}/${mtd}/${nv.chiTieu}`);
            }
        });

        const nsbqNTB = (nvActive > 0) ? (tNTB / nvActive).toFixed(2) : '0.00';
        const nsbqETB = (nvActive > 0) ? (tETB / nvActive).toFixed(2) : '0.00';

        let ketQua = `${quanLy} ngày ${ngayHienThi}\n`;
        ketQua += `🔥${danhSachNhanVien.length} FOS – ${tMC} MC\n✅NTB: ${tNTB}\n✅NSBQ NTB: ${nsbqNTB}\n✅ETB: ${tETB}\n✅NSBQ ETB: ${nsbqETB}\n✅AE+: ${tAE}\n✅Pos: ${tPos}/${chiTieuPos}\n\n`;
        ketQua += `⭐️Active ${nvActive}/${danhSachNhanVien.length}\n${dsChiTiet.join('\n')}`;

        $('#vung-ket-qua-bao-cao').val(ketQua);

        // Luôn kiểm tra sai lệch MTD với mốc lịch sử (ngày gần nhất TRƯỚC HÔM NAY)
        kiemTraChiSoMtd(danhSachNhanVien, baoCaoLichSuGanNhat, ngayBaoCaoLichSu);

        if (!chiXem) {
            const thongKe = { 
                tongFOS: danhSachNhanVien.length, tongMC: tMC, tongNTB: tNTB, nsbqNTB, 
                tongETB: tETB, nsbqETB, tongPosThucHien: tPos, posChiTieu: chiTieuPos, 
                activeFOS: nvActive, tongAEPlus: tAE 
            };
            const cauTruc = taoCauTrucGuiBaoCao(danhSachNhanVien, baoCaoLichSuGanNhat, thongKe);
            luuBaoCaoLenServer(cauTruc, true);
        }
    };

