                 danhSachNhanVien.push({ _id: `local_${Date.now()}`, ten, gioiTinh: gt, chiTieu: ct, baoCao: '', trangThai: 'Chưa báo cáo', kiemTraTen: null });
                 modalThemNv.hide(); hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); return;
            }
