/* Lớp phủ tải trang (Loading Overlay) */
#lop-phu-tai-trang {
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    background: rgba(0, 0, 0, 0.7);
    backdrop-filter: blur(10px);
    display: none; 
    flex-direction: column;
    justify-content: center;
    align-items: center;
    z-index: 9999;
    color: white;
}

body {
    font-family: 'Poppins', sans-serif;
    background-color: var(--bg-gradient);
    background-image: var(--bg-image), var(--bg-gradient);
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: var(--text-primary);
    transition: background 0.4s ease, color 0.4s ease;
    min-height: 100vh;
}

/* Nút Cài Đặt (Settings Button) */
.settings-container {
    position: fixed;
    top: 25px;
    right: 25px;
    z-index: 1100;
}

#nut-cai-dat {
    cursor: pointer;
    font-size: 1.5rem;
    color: var(--accent-blue);
    background: var(--card-bg);
    width: 50px;
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    box-shadow: 0 8px 32px rgba(0,0,0,0.15);
    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275), background 0.3s ease;
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.1);
}
#nut-cai-dat:hover { transform: rotate(90deg) scale(1.1); }

/* Fix Dropdown & Submenu - Lỗi hàng */
.dropdown-menu {
    border-radius: 1rem;
    padding: 0.5rem;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: var(--card-bg);
    backdrop-filter: blur(20px);
    box-shadow: 0 15px 45px rgba(0,0,0,0.2) !important;
}

.dropdown-item {
    border-radius: 0.5rem;
    padding: 0.6rem 1rem;
    color: var(--text-primary);
    transition: all 0.2s ease;
}
.dropdown-item:hover {
    background-color: rgba(0, 122, 255, 0.1);
    color: var(--accent-blue);
}

.dropdown-submenu {
    position: relative;
}

/* Menu con hiển thị khi hover */
.dropdown-submenu > .dropdown-menu {
    top: 0;
    left: auto;
    right: 100%; /* Mở sang trái vì nút ở góc phải màn hình */
    margin-top: -5px;
    margin-right: 0.5rem;
    display: none;
}

.dropdown-submenu:hover > .dropdown-menu {
    display: block;
}

/* Mũi tên chỉ hướng cho menu con */
.dropdown-toggle::after {
    display: inline-block;
    margin-left: 0.5em;
    vertical-align: 0.255em;
    content: "";
    border-top: 0.3em solid;
    border-right: 0.3em solid transparent;
    border-bottom: 0;
    border-left: 0.3em solid transparent;
}

.dropdown-submenu > .dropdown-toggle::after {
    transform: rotate(90deg); /* Xoay mũi tên sang trái */
    float: left;
    margin-top: 0.5rem;
    margin-right: 0.5rem;
    margin-left: 0;
}

/* Main Layout UI */
.main-title { font-weight: 700; color: var(--main-title-color); letter-spacing: -1px; }

.card, .modal-content {
    background: var(--card-bg);
    backdrop-filter: blur(25px) saturate(200%);
