    --card-bg: rgba(45, 52, 54, 0.85);
    --text-primary: #fab1a0;
    --accent-blue: #a29bfe;
}

/* Serene Nature */
body.theme-nature-light {
    --bg-gradient: linear-gradient(135deg, #e8f5e9 0%, #c8e6c9 100%);
    --accent-blue: #2e7d32;
    --card-bg: rgba(255, 255, 255, 0.85);
}
body.theme-nature-dark {
    --bg-gradient: linear-gradient(135deg, #1b5e20 0%, #000000 100%);
    --card-bg: rgba(27, 94, 32, 0.9);
    --text-primary: #c8e6c9;
    --accent-blue: #81c784;
}

/* Gaming Zone */
body.theme-gaming-light {
    --bg-gradient: linear-gradient(135deg, #00d2ff 0%, #3a7bd5 100%);
    --accent-blue: #000000;
    --card-bg: rgba(255, 255, 255, 0.9);
}
body.theme-gaming-dark {
    --bg-gradient: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%);
    --accent-blue: #00d2ff;
    --accent-green: #39ff14;
    --accent-red: #ff0055;
    --card-bg: rgba(0, 0, 0, 0.85);
    --text-primary: #00ffcc;
}

/* Carbon Fiber */
body.theme-carbon-light {
    --bg-gradient: linear-gradient(135deg, #e0e0e0 0%, #ffffff 100%);
    --accent-blue: #333;
    --card-bg: rgba(255, 255, 255, 0.95);
}
body.theme-carbon-dark {
    --bg-gradient: radial-gradient(circle, #2c3e50 0%, #000000 100%);
    --card-bg: rgba(30, 30, 30, 0.95);
    --text-primary: #ecf0f1;
    --accent-blue: #bdc3c7;
    --btn-fos-bg: #222;
}

/* Chic & Modern */
body.theme-chic-light {
    --bg-gradient: linear-gradient(to right, #fdfbfb 0%, #ebedee 100%);
    --accent-blue: #2c3e50;
    --card-bg: #ffffff;
}
body.theme-chic-dark {
    --bg-gradient: linear-gradient(to right, #434343 0%, #000000 100%);
    --card-bg: #1a1a1a;
    --text-primary: #ffffff;
    --accent-blue: #d4af37;
}

/* --- BASE UI STYLES --- */

#lop-phu-tai-trang {
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    background: rgba(0, 0, 0, 0.7);
    backdrop-filter: blur(10px);
    display: none; 
    flex-direction: column;
    justify-content: center;
    align-items: center;
    z-index: 9999;
    color: white;
}

body {
    font-family: 'Poppins', sans-serif;
    background-color: var(--bg-gradient);
    background-image: var(--bg-image), var(--bg-gradient);
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: var(--text-primary);
    transition: background 0.4s ease, color 0.4s ease;
    min-height: 100vh;
}

/* Settings Button */
.settings-container {
    position: fixed;
    top: 25px;
    right: 25px;
    z-index: 1100;
}

#nut-cai-dat {
    cursor: pointer;
    font-size: 1.5rem;
    color: var(--accent-blue);
    background: var(--card-bg);
    width: 50px;
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    box-shadow: 0 8px 32px rgba(0,0,0,0.15);
    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275), background 0.3s ease;
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.1);
}
#nut-cai-dat:hover { transform: rotate(90deg) scale(1.1); background: rgba(255,255,255,0.9); }

/* Fix Dropdown & Submenu Disappearing Bug */
.dropdown-menu {
    border-radius: 1rem;
    padding: 0.5rem;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: var(--card-bg);
    backdrop-filter: blur(25px);
    box-shadow: 0 15px 45px rgba(0,0,0,0.2) !important;
}

.dropdown-item {
    border-radius: 0.6rem;
    padding: 0.6rem 1rem;
    color: var(--text-primary);
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
}
.dropdown-item:hover {
    background-color: rgba(0, 122, 255, 0.1);
    color: var(--accent-blue);
}

.dropdown-submenu {
    position: relative;
}

/* CRITICAL: Fix disappearing on hover */
.dropdown-submenu > .dropdown-menu {
    top: 0;
    left: auto;
    right: 100%;
    margin-top: -5px;
    margin-right: 0px; /* Bridge will handle the gap */
    display: none;
}

/* The 'Bridge' pseudo-element to prevent closing when moving mouse to submenu */
.dropdown-submenu:hover > .dropdown-menu {
    display: block;
}
.dropdown-submenu:hover > .dropdown-menu::before {
    content: "";
    position: absolute;
    top: 0;
    right: -20px;
    width: 25px;
    height: 100%;
    background: transparent;
    z-index: -1;
}

.dropdown-toggle::after {
    display: inline-block;
    margin-left: 0.5em;
    vertical-align: 0.255em;
    content: "";
    border-top: 0.3em solid;
    border-right: 0.3em solid transparent;
    border-bottom: 0;
    border-left: 0.3em solid transparent;
}

.dropdown-submenu > .dropdown-toggle::after {
    transform: rotate(90deg);
    float: left;
    margin-top: 0.5rem;
    margin-right: 0.5rem;
    margin-left: 0;
}

/* Layout Elements */
.main-title { font-weight: 700; color: var(--main-title-color); letter-spacing: -1px; }

.card, .modal-content {
    background: var(--card-bg);
    backdrop-filter: blur(25px) saturate(200%);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 1.5rem;
}

#vung-danh-sach-nv {
    max-height: 420px;
    overflow-y: auto;
    padding: 12px;
    margin-bottom: 20px;
    border-radius: 1.25rem;
    background: rgba(0,0,0,0.03);
}

.nut-ten-nv {
    background-color: var(--btn-fos-bg);
    border: 1px solid var(--btn-fos-border);
    color: var(--text-primary);
    flex: 1;
    text-align: left;
    font-weight: 600;
    border-radius: 0.75rem 0 0 0.75rem !important;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    padding: 10px 15px;
}
.nut-ten-nv.da-bao-cao { background-color: var(--accent-green) !important; color: white !important; border-color: var(--accent-green); }
.nut-ten-nv.nghi { background-color: var(--accent-gray) !important; color: white !important; text-decoration: line-through; opacity: 0.8; }
.nut-ten-nv.sai-ten { background-color: var(--accent-red) !important; color: white !important; }

.nut-sua-nv { background-color: var(--accent-blue); color: white; width: 44px; border: none; }
.nut-xoa-nv { background-color: var(--accent-red); color: white; border-radius: 0 0.75rem 0.75rem 0 !important; width: 44px; border: none; }

.db-status-widget {
    position: fixed; bottom: 15px; left: 15px;
    background: var(--card-bg); padding: 10px 18px; border-radius: 18px;
    font-size: 0.7rem; z-index: 1000; box-shadow: 0 10px 30px rgba(0,0,0,0.12);
    backdrop-filter: blur(20px); border: 1px solid rgba(255, 255, 255, 0.15);
    display: flex; flex-direction: column; gap: 4px;
    min-width: 220px;
}

.status-dot {
    height: 8px; width: 8px; border-radius: 50%; display: inline-block; margin-right: 6px;
}
.status-dot.online { background-color: var(--accent-green); box-shadow: 0 0 8px var(--accent-green); }
.status-dot.offline { background-color: var(--accent-red); box-shadow: 0 0 8px var(--accent-red); }

#chi-bao-dang-luu {
    position: fixed; bottom: 85px; right: 20px;
    z-index: 2000; background: var(--accent-blue); padding: 12px 24px;
    border-radius: 50px; box-shadow: 0 10px 25px rgba(0,122,255,0.3);
    display: none; align-items: center; gap: 10px; color: white;
    font-size: 0.9rem; font-weight: 500;
}

import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';
import { hienThiThongBao, hienThiTaiTrang, anTaiTrang, dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien, apDungGiaoDien, luuCauHinhGiaoDien, apDungGiaoDienNgauNhien } from './theme.js';
import { thucHienGoiApi, ghiNhanTuongTacApi, lamMoiThongKeCsdl, datCheDoUngDung, layCheDoUngDung } from './api.js';
import { kiemTraTenTrongBaoCao, taoCauTrucGuiBaoCao } from './report.js';

$(function() {
    // --- TRẠNG THÁI ỨNG DỤNG ---
    let danhSachNhanVien = []; 
    let baoCaoLichSuGanNhat = null; 
    let ngayBaoCaoLichSu = null; 
    let nhanVienHienTai = null;
    let nhanVienCanXoa = null;

    // --- KHỞI TẠO MODAL BOOTSTRAP ---
    const modalThemNv = new bootstrap.Modal('#modal-them-nhan-vien');
    const modalDanBaoCao = new bootstrap.Modal('#modal-dan-bao-cao');
    const modalSuaBaoCao = new bootstrap.Modal('#modal-sua-bao-cao');
    const modalDanNhieuBaoCao = new bootstrap.Modal('#modal-dan-nhieu-bao-cao');
    const modalXacNhanXoa = new bootstrap.Modal('#modal-xac-nhan-xoa');
    const modalXemBaoCaoCu = new bootstrap.Modal('#modal-xem-bao-cao-cu');

    // --- CẬP NHẬT THÔNG TIN BUILD ---
    const phienBanBuild = "v1.3.8-stable";
    const thoiGianBuildStr = "2025.02.21 21:35"; 
    $('#phien-ban-build-text').text(phienBanBuild);
    $('#thoi-gian-build-text').text(`Build: ${thoiGianBuildStr}`);

    const capNhatWidgetDb = (trucTuyen, slNv, slBaoCao, slTruyCap) => {
        const $cham = $('#cham-trang-thai-db');
        const $chu = $('#chu-trang-thai-db');
        const $nv = $('#so-luong-nv-db');
        const $bc = $('#so-luong-bao-cao-db');
        const $luong = $('#luong-truy-cap-api');

        if (trucTuyen) {
            $cham.removeClass('offline').addClass('online');
            $chu.text('RestDB Online');
        } else {
            $cham.removeClass('online').addClass('offline');
            $chu.text('Chế độ Offline');
        }
        if (slNv !== null) $nv.text(`NV: ${slNv}`);
        if (slBaoCao !== null) $bc.text(`Rpt: ${slBaoCao}`);
        if (slTruyCap !== null) $luong.text(`(${slTruyCap})`);
    }

    const $vungDsNv = $('#vung-danh-sach-nv');

    const capNhatNutTaoBaoCao = () => {
        const daBaoCao = danhSachNhanVien.filter(nv => nv.trangThai !== 'Chưa báo cáo').length;
        const tongSo = danhSachNhanVien.length;
        $('#nut-tao-bao-cao').html(`Tạo & Lưu Báo Cáo (${daBaoCao}/${tongSo})`);
    };

    const hienThiDanhSachNhanVien = () => {
        if (danhSachNhanVien.length === 0) {
             $vungDsNv.html('<div class="text-center py-3 text-muted">Danh sách trống.</div>');
             capNhatNutTaoBaoCao();
             return;
        }

        let html = '<div class="row g-2">';
        danhSachNhanVien.forEach(nv => {
            let lopNut = 'nut-ten-nv btn';
            if (nv.kiemTraTen === false) lopNut += ' sai-ten';
            else if (nv.trangThai === 'Đã báo cáo') lopNut += ' da-bao-cao';
            else if (nv.trangThai === 'Off') lopNut += ' nghi';

            html += `
                <div class="col-6">
                    <div class="input-group shadow-sm" style="border-radius: 0.75rem; overflow: hidden;">
                        <button class="${lopNut}" data-nv-ten="${nv.ten}" title="${nv.ten}">
                            ${nv.ten}
                        </button>
                        <button class="btn nut-sua-nv nut-sua-nhanh-nv" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-pen-to-square"></i>
                        </button>
                        <button class="btn nut-xoa-nv nut-xoa-nv-kich-hoat" data-nv-id="${nv._id}" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </div>
            `;
        });
        html += '</div>';
        $vungDsNv.html(html);
        capNhatNutTaoBaoCao();
    };

    const luuVaoBoNhoTam = () => {
        const homNayStr = dinhDangNgayISO(new Date());
        const duLieu = {
            ngay: homNayStr,
            duLieuNv: danhSachNhanVien.map(n => ({
                _id: n._id, baoCao: n.baoCao, trangThai: n.trangThai, kiemTraTen: n.kiemTraTen
            })),
            vanBanKetQua: $('#vung-ket-qua-bao-cao').val()
        };
        localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify(duLieu));
    };

    const khoiPhuTuBoNhoTam = () => {
        const duLieuTho = localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO);
        if (!duLieuTho) return false;
        try {
            const duLieu = JSON.parse(duLieuTho);
            if (duLieu.ngay !== dinhDangNgayISO(new Date())) {
                localStorage.removeItem(KHOA_BO_NHO_TAM_CUC_BO);
                return false;
            }
            duLieu.duLieuNv.forEach(itemTam => {
                const nv = danhSachNhanVien.find(n => n._id === itemTam._id);
                if (nv && itemTam.baoCao) {
                    nv.baoCao = itemTam.baoCao; 
                    nv.trangThai = itemTam.trangThai; 
                    nv.kiemTraTen = itemTam.kiemTraTen;
                }
            });
            hienThiDanhSachNhanVien();
            if(duLieu.vanBanKetQua) $('#vung-ket-qua-bao-cao').val(duLieu.vanBanKetQua);
            return true;
        } catch (e) { return false; }
    };

    const taiDuLieuTuServer = async () => {
        hienThiTaiTrang("Đang tải danh sách FOS...");
        try {
            ghiNhanTuongTacApi().catch(() => {});

            const duLieuGoc = await thucHienGoiApi('nhanvien?h={"$orderby": {"Ten": 1}}');
            datCheDoUngDung('online');
            danhSachNhanVien = duLieuGoc.map(item => ({
                _id: item._id, ten: item.Ten, gioiTinh: item.GioiTinh,
                chiTieu: parseInt(item.ChiTieu, 10) || 50, baoCao: '',
                trangThai: 'Chưa báo cáo', kiemTraTen: null
            }));

            hienThiDanhSachNhanVien();

            // Ẩn loader ngay khi danh sách nhân viên hiện ra để user thao tác ngay
            anTaiTrang(); 

            // Các công việc nền tiếp tục chạy ngầm sau khi user đã có thể thao tác
            khoiPhuTuBoNhoTam();
            lamMoiThongKeCsdl(capNhatWidgetDb).catch(() => {});
            khoiPhuPhienLamViec().catch(() => {});

        } catch (error) {
            datCheDoUngDung('offline');
            hienThiThongBao("Đang hoạt động ngoại tuyến", "info");
            try {
                const phanHoi = await fetch('fos.txt');
                const text = await phanHoi.text();
                danhSachNhanVien = text.split('\n').filter(l => l.trim()).map((line, index) => {
                    const parts = line.split('|');
                    return {
                        _id: `local_${index}`, ten: parts[0]?.trim(), gioiTinh: parts[1]?.trim(), 
                        chiTieu: parseInt(parts[2]?.trim() || '50'), baoCao: '', 
                        trangThai: 'Chưa báo cáo', kiemTraTen: null
                    };
                });
                hienThiDanhSachNhanVien();
                anTaiTrang();
                khoiPhuTuBoNhoTam();
            } catch (e) {
                anTaiTrang();
            }
        }
    };

    const khoiPhuPhienLamViec = async () => {
        const homNayStr = dinhDangNgayISO(new Date());

        try {
            const bcHomNay = await thucHienGoiApi(`report?q={"ngayBaoCao": "${homNayStr}"}`);
            if (bcHomNay.length > 0) {
                bcHomNay[0].baoCaoFOS.forEach(item => {
                    const nv = danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
                    if (nv && nv.baoCao === '') {
                        nv.trangThai = (item.OFF === 0 || item.OFF === '0') ? 'Đã báo cáo' : 'Off';
                        nv.baoCao = item.rawReport || `Fos ${item.tenNhanVien} ${nv.trangThai === 'Off' ? 'OFF' : ''}`;
                    }
                });
                hienThiDanhSachNhanVien();
            }
        } catch (e) {}

        // Lấy mốc lịch sử thực sự cũ hơn hôm nay
        try {
            const truyVanLichSu = `{"ngayBaoCao": {"$lt": "${homNayStr}"}}`;
            const sapXepLichSu = `{"$orderby": {"ngayBaoCao": -1}}`;
            const dsBcCu = await thucHienGoiApi(`report?q=${truyVanLichSu}&h=${sapXepLichSu}&max=1`);

            if (dsBcCu.length > 0) {
                const bcLichSu = dsBcCu[0];
                baoCaoLichSuGanNhat = bcLichSu;
                ngayBaoCaoLichSu = bcLichSu.ngayBaoCao;
                baoCaoLichSuGanNhat.duLieuNvLichSu = bcLichSu.baoCaoFOS.map(item => ({
                    ten: item.tenNhanVien, 
                    mtdMC: item.chiSoHieuSuat.saleTrongThang
                }));

                let txt = `Chốt mốc ngày ${dinhDangNgayHienThi(ngayBaoCaoLichSu)}:\n`;
                baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => txt += `${n.ten}: MTD ${n.mtdMC}\n`);
                $('#vung-ket-qua-bao-cao-cu').val(txt);
                thucHienTaoBaoCao(null, true);
            }
        } catch (e) {}
    };

    const luuBaoCaoLenServer = async (cauTruc, chayNgam = false) => {
        if (layCheDoUngDung() === 'offline') return;
        if (chayNgam) $('#chi-bao-dang-luu').css('display', 'flex');
        try {
            const kiemTra = await thucHienGoiApi(`report?q={"ngayBaoCao": "${cauTruc.ngayBaoCao}"}`);
            if (kiemTra.length > 0) await thucHienGoiApi(`report/${kiemTra[0]._id}`, 'PUT', cauTruc);
            else await thucHienGoiApi('report', 'POST', cauTruc);
            lamMoiThongKeCsdl(capNhatWidgetDb);
        } catch (error) {} finally { setTimeout(() => $('#chi-bao-dang-luu').fadeOut(), 1000); }
    };

    const thucHienTaoBaoCao = (e, chiXem = false) => {
        danhSachNhanVien.sort((a, b) => b.chiTieu - a.chiTieu);
        hienThiDanhSachNhanVien();
        const quanLy = 'TNH';
        const ngayHienThi = dinhDangNgayHienThi(new Date());
        let tMC = 0, tNTB = 0, tETB = 0, nvActive = 0, tPos = 0, tAE = 0;
        let dsChiTiet = [];
        const banDoLichSu = new Map();
        if (baoCaoLichSuGanNhat?.duLieuNvLichSu) baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => banDoLichSu.set(n.ten, n));

        danhSachNhanVien.forEach(nv => {
            const bieuTuong = nv.gioiTinh === 'Nữ' ? '👵' : '👨';
            const bc = nv.baoCao;
            let mtd = trichXuatSoLieu(bc, 'MTD MC');
            let ntb = trichXuatSoLieu(bc, 'NTB'), etb = trichXuatSoLieu(bc, 'ETB');
            let mcNay = ntb + etb;
            if (mcNay === 0) mcNay = trichXuatSoLieu(bc, ['Tổng MC', 'MC']);

            if ((nv.trangThai === 'Off' || mcNay === 0) && mtd === 0 && baoCaoLichSuGanNhat) {
                const nvLichSu = banDoLichSu.get(nv.ten);
                mtd = nvLichSu ? (nvLichSu.mtdMC || 0) : 0;
            }

            if (nv.trangThai === 'Off') {
                const matchLyDo = bc.match(/^Fos\s+\S+\s+(.*)$/i);
                const lyDo = (matchLyDo && matchLyDo[1] && matchLyDo[1].toUpperCase() !== 'OFF') ? matchLyDo[1] : 'OFF';
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${lyDo}/${mtd}/${nv.chiTieu}`);
            } else {
                nvActive++;
                tMC += mcNay; tNTB += ntb; tETB += etb;
                tPos += trichXuatSoLieu(bc, 'Pos'); tAE += trichXuatSoLieu(bc, ['AE+', 'AE Plus']);
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${mcNay}/${mtd}/${nv.chiTieu}`);
            }
        });

        const nsbqNTB = (nvActive > 0) ? (tNTB / nvActive).toFixed(2) : '0.00';
        const nsbqETB = (nvActive > 0) ? (tETB / nvActive).toFixed(2) : '0.00';
        let ketQua = `${quanLy} ngày ${ngayHienThi}\n🔥${danhSachNhanVien.length} FOS – ${tMC} MC\n✅NTB: ${tNTB}\n✅NSBQ NTB: ${nsbqNTB}\n✅ETB: ${tETB}\n✅NSBQ ETB: ${nsbqETB}\n✅AE+: ${tAE}\n✅Pos: ${tPos}/${danhSachNhanVien.length * 3}\n\n⭐️Active ${nvActive}/${danhSachNhanVien.length}\n${dsChiTiet.join('\n')}`;
        $('#vung-ket-qua-bao-cao').val(ketQua);

        if (!chiXem) {
            const thongKe = { tongFOS: danhSachNhanVien.length, tongMC: tMC, tongNTB: tNTB, nsbqNTB, tongETB: tETB, nsbqETB, tongPosThucHien: tPos, posChiTieu: danhSachNhanVien.length * 3, activeFOS: nvActive, tongAEPlus: tAE };
            luuBaoCaoLenServer(taoCauTrucGuiBaoCao(danhSachNhanVien, baoCaoLichSuGanNhat, thongKe), true);
        }
    };

    // --- SỰ KIỆN GIAO DIỆN ---
    $('body').on('click', '.lua-chon-giao-dien', function(e) {
        e.preventDefault();
        const theme = $(this).data('theme');
        const mode = $(this).data('mode');
        const lop = `theme-${theme}-${mode}`;
        apDungGiaoDien(lop); 
        luuCauHinhGiaoDien(lop);
        hienThiThongBao(`Giao diện: ${theme} ${mode}`);
    });

    $('#nut-giao-dien-ngau-nhien').on('click', e => { 
        e.preventDefault(); 
        luuCauHinhGiaoDien('random'); 
        apDungGiaoDienNgauNhien(); 
    });

    $('#nut-luu-nv-moi').on('click', async () => {
        const ten = $('#ten-nv-modal').val().trim(), gt = $('#gioi-tinh-nv-modal').val(), ct = parseInt($('#chi-tieu-nv-modal').val()) || 0;
        if (ten && !danhSachNhanVien.some(n => n.ten.toLowerCase() === ten.toLowerCase())) {
            hienThiTaiTrang("Đang lưu nhân viên...");
            try { await thucHienGoiApi('nhanvien', 'POST', { Ten: ten, GioiTinh: gt, ChiTieu: ct }); modalThemNv.hide(); taiDuLieuTuServer(); }
            catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); }
        }
    });

    $vungDsNv.on('click', '.nut-xoa-nv-kich-hoat', function() {
        nhanVienCanXoa = { id: $(this).data('nv-id'), ten: $(this).data('nv-ten') };
        $('#noi-dung-xac-nhan-xoa').text(`Xoá nhân viên "${nhanVienCanXoa.ten}"?`);
        modalXacNhanXoa.show();
    });

    $('#nut-xac-nhan-xoa-vinh-vien').on('click', async () => {
        if (!nhanVienCanXoa) return;
        hienThiTaiTrang("Đang xoá vĩnh viễn...");
        try { await thucHienGoiApi(`nhanvien/${nhanVienCanXoa.id}`, 'DELETE'); taiDuLieuTuServer(); }
        catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); modalXacNhanXoa.hide(); }
    });

    $vungDsNv.on('click', '.nut-ten-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { 
            $('#modalDanBaoCaoLabel').text(`Báo cáo của ${nhanVienHienTai}`); 
            $('#noi-dung-bao-cao-nhap').val(nv.baoCao); 
            modalDanBaoCao.show(); 
        }
    });

    $('#nut-luu-bao-cao-don').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const nd = $('#noi-dung-bao-cao-nhap').val();
            nv.baoCao = nd; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, nd);
            hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide();
        }
    });

    $('#nut-danh-dau-off').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} OFF`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $('#nut-xac-nhan-off-co-ly-do').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} ${$('#ly-do-off-nhap').val().trim() || 'OFF'}`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $vungDsNv.on('click', '.nut-sua-nhanh-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const bc = nv.baoCao;
            $('#tieu-de-modal-sua-bao-cao').text(`Sửa nhanh: ${nhanVienHienTai}`);
            $('#ntb-sua').val(trichXuatSoLieu(bc, 'NTB')); $('#etb-sua').val(trichXuatSoLieu(bc, 'ETB'));
            $('#pos-sua').val(trichXuatSoLieu(bc, 'Pos')); $('#aeplus-sua').val(trichXuatSoLieu(bc, ['AE+', 'AE Plus']));
            $('#mtd-sua').val(trichXuatSoLieu(bc, 'MTD MC'));
            modalSuaBaoCao.show();
        }
    });

    $('#nut-xac-nhan-sua-bao-cao').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const n = parseInt($('#ntb-sua').val()) || 0, e = parseInt($('#etb-sua').val()) || 0;
            nv.baoCao = `Fos ${nv.ten}\nTổng MC: ${n+e}\nNTB: ${n}\nETB: ${e}\nAE+: ${$('#aeplus-sua').val() || 0}\nPos: ${$('#pos-sua').val() || 0}\nMTD MC: ${$('#mtd-sua').val() || 0}`;
            nv.trangThai = 'Đã báo cáo'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalSuaBaoCao.hide();
        }
    });

    $('#nut-dan-tu-bo-nho').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-dan-hang-loat').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-nhieu-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-xu-ly-nhieu-bao-cao').on('click', () => {
        const vanBan = $('#noi-dung-nhieu-bao-cao-nhap').val().trim();
        if (!vanBan) return;
        const khoiBaoCao = vanBan.split(/(?=^Fos\s)/im); 
        khoiBaoCao.forEach(khoi => {
            const khoiTrim = khoi.trim();
            const nv = danhSachNhanVien.find(n => {
                const tenEscape = n.ten.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
                return new RegExp(`^Fos\\s+${tenEscape}(?=\\s|$)`, 'i').test(khoiTrim);
            });
            if (nv) { nv.baoCao = khoiTrim; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, khoiTrim); }
        });
        modalDanNhieuBaoCao.hide(); hienThiDanhSachNhanVien(); luuVaoBoNhoTam();
        hienThiThongBao("Đã xử lý xong báo cáo hàng loạt.");
    });

    $('#nut-tao-bao-cao').on('click', () => thucHienTaoBaoCao());

    // Fix: Using robust delegation for the history button
    $(document).on('click', '#nut-xem-bao-cao-cu', (e) => {
        e.preventDefault();
        modalXemBaoCaoCu.show();
    });

    $('#nut-sao-chep').on('click', function() {
        const $btn = $(this);
        navigator.clipboard.writeText($('#vung-ket-qua-bao-cao').val()).then(() => {
            hienThiThongBao('Đã sao chép báo cáo vào bộ nhớ tạm!');
            $btn.html('<i class="fa-solid fa-check"></i> Đã chép').addClass('btn-success').removeClass('btn-primary');
            setTimeout(() => $btn.html('<i class="fa-regular fa-copy"></i> Sao chép').removeClass('btn-success').addClass('btn-primary'), 2000);
        });
    });

    // KHỞI CHẠY
    khoiTaoGiaoDien(); 
    xayDungMenuGiaoDien(); 
    taiDuLieuTuServer(); 
});

/* --- HỆ THỐNG GIAO DIỆN SỬ DỤNG BIẾN CSS --- */

:root {
    --bg-gradient: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
    --bg-image: none;
    --card-bg: rgba(255, 255, 255, 0.8);
    --text-primary: #1c1c1e;
    --text-secondary: #636366;
    --main-title-color: #1c1c1e;
    --accent-blue: #007AFF;
    --accent-green: #34C759;
    --accent-red: #FF3B30;
    --accent-gray: #8E8E93;
    --input-bg: #F2F2F7;
    --input-border: rgba(0, 0, 0, 0.1);
    --btn-fos-bg: #ffffff;
    --btn-fos-border: #e0e0e0;
    --scrollbar-thumb: var(--accent-gray);
    --scrollbar-track: rgba(0, 0, 0, 0.05);
    --close-btn-filter: none;
}

/* --- THEMES DEFINITIONS (16 variations) --- */

/* iOS 18 Dark */
body.theme-ios18-dark {
    --bg-gradient: linear-gradient(135deg, #000000 0%, #1c1c1e 100%);
    --card-bg: rgba(28, 28, 30, 0.95);
    --text-primary: #ffffff;
    --text-secondary: #a0a0a5;
    --main-title-color: #ffffff;
    --input-bg: #2c2c2e;
    --btn-fos-bg: #1c1c1e;
    --btn-fos-border: #3a3a3c;
    --close-btn-filter: invert(1) grayscale(100%) brightness(200%);
}

/* OneUI Samsung Dark */
body.theme-oneui-dark {
    --bg-gradient: linear-gradient(180deg, #121212 0%, #212121 100%);
    --card-bg: rgba(33, 33, 33, 0.98);
    --text-primary: #e0e0e0;
    --text-secondary: #999;
    --accent-blue: #3d5afe;
    --btn-fos-bg: #2a2a2a;
    --btn-fos-border: #333;
    --input-bg: #222;
    --close-btn-filter: invert(1);
}

/* Window 11 Dark */
body.theme-window11-dark {
    --bg-gradient: linear-gradient(135deg, #202020 0%, #1c1c1c 100%);
    --card-bg: rgba(32, 32, 32, 0.9);
    --text-primary: #ffffff;
    --text-secondary: #bbb;
    --accent-blue: #4cc2ff;
    --btn-fos-bg: #2d2d2d;
    --btn-fos-border: #444;
    --input-bg: #1e1e1e;
    --close-btn-filter: invert(1);
}

/* Gaming Zone Dark */
body.theme-gaming-dark {
    --bg-gradient: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%);
    --accent-blue: #00d2ff;
    --accent-green: #39ff14;
    --accent-red: #ff0055;
    --card-bg: rgba(0, 0, 0, 0.85);
    --text-primary: #00ffcc;
    --text-secondary: #00ccaa;
    --input-bg: #0a0a1a;
    --close-btn-filter: invert(1) hue-rotate(180deg);
}

/* Chic & Modern Dark */
body.theme-chic-dark {
    --bg-gradient: linear-gradient(to right, #434343 0%, #000000 100%);
    --card-bg: #1a1a1a;
    --text-primary: #ffffff;
    --text-secondary: #ccc;
    --accent-blue: #d4af37;
    --input-bg: #222;
    --close-btn-filter: invert(1);
}

/* --- ÉP MÀU CHỮ CHO TẤT CẢ PHẦN TỬ --- */
h1, h2, h3, h4, h5, h6, 
.card-title, .modal-title, .form-label, 
.main-title, strong, b, .fs-5 {
    color: var(--text-primary) !important;
}

body, p, span, li, a:not(.btn), label {
    color: var(--text-primary);
}

.text-muted, .subtitle-text, .status-detail, #thoi-gian-build-text {
    color: var(--text-secondary) !important;
}

/* --- BASE UI STYLES --- */

#lop-phu-tai-trang {
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    background: rgba(0, 0, 0, 0.7);
    backdrop-filter: blur(10px);
    display: none; 
    flex-direction: column;
    justify-content: center;
    align-items: center;
    z-index: 9999;
    color: white;
}

body {
    font-family: 'Poppins', sans-serif;
    background-color: var(--bg-gradient);
    background-image: var(--bg-image), var(--bg-gradient);
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: var(--text-primary);
    transition: background 0.4s ease, color 0.4s ease;
    min-height: 100vh;
}

/* Settings Button */
.settings-container {
    position: fixed;
    top: 25px;
    right: 25px;
    z-index: 1100;
}

#nut-cai-dat {
    cursor: pointer;
    font-size: 1.5rem;
    color: var(--accent-blue);
    background: var(--card-bg);
    width: 50px;
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    box-shadow: 0 8px 32px rgba(0,0,0,0.15);
    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275), background 0.3s ease;
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.1);
}
#nut-cai-dat:hover { transform: rotate(90deg) scale(1.1); background: rgba(255,255,255,0.9); }

/* Fix Dropdown & Submenu */
.dropdown-menu {
    border-radius: 1rem;
    padding: 0.5rem;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: var(--card-bg);
    backdrop-filter: blur(25px);
    box-shadow: 0 15px 45px rgba(0,0,0,0.2) !important;
}

.dropdown-item {
    border-radius: 0.6rem;
    padding: 0.6rem 1rem;
    color: var(--text-primary) !important;
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
}
.dropdown-item:hover {
    background-color: rgba(0, 122, 255, 0.1);
    color: var(--accent-blue) !important;
}

/* Modal Fixes */
.modal-header .btn-close {
    filter: var(--close-btn-filter);
}

.form-control, .form-select {
    background-color: var(--input-bg);
    color: var(--text-primary);
    border: 1px solid var(--input-border);
}

.form-control:focus, .form-select:focus {
    background-color: var(--input-bg);
    color: var(--text-primary);
    border-color: var(--accent-blue);
    box-shadow: 0 0 0 0.25rem rgba(0, 122, 255, 0.25);
}

.form-control::placeholder {
    color: var(--text-secondary);
    opacity: 0.6;
}

/* Layout Elements */
.card, .modal-content {
    background: var(--card-bg);
    backdrop-filter: blur(25px) saturate(200%);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 1.5rem;
}

#vung-danh-sach-nv {
    max-height: 420px;
    overflow-y: auto;
    padding: 12px;
    margin-bottom: 20px;
    border-radius: 1.25rem;
    background: rgba(0,0,0,0.03);
}

.nut-ten-nv {
    background-color: var(--btn-fos-bg);
    border: 1px solid var(--btn-fos-border);
    color: var(--text-primary);
    flex: 1;
    text-align: left;
    font-weight: 600;
    border-radius: 0.75rem 0 0 0.75rem !important;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    padding: 10px 15px;
}
.nut-ten-nv.da-bao-cao { background-color: var(--accent-green) !important; color: white !important; border-color: var(--accent-green); }
.nut-ten-nv.nghi { background-color: var(--accent-gray) !important; color: white !important; text-decoration: line-through; opacity: 0.8; }
.nut-ten-nv.sai-ten { background-color: var(--accent-red) !important; color: white !important; }

.nut-sua-nv { background-color: var(--accent-blue); color: white; width: 44px; border: none; }
.nut-xoa-nv { background-color: var(--accent-red); color: white; border-radius: 0 0.75rem 0.75rem 0 !important; width: 44px; border: none; }

.db-status-widget {
    position: fixed; bottom: 15px; left: 15px;
    background: var(--card-bg); padding: 10px 18px; border-radius: 18px;
    font-size: 0.7rem; z-index: 1000; box-shadow: 0 10px 30px rgba(0,0,0,0.12);
    backdrop-filter: blur(20px); border: 1px solid rgba(255, 255, 255, 0.15);
    display: flex; flex-direction: column; gap: 4px;
    min-width: 220px;
}

.status-dot {
    height: 8px; width: 8px; border-radius: 50%; display: inline-block; margin-right: 6px;
}
.status-dot.online { background-color: var(--accent-green); box-shadow: 0 0 8px var(--accent-green); }
.status-dot.offline { background-color: var(--accent-red); box-shadow: 0 0 8px var(--accent-red); }

#chi-bao-dang-luu {
    position: fixed; bottom: 85px; right: 20px;
    z-index: 2000; background: var(--accent-blue); padding: 12px 24px;
    border-radius: 50px; box-shadow: 0 10px 25px rgba(0,122,255,0.3);
    display: none; align-items: center; gap: 10px; color: white;
    font-size: 0.9rem; font-weight: 500;
}

import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';
import { hienThiThongBao, hienThiTaiTrang, anTaiTrang, dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien, apDungGiaoDien, luuCauHinhGiaoDien, apDungGiaoDienNgauNhien } from './theme.js';
import { thucHienGoiApi, ghiNhanTuongTacApi, lamMoiThongKeCsdl, datCheDoUngDung, layCheDoUngDung } from './api.js';
import { kiemTraTenTrongBaoCao, taoCauTrucGuiBaoCao } from './report.js';

$(function() {
    // --- TRẠNG THÁI ỨNG DỤNG ---
    let danhSachNhanVien = []; 
    let baoCaoLichSuGanNhat = null; 
    let ngayBaoCaoLichSu = null; 
    let nhanVienHienTai = null;
    let nhanVienCanXoa = null;

    // --- KHỞI TẠO MODAL BOOTSTRAP ---
    const modalThemNv = new bootstrap.Modal('#modal-them-nhan-vien');
    const modalDanBaoCao = new bootstrap.Modal('#modal-dan-bao-cao');
    const modalSuaBaoCao = new bootstrap.Modal('#modal-sua-bao-cao');
    const modalDanNhieuBaoCao = new bootstrap.Modal('#modal-dan-nhieu-bao-cao');
    const modalXacNhanXoa = new bootstrap.Modal('#modal-xac-nhan-xoa');
    const modalXemBaoCaoCu = new bootstrap.Modal('#modal-xem-bao-cao-cu');

    // --- CẬP NHẬT THÔNG TIN BUILD ---
    const phienBanBuild = "v1.3.9-stable";
    const thoiGianBuildStr = "2025.02.21 21:45"; 
    $('#phien-ban-build-text').text(phienBanBuild);
    $('#thoi-gian-build-text').text(`Build: ${thoiGianBuildStr}`);

    const capNhatWidgetDb = (trucTuyen, slNv, slBaoCao, slTruyCap) => {
        const $cham = $('#cham-trang-thai-db');
        const $chu = $('#chu-trang-thai-db');
        const $nv = $('#so-luong-nv-db');
        const $bc = $('#so-luong-bao-cao-db');
        const $luong = $('#luong-truy-cap-api');

        if (trucTuyen) {
            $cham.removeClass('offline').addClass('online');
            $chu.text('RestDB Online');
        } else {
            $cham.removeClass('online').addClass('offline');
            $chu.text('Chế độ Offline');
        }
        if (slNv !== null) $nv.text(`NV: ${slNv}`);
        if (slBaoCao !== null) $bc.text(`Rpt: ${slBaoCao}`);
        if (slTruyCap !== null) $luong.text(`(${slTruyCap})`);
    }

    const $vungDsNv = $('#vung-danh-sach-nv');

    const capNhatNutTaoBaoCao = () => {
        const daBaoCao = danhSachNhanVien.filter(nv => nv.trangThai !== 'Chưa báo cáo').length;
        const tongSo = danhSachNhanVien.length;
        $('#nut-tao-bao-cao').html(`Tạo & Lưu Báo Cáo (${daBaoCao}/${tongSo})`);
    };

    const hienThiDanhSachNhanVien = () => {
        if (danhSachNhanVien.length === 0) {
             $vungDsNv.html('<div class="text-center py-3 text-muted">Danh sách trống.</div>');
             capNhatNutTaoBaoCao();
             return;
        }

        let html = '<div class="row g-2">';
        danhSachNhanVien.forEach(nv => {
            let lopNut = 'nut-ten-nv btn';
            if (nv.kiemTraTen === false) lopNut += ' sai-ten';
            else if (nv.trangThai === 'Đã báo cáo') lopNut += ' da-bao-cao';
            else if (nv.trangThai === 'Off') lopNut += ' nghi';

            html += `
                <div class="col-6">
                    <div class="input-group shadow-sm" style="border-radius: 0.75rem; overflow: hidden;">
                        <button class="${lopNut}" data-nv-ten="${nv.ten}" title="${nv.ten}">
                            ${nv.ten}
                        </button>
                        <button class="btn nut-sua-nv nut-sua-nhanh-nv" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-pen-to-square"></i>
                        </button>
                        <button class="btn nut-xoa-nv nut-xoa-nv-kich-hoat" data-nv-id="${nv._id}" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </div>
            `;
        });
        html += '</div>';
        $vungDsNv.html(html);
        capNhatNutTaoBaoCao();
    };

    const luuVaoBoNhoTam = () => {
        const homNayStr = dinhDangNgayISO(new Date());
        const duLieu = {
            ngay: homNayStr,
            duLieuNv: danhSachNhanVien.map(n => ({
                _id: n._id, baoCao: n.baoCao, trangThai: n.trangThai, kiemTraTen: n.kiemTraTen
            })),
            vanBanKetQua: $('#vung-ket-qua-bao-cao').val()
        };
        localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify(duLieu));
    };

    const khoiPhuTuBoNhoTam = () => {
        const duLieuTho = localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO);
        if (!duLieuTho) return false;
        try {
            const duLieu = JSON.parse(duLieuTho);
            if (duLieu.ngay !== dinhDangNgayISO(new Date())) {
                localStorage.removeItem(KHOA_BO_NHO_TAM_CUC_BO);
                return false;
            }
            duLieu.duLieuNv.forEach(itemTam => {
                const nv = danhSachNhanVien.find(n => n._id === itemTam._id);
                if (nv && itemTam.baoCao) {
                    nv.baoCao = itemTam.baoCao; 
                    nv.trangThai = itemTam.trangThai; 
                    nv.kiemTraTen = itemTam.kiemTraTen;
                }
            });
            hienThiDanhSachNhanVien();
            if(duLieu.vanBanKetQua) $('#vung-ket-qua-bao-cao').val(duLieu.vanBanKetQua);
            return true;
        } catch (e) { return false; }
    };

    const taiDuLieuTuServer = async () => {
        hienThiTaiTrang("Đang tải danh sách FOS...");
        try {
            ghiNhanTuongTacApi().catch(() => {});

            const duLieuGoc = await thucHienGoiApi('nhanvien?h={"$orderby": {"Ten": 1}}');
            datCheDoUngDung('online');
            danhSachNhanVien = duLieuGoc.map(item => ({
                _id: item._id, ten: item.Ten, gioiTinh: item.GioiTinh,
                chiTieu: parseInt(item.ChiTieu, 10) || 50, baoCao: '',
                trangThai: 'Chưa báo cáo', kiemTraTen: null
            }));

            hienThiDanhSachNhanVien();

            anTaiTrang(); 
            khoiPhuTuBoNhoTam();
            lamMoiThongKeCsdl(capNhatWidgetDb).catch(() => {});
            khoiPhuPhienLamViec().catch(() => {});

        } catch (error) {
            datCheDoUngDung('offline');
            hienThiThongBao("Đang hoạt động ngoại tuyến", "info");
            try {
                const phanHoi = await fetch('fos.txt');
                const text = await phanHoi.text();
                danhSachNhanVien = text.split('\n').filter(l => l.trim()).map((line, index) => {
                    const parts = line.split('|');
                    return {
                        _id: `local_${index}`, ten: parts[0]?.trim(), gioiTinh: parts[1]?.trim(), 
                        chiTieu: parseInt(parts[2]?.trim() || '50'), baoCao: '', 
                        trangThai: 'Chưa báo cáo', kiemTraTen: null
                    };
                });
                hienThiDanhSachNhanVien();
                anTaiTrang();
                khoiPhuTuBoNhoTam();
            } catch (e) {
                anTaiTrang();
            }
        }
    };

    const khoiPhuPhienLamViec = async () => {
        const homNayStr = dinhDangNgayISO(new Date());

        try {
            const bcHomNay = await thucHienGoiApi(`report?q={"ngayBaoCao": "${homNayStr}"}`);
            if (bcHomNay.length > 0) {
                bcHomNay[0].baoCaoFOS.forEach(item => {
                    const nv = danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
                    if (nv && nv.baoCao === '') {
                        nv.trangThai = (item.OFF === 0 || item.OFF === '0') ? 'Đã báo cáo' : 'Off';
                        nv.baoCao = item.rawReport || `Fos ${item.tenNhanVien} ${nv.trangThai === 'Off' ? 'OFF' : ''}`;
                    }
                });
                hienThiDanhSachNhanVien();
            }
        } catch (e) {}

        try {
            const truyVanLichSu = `{"ngayBaoCao": {"$lt": "${homNayStr}"}}`;
            const sapXepLichSu = `{"$orderby": {"ngayBaoCao": -1}}`;
            const dsBcCu = await thucHienGoiApi(`report?q=${truyVanLichSu}&h=${sapXepLichSu}&max=1`);

            if (dsBcCu.length > 0) {
                const bcLichSu = dsBcCu[0];
                baoCaoLichSuGanNhat = bcLichSu;
                ngayBaoCaoLichSu = bcLichSu.ngayBaoCao;
                baoCaoLichSuGanNhat.duLieuNvLichSu = bcLichSu.baoCaoFOS.map(item => ({
                    ten: item.tenNhanVien, 
                    mtdMC: item.chiSoHieuSuat.saleTrongThang
                }));

                let txt = `Chốt mốc ngày ${dinhDangNgayHienThi(ngayBaoCaoLichSu)}:\n`;
                baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => txt += `${n.ten}: MTD ${n.mtdMC}\n`);
                $('#vung-ket-qua-bao-cao-cu').val(txt);
                thucHienTaoBaoCao(null, true);
            }
        } catch (e) {}
    };

    const luuBaoCaoLenServer = async (cauTruc, chayNgam = false) => {
        if (layCheDoUngDung() === 'offline') return;
        if (chayNgam) $('#chi-bao-dang-luu').css('display', 'flex');
        try {
            const kiemTra = await thucHienGoiApi(`report?q={"ngayBaoCao": "${cauTruc.ngayBaoCao}"}`);
            if (kiemTra.length > 0) await thucHienGoiApi(`report/${kiemTra[0]._id}`, 'PUT', cauTruc);
            else await thucHienGoiApi('report', 'POST', cauTruc);
            lamMoiThongKeCsdl(capNhatWidgetDb);
        } catch (error) {} finally { setTimeout(() => $('#chi-bao-dang-luu').fadeOut(), 1000); }
    };

    const thucHienTaoBaoCao = (e, chiXem = false) => {
        danhSachNhanVien.sort((a, b) => b.chiTieu - a.chiTieu);
        hienThiDanhSachNhanVien();
        const quanLy = 'TNH';
        const ngayHienThi = dinhDangNgayHienThi(new Date());
        let tMC = 0, tNTB = 0, tETB = 0, nvActive = 0, tPos = 0, tAE = 0;
        let dsChiTiet = [];
        const banDoLichSu = new Map();
        if (baoCaoLichSuGanNhat?.duLieuNvLichSu) baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => banDoLichSu.set(n.ten, n));

        danhSachNhanVien.forEach(nv => {
            const bieuTuong = nv.gioiTinh === 'Nữ' ? '👵' : '👨';
            const bc = nv.baoCao;
            let mtd = trichXuatSoLieu(bc, 'MTD MC');
            let ntb = trichXuatSoLieu(bc, 'NTB'), etb = trichXuatSoLieu(bc, 'ETB');
            let mcNay = ntb + etb;
            if (mcNay === 0) mcNay = trichXuatSoLieu(bc, ['Tổng MC', 'MC']);

            if ((nv.trangThai === 'Off' || mcNay === 0) && mtd === 0 && baoCaoLichSuGanNhat) {
                const nvLichSu = banDoLichSu.get(nv.ten);
                mtd = nvLichSu ? (nvLichSu.mtdMC || 0) : 0;
            }

            if (nv.trangThai === 'Off') {
                const matchLyDo = bc.match(/^Fos\s+\S+\s+(.*)$/i);
                const lyDo = (matchLyDo && matchLyDo[1] && matchLyDo[1].toUpperCase() !== 'OFF') ? matchLyDo[1] : 'OFF';
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${lyDo}/${mtd}/${nv.chiTieu}`);
            } else {
                nvActive++;
                tMC += mcNay; tNTB += ntb; tETB += etb;
                tPos += trichXuatSoLieu(bc, 'Pos'); tAE += trichXuatSoLieu(bc, ['AE+', 'AE Plus']);
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${mcNay}/${mtd}/${nv.chiTieu}`);
            }
        });

        const nsbqNTB = (nvActive > 0) ? (tNTB / nvActive).toFixed(2) : '0.00';
        const nsbqETB = (nvActive > 0) ? (tETB / nvActive).toFixed(2) : '0.00';
        let ketQua = `${quanLy} ngày ${ngayHienThi}\n🔥${danhSachNhanVien.length} FOS – ${tMC} MC\n✅NTB: ${tNTB}\n✅NSBQ NTB: ${nsbqNTB}\n✅ETB: ${tETB}\n✅NSBQ ETB: ${nsbqETB}\n✅AE+: ${tAE}\n✅Pos: ${tPos}/${danhSachNhanVien.length * 3}\n\n⭐️Active ${nvActive}/${danhSachNhanVien.length}\n${dsChiTiet.join('\n')}`;
        $('#vung-ket-qua-bao-cao').val(ketQua);

        if (!chiXem) {
            const thongKe = { tongFOS: danhSachNhanVien.length, tongMC: tMC, tongNTB: tNTB, nsbqNTB, tongETB: tETB, nsbqETB, tongPosThucHien: tPos, posChiTieu: danhSachNhanVien.length * 3, activeFOS: nvActive, tongAEPlus: tAE };
            luuBaoCaoLenServer(taoCauTrucGuiBaoCao(danhSachNhanVien, baoCaoLichSuGanNhat, thongKe), true);
        }
    };

    // --- SỰ KIỆN GIAO DIỆN ---
    $('body').on('click', '.lua-chon-giao-dien', function(e) {
        e.preventDefault();
        const theme = $(this).data('theme');
        const mode = $(this).data('mode');
        const lop = `theme-${theme}-${mode}`;
        apDungGiaoDien(lop); 
        luuCauHinhGiaoDien(lop);
        hienThiThongBao(`Giao diện: ${theme} ${mode}`);
    });

    $('#nut-giao-dien-ngau-nhien').on('click', e => { 
        e.preventDefault(); 
        luuCauHinhGiaoDien('random'); 
        apDungGiaoDienNgauNhien(); 
    });

    $('#nut-luu-nv-moi').on('click', async () => {
        const ten = $('#ten-nv-modal').val().trim(), gt = $('#gioi-tinh-nv-modal').val(), ct = parseInt($('#chi-tieu-nv-modal').val()) || 0;
        if (ten && !danhSachNhanVien.some(n => n.ten.toLowerCase() === ten.toLowerCase())) {
            hienThiTaiTrang("Đang lưu nhân viên...");
            try { await thucHienGoiApi('nhanvien', 'POST', { Ten: ten, GioiTinh: gt, ChiTieu: ct }); modalThemNv.hide(); taiDuLieuTuServer(); }
            catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); }
        }
    });

    $vungDsNv.on('click', '.nut-xoa-nv-kich-hoat', function() {
        nhanVienCanXoa = { id: $(this).data('nv-id'), ten: $(this).data('nv-ten') };
        $('#noi-dung-xac-nhan-xoa').text(`Xoá nhân viên "${nhanVienCanXoa.ten}"?`);
        modalXacNhanXoa.show();
    });

    $('#nut-xac-nhan-xoa-vinh-vien').on('click', async () => {
        if (!nhanVienCanXoa) return;
        hienThiTaiTrang("Đang xoá vĩnh viễn...");
        try { await thucHienGoiApi(`nhanvien/${nhanVienCanXoa.id}`, 'DELETE'); taiDuLieuTuServer(); }
        catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); modalXacNhanXoa.hide(); }
    });

    $vungDsNv.on('click', '.nut-ten-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { 
            $('#modalDanBaoCaoLabel').text(`Báo cáo của ${nhanVienHienTai}`); 
            $('#noi-dung-bao-cao-nhap').val(nv.baoCao); 
            modalDanBaoCao.show(); 
        }
    });

    $('#nut-luu-bao-cao-don').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const nd = $('#noi-dung-bao-cao-nhap').val();
            nv.baoCao = nd; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, nd);
            hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide();
        }
    });

    $('#nut-danh-dau-off').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} OFF`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $('#nut-xac-nhan-off-co-ly-do').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} ${$('#ly-do-off-nhap').val().trim() || 'OFF'}`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $vungDsNv.on('click', '.nut-sua-nhanh-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const bc = nv.baoCao;
            $('#tieu-de-modal-sua-bao-cao').text(`Sửa nhanh: ${nhanVienHienTai}`);
            $('#ntb-sua').val(trichXuatSoLieu(bc, 'NTB')); $('#etb-sua').val(trichXuatSoLieu(bc, 'ETB'));
            $('#pos-sua').val(trichXuatSoLieu(bc, 'Pos')); $('#aeplus-sua').val(trichXuatSoLieu(bc, ['AE+', 'AE Plus']));
            $('#mtd-sua').val(trichXuatSoLieu(bc, 'MTD MC'));
            modalSuaBaoCao.show();
        }
    });

    $('#nut-xac-nhan-sua-bao-cao').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const n = parseInt($('#ntb-sua').val()) || 0, e = parseInt($('#etb-sua').val()) || 0;
            nv.baoCao = `Fos ${nv.ten}\nTổng MC: ${n+e}\nNTB: ${n}\nETB: ${e}\nAE+: ${$('#aeplus-sua').val() || 0}\nPos: ${$('#pos-sua').val() || 0}\nMTD MC: ${$('#mtd-sua').val() || 0}`;
            nv.trangThai = 'Đã báo cáo'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalSuaBaoCao.hide();
        }
    });

    $('#nut-dan-tu-bo-nho').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-dan-hang-loat').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-nhieu-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-xu-ly-nhieu-bao-cao').on('click', () => {
        const vanBan = $('#noi-dung-nhieu-bao-cao-nhap').val().trim();
        if (!vanBan) return;
        const khoiBaoCao = vanBan.split(/(?=^Fos\s)/im); 
        khoiBaoCao.forEach(khoi => {
            const khoiTrim = khoi.trim();
            const nv = danhSachNhanVien.find(n => {
                const tenEscape = n.ten.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
                return new RegExp(`^Fos\\s+${tenEscape}(?=\\s|$)`, 'i').test(khoiTrim);
            });
            if (nv) { nv.baoCao = khoiTrim; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, khoiTrim); }
        });
        modalDanNhieuBaoCao.hide(); hienThiDanhSachNhanVien(); luuVaoBoNhoTam();
        hienThiThongBao("Đã xử lý xong báo cáo hàng loạt.");
    });

    $('#nut-tao-bao-cao').on('click', () => thucHienTaoBaoCao());

    $('#nut-sao-chep').on('click', function() {
        const $btn = $(this);
        navigator.clipboard.writeText($('#vung-ket-qua-bao-cao').val()).then(() => {
            hienThiThongBao('Đã sao chép báo cáo vào bộ nhớ tạm!');
            $btn.html('<i class="fa-solid fa-check"></i> Đã chép').addClass('btn-success').removeClass('btn-primary');
            setTimeout(() => $btn.html('<i class="fa-regular fa-copy"></i> Sao chép').removeClass('btn-success').addClass('btn-primary'), 2000);
        });
    });

    // KHỞI CHẠY
    khoiTaoGiaoDien(); 
    xayDungMenuGiaoDien(); 
    taiDuLieuTuServer(); 
});

import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';
import { hienThiThongBao, hienThiTaiTrang, anTaiTrang, dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien, apDungGiaoDien, luuCauHinhGiaoDien, apDungGiaoDienNgauNhien } from './theme.js';
import { thucHienGoiApi, ghiNhanTuongTacApi, lamMoiThongKeCsdl, datCheDoUngDung, layCheDoUngDung } from './api.js';
import { kiemTraTenTrongBaoCao, taoCauTrucGuiBaoCao } from './report.js';

$(function() {
    // --- TRẠNG THÁI ỨNG DỤNG ---
    let danhSachNhanVien = []; 
    let baoCaoLichSuGanNhat = null; 
    let ngayBaoCaoLichSu = null; 
    let nhanVienHienTai = null;
    let nhanVienCanXoa = null;

    // --- KHỞI TẠO MODAL BOOTSTRAP ---
    const modalThemNv = new bootstrap.Modal('#modal-them-nhan-vien');
    const modalDanBaoCao = new bootstrap.Modal('#modal-dan-bao-cao');
    const modalSuaBaoCao = new bootstrap.Modal('#modal-sua-bao-cao');
    const modalDanNhieuBaoCao = new bootstrap.Modal('#modal-dan-nhieu-bao-cao');
    const modalXacNhanXoa = new bootstrap.Modal('#modal-xac-nhan-xoa');
    const modalXemBaoCaoCu = new bootstrap.Modal('#modal-xem-bao-cao-cu');

    // --- CẬP NHẬT THÔNG TIN BUILD ---
    const phienBanBuild = "v1.4.0-stable";
    const thoiGianBuildStr = "2025.02.21 21:55"; 
    $('#phien-ban-build-text').text(phienBanBuild);
    $('#thoi-gian-build-text').text(`Build: ${thoiGianBuildStr}`);

    const capNhatWidgetDb = (trucTuyen, slNv, slBaoCao, slTruyCap) => {
        const $cham = $('#cham-trang-thai-db');
        const $chu = $('#chu-trang-thai-db');
        const $nv = $('#so-luong-nv-db');
        const $bc = $('#so-luong-bao-cao-db');
        const $luong = $('#luong-truy-cap-api');

        if (trucTuyen) {
            $cham.removeClass('offline').addClass('online');
            $chu.text('RestDB Online');
        } else {
            $cham.removeClass('online').addClass('offline');
            $chu.text('Chế độ Offline');
        }
        if (slNv !== null) $nv.text(`NV: ${slNv}`);
        if (slBaoCao !== null) $bc.text(`Rpt: ${slBaoCao}`);
        if (slTruyCap !== null) $luong.text(`(${slTruyCap})`);
    }

    const $vungDsNv = $('#vung-danh-sach-nv');

    const capNhatNutTaoBaoCao = () => {
        const daBaoCao = danhSachNhanVien.filter(nv => nv.trangThai !== 'Chưa báo cáo').length;
        const tongSo = danhSachNhanVien.length;
        $('#nut-tao-bao-cao').html(`Tạo & Lưu Báo Cáo (${daBaoCao}/${tongSo})`);
    };

    const hienThiDanhSachNhanVien = () => {
        if (danhSachNhanVien.length === 0) {
             $vungDsNv.html('<div class="text-center py-3 text-muted">Danh sách trống.</div>');
             capNhatNutTaoBaoCao();
             return;
        }

        let html = '<div class="row g-2">';
        danhSachNhanVien.forEach(nv => {
            let lopNut = 'nut-ten-nv btn';
            if (nv.kiemTraTen === false) lopNut += ' sai-ten';
            else if (nv.trangThai === 'Đã báo cáo') lopNut += ' da-bao-cao';
            else if (nv.trangThai === 'Off') lopNut += ' nghi';

            html += `
                <div class="col-6">
                    <div class="input-group shadow-sm" style="border-radius: 0.75rem; overflow: hidden;">
                        <button class="${lopNut}" data-nv-ten="${nv.ten}" title="${nv.ten}">
                            ${nv.ten}
                        </button>
                        <button class="btn nut-sua-nv nut-sua-nhanh-nv" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-pen-to-square"></i>
                        </button>
                        <button class="btn nut-xoa-nv nut-xoa-nv-kich-hoat" data-nv-id="${nv._id}" data-nv-ten="${nv.ten}">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </div>
            `;
        });
        html += '</div>';
        $vungDsNv.html(html);
        capNhatNutTaoBaoCao();
    };

    const luuVaoBoNhoTam = () => {
        const homNayStr = dinhDangNgayISO(new Date());
        const duLieu = {
            ngay: homNayStr,
            duLieuNv: danhSachNhanVien.map(n => ({
                _id: n._id, baoCao: n.baoCao, trangThai: n.trangThai, kiemTraTen: n.kiemTraTen
            })),
            vanBanKetQua: $('#vung-ket-qua-bao-cao').val()
        };
        localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify(duLieu));
    };

    const khoiPhuTuBoNhoTam = () => {
        const duLieuTho = localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO);
        if (!duLieuTho) return false;
        try {
            const duLieu = JSON.parse(duLieuTho);
            if (duLieu.ngay !== dinhDangNgayISO(new Date())) {
                localStorage.removeItem(KHOA_BO_NHO_TAM_CUC_BO);
                return false;
            }
            duLieu.duLieuNv.forEach(itemTam => {
                const nv = danhSachNhanVien.find(n => n._id === itemTam._id);
                if (nv && itemTam.baoCao) {
                    nv.baoCao = itemTam.baoCao; 
                    nv.trangThai = itemTam.trangThai; 
                    nv.kiemTraTen = itemTam.kiemTraTen;
                }
            });
            hienThiDanhSachNhanVien();
            if(duLieu.vanBanKetQua) $('#vung-ket-qua-bao-cao').val(duLieu.vanBanKetQua);
            return true;
        } catch (e) { return false; }
    };

    const taiDuLieuTuServer = async () => {
        hienThiTaiTrang("Đang tải danh sách FOS...");
        try {
            ghiNhanTuongTacApi().catch(() => {});

            const duLieuGoc = await thucHienGoiApi('nhanvien?h={"$orderby": {"Ten": 1}}');
            datCheDoUngDung('online');
            danhSachNhanVien = duLieuGoc.map(item => ({
                _id: item._id, ten: item.Ten, gioiTinh: item.GioiTinh,
                chiTieu: parseInt(item.ChiTieu, 10) || 50, baoCao: '',
                trangThai: 'Chưa báo cáo', kiemTraTen: null
            }));

            hienThiDanhSachNhanVien();

            anTaiTrang(); 
            khoiPhuTuBoNhoTam();
            lamMoiThongKeCsdl(capNhatWidgetDb).catch(() => {});
            khoiPhuPhienLamViec().catch(() => {});

        } catch (error) {
            datCheDoUngDung('offline');
            hienThiThongBao("Đang hoạt động ngoại tuyến", "info");
            try {
                const phanHoi = await fetch('fos.txt');
                const text = await phanHoi.text();
                danhSachNhanVien = text.split('\n').filter(l => l.trim()).map((line, index) => {
                    const parts = line.split('|');
                    return {
                        _id: `local_${index}`, ten: parts[0]?.trim(), gioiTinh: parts[1]?.trim(), 
                        chiTieu: parseInt(parts[2]?.trim() || '50'), baoCao: '', 
                        trangThai: 'Chưa báo cáo', kiemTraTen: null
                    };
                });
                hienThiDanhSachNhanVien();
                anTaiTrang();
                khoiPhuTuBoNhoTam();
            } catch (e) {
                anTaiTrang();
            }
        }
    };

    const khoiPhuPhienLamViec = async () => {
        const homNayStr = dinhDangNgayISO(new Date());

        try {
            const bcHomNay = await thucHienGoiApi(`report?q={"ngayBaoCao": "${homNayStr}"}`);
            if (bcHomNay.length > 0) {
                bcHomNay[0].baoCaoFOS.forEach(item => {
                    const nv = danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
                    if (nv && nv.baoCao === '') {
                        nv.trangThai = (item.OFF === 0 || item.OFF === '0') ? 'Đã báo cáo' : 'Off';
                        nv.baoCao = item.rawReport || `Fos ${item.tenNhanVien} ${nv.trangThai === 'Off' ? 'OFF' : ''}`;
                    }
                });
                hienThiDanhSachNhanVien();
            }
        } catch (e) {}

        try {
            const truyVanLichSu = `{"ngayBaoCao": {"$lt": "${homNayStr}"}}`;
            const sapXepLichSu = `{"$orderby": {"ngayBaoCao": -1}}`;
            const dsBcCu = await thucHienGoiApi(`report?q=${truyVanLichSu}&h=${sapXepLichSu}&max=1`);

            if (dsBcCu.length > 0) {
                const bcLichSu = dsBcCu[0];
                baoCaoLichSuGanNhat = bcLichSu;
                ngayBaoCaoLichSu = bcLichSu.ngayBaoCao;
                baoCaoLichSuGanNhat.duLieuNvLichSu = bcLichSu.baoCaoFOS.map(item => ({
                    ten: item.tenNhanVien, 
                    mtdMC: item.chiSoHieuSuat.saleTrongThang
                }));
                thucHienTaoBaoCao(null, true);
            }
        } catch (e) {}
    };

    const luuBaoCaoLenServer = async (cauTruc, chayNgam = false) => {
        if (layCheDoUngDung() === 'offline') return;
        if (chayNgam) $('#chi-bao-dang-luu').css('display', 'flex');
        try {
            const kiemTra = await thucHienGoiApi(`report?q={"ngayBaoCao": "${cauTruc.ngayBaoCao}"}`);
            if (kiemTra.length > 0) await thucHienGoiApi(`report/${kiemTra[0]._id}`, 'PUT', cauTruc);
            else await thucHienGoiApi('report', 'POST', cauTruc);
            lamMoiThongKeCsdl(capNhatWidgetDb);
        } catch (error) {} finally { setTimeout(() => $('#chi-bao-dang-luu').fadeOut(), 1000); }
    };

    const thucHienTaoBaoCao = (e, chiXem = false) => {
        danhSachNhanVien.sort((a, b) => b.chiTieu - a.chiTieu);
        hienThiDanhSachNhanVien();
        const quanLy = 'TNH';
        const ngayHienThi = dinhDangNgayHienThi(new Date());
        let tMC = 0, tNTB = 0, tETB = 0, nvActive = 0, tPos = 0, tAE = 0;
        let dsChiTiet = [];
        const banDoLichSu = new Map();
        if (baoCaoLichSuGanNhat?.duLieuNvLichSu) baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => banDoLichSu.set(n.ten, n));

        danhSachNhanVien.forEach(nv => {
            const bieuTuong = nv.gioiTinh === 'Nữ' ? '👵' : '👨';
            const bc = nv.baoCao;
            let mtd = trichXuatSoLieu(bc, 'MTD MC');
            let ntb = trichXuatSoLieu(bc, 'NTB'), etb = trichXuatSoLieu(bc, 'ETB');
            let mcNay = ntb + etb;
            if (mcNay === 0) mcNay = trichXuatSoLieu(bc, ['Tổng MC', 'MC']);

            if ((nv.trangThai === 'Off' || mcNay === 0) && mtd === 0 && baoCaoLichSuGanNhat) {
                const nvLichSu = banDoLichSu.get(nv.ten);
                mtd = nvLichSu ? (nvLichSu.mtdMC || 0) : 0;
            }

            if (nv.trangThai === 'Off') {
                const matchLyDo = bc.match(/^Fos\s+\S+\s+(.*)$/i);
                const lyDo = (matchLyDo && matchLyDo[1] && matchLyDo[1].toUpperCase() !== 'OFF') ? matchLyDo[1] : 'OFF';
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${lyDo}/${mtd}/${nv.chiTieu}`);
            } else {
                nvActive++;
                tMC += mcNay; tNTB += ntb; tETB += etb;
                tPos += trichXuatSoLieu(bc, 'Pos'); tAE += trichXuatSoLieu(bc, ['AE+', 'AE Plus']);
                dsChiTiet.push(`${bieuTuong}${nv.ten}: ${mcNay}/${mtd}/${nv.chiTieu}`);
            }
        });

        const nsbqNTB = (nvActive > 0) ? (tNTB / nvActive).toFixed(2) : '0.00';
        const nsbqETB = (nvActive > 0) ? (tETB / nvActive).toFixed(2) : '0.00';
        let ketQua = `${quanLy} ngày ${ngayHienThi}\n🔥${danhSachNhanVien.length} FOS – ${tMC} MC\n✅NTB: ${tNTB}\n✅NSBQ NTB: ${nsbqNTB}\n✅ETB: ${tETB}\n✅NSBQ ETB: ${nsbqETB}\n✅AE+: ${tAE}\n✅Pos: ${tPos}/${danhSachNhanVien.length * 3}\n\n⭐️Active ${nvActive}/${danhSachNhanVien.length}\n${dsChiTiet.join('\n')}`;
        $('#vung-ket-qua-bao-cao').val(ketQua);

        if (!chiXem) {
            const thongKe = { tongFOS: danhSachNhanVien.length, tongMC: tMC, tongNTB: tNTB, nsbqNTB, tongETB: tETB, nsbqETB, tongPosThucHien: tPos, posChiTieu: danhSachNhanVien.length * 3, activeFOS: nvActive, tongAEPlus: tAE };
            luuBaoCaoLenServer(taoCauTrucGuiBaoCao(danhSachNhanVien, baoCaoLichSuGanNhat, thongKe), true);
        }
    };

    const reconstructReportText = (reportObj) => {
        if (!reportObj) return "";
        const quanLy = 'TNH';
        const tk = reportObj.tongKetToanDoi;
        const ngay = dinhDangNgayHienThi(reportObj.ngayBaoCao);

        let dsChiTiet = [];
        reportObj.baoCaoFOS.forEach(item => {
            // Tìm giới tính từ danh sách hiện tại nếu có, không thì mặc định
            const nvHienTai = danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
            const bieuTuong = nvHienTai ? (nvHienTai.gioiTinh === 'Nữ' ? '👵' : '👨') : '👤';

            if (item.OFF !== 0 && item.OFF !== "0") {
                const lyDo = (item.OFF === 1 || item.OFF === "1") ? "OFF" : item.OFF;
                dsChiTiet.push(`${bieuTuong}${item.tenNhanVien}: ${lyDo}/${item.chiSoHieuSuat.saleTrongThang}/${item.chiSoHieuSuat.chiTieu}`);
            } else {
                dsChiTiet.push(`${bieuTuong}${item.tenNhanVien}: ${item.chiSoHieuSuat.saleHomNay}/${item.chiSoHieuSuat.saleTrongThang}/${item.chiSoHieuSuat.chiTieu}`);
            }
        });

        return `${quanLy} ngày ${ngay}\n🔥${tk.tongSoFOS} FOS – ${tk.tongSoMC} MC\n✅NTB: ${tk.tongSoNTB}\n✅NSBQ NTB: ${tk.NSBQ_NTB}\n✅ETB: ${tk.tongSoETB}\n✅NSBQ ETB: ${tk.NSBQ_ETB}\n✅AE+: ${tk.tongSoAEPlus}\n✅Pos: ${tk.tyLePOS}\n\n⭐️Active ${tk.tyLeActiveFOS}\n${dsChiTiet.join('\n')}`;
    };

    // --- SỰ KIỆN GIAO DIỆN ---
    $('body').on('click', '.lua-chon-giao-dien', function(e) {
        e.preventDefault();
        const theme = $(this).data('theme');
        const mode = $(this).data('mode');
        const lop = `theme-${theme}-${mode}`;
        apDungGiaoDien(lop); 
        luuCauHinhGiaoDien(lop);
        hienThiThongBao(`Giao diện: ${theme} ${mode}`);
    });

    $('#nut-giao-dien-ngau-nhien').on('click', e => { 
        e.preventDefault(); 
        luuCauHinhGiaoDien('random'); 
        apDungGiaoDienNgauNhien(); 
    });

    $('#nut-luu-nv-moi').on('click', async () => {
        const ten = $('#ten-nv-modal').val().trim(), gt = $('#gioi-tinh-nv-modal').val(), ct = parseInt($('#chi-tieu-nv-modal').val()) || 0;
        if (ten && !danhSachNhanVien.some(n => n.ten.toLowerCase() === ten.toLowerCase())) {
            hienThiTaiTrang("Đang lưu nhân viên...");
            try { await thucHienGoiApi('nhanvien', 'POST', { Ten: ten, GioiTinh: gt, ChiTieu: ct }); modalThemNv.hide(); taiDuLieuTuServer(); }
            catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); }
        }
    });

    $vungDsNv.on('click', '.nut-xoa-nv-kich-hoat', function() {
        nhanVienCanXoa = { id: $(this).data('nv-id'), ten: $(this).data('nv-ten') };
        $('#noi-dung-xac-nhan-xoa').text(`Xoá nhân viên "${nhanVienCanXoa.ten}"?`);
        modalXacNhanXoa.show();
    });

    $('#nut-xac-nhan-xoa-vinh-vien').on('click', async () => {
        if (!nhanVienCanXoa) return;
        hienThiTaiTrang("Đang xoá vĩnh viễn...");
        try { await thucHienGoiApi(`nhanvien/${nhanVienCanXoa.id}`, 'DELETE'); taiDuLieuTuServer(); }
        catch (e) { hienThiThongBao(e.message, 'error'); } finally { anTaiTrang(); modalXacNhanXoa.hide(); }
    });

    $vungDsNv.on('click', '.nut-ten-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { 
            $('#modalDanBaoCaoLabel').text(`Báo cáo của ${nhanVienHienTai}`); 
            $('#noi-dung-bao-cao-nhap').val(nv.baoCao); 
            modalDanBaoCao.show(); 
        }
    });

    $('#nut-luu-bao-cao-don').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const nd = $('#noi-dung-bao-cao-nhap').val();
            nv.baoCao = nd; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, nd);
            hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide();
        }
    });

    $('#nut-danh-dau-off').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} OFF`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $('#nut-xac-nhan-off-co-ly-do').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} ${$('#ly-do-off-nhap').val().trim() || 'OFF'}`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $vungDsNv.on('click', '.nut-sua-nhanh-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const bc = nv.baoCao;
            $('#tieu-de-modal-sua-bao-cao').text(`Sửa nhanh: ${nhanVienHienTai}`);
            $('#ntb-sua').val(trichXuatSoLieu(bc, 'NTB')); $('#etb-sua').val(trichXuatSoLieu(bc, 'ETB'));
            $('#pos-sua').val(trichXuatSoLieu(bc, 'Pos')); $('#aeplus-sua').val(trichXuatSoLieu(bc, ['AE+', 'AE Plus']));
            $('#mtd-sua').val(trichXuatSoLieu(bc, 'MTD MC'));
            modalSuaBaoCao.show();
        }
    });

    $('#nut-xac-nhan-sua-bao-cao').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const n = parseInt($('#ntb-sua').val()) || 0, e = parseInt($('#etb-sua').val()) || 0;
            nv.baoCao = `Fos ${nv.ten}\nTổng MC: ${n+e}\nNTB: ${n}\nETB: ${e}\nAE+: ${$('#aeplus-sua').val() || 0}\nPos: ${$('#pos-sua').val() || 0}\nMTD MC: ${$('#mtd-sua').val() || 0}`;
            nv.trangThai = 'Đã báo cáo'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalSuaBaoCao.hide();
        }
    });

    $('#nut-dan-tu-bo-nho').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-dan-hang-loat').on('click', async () => {
        try { const t = await navigator.clipboard.readText(); if (t) $('#noi-dung-nhieu-bao-cao-nhap').val(t); } catch(e) {}
    });

    $('#nut-xu-ly-nhieu-bao-cao').on('click', () => {
        const vanBan = $('#noi-dung-nhieu-bao-cao-nhap').val().trim();
        if (!vanBan) return;
        const khoiBaoCao = vanBan.split(/(?=^Fos\s)/im); 
        khoiBaoCao.forEach(khoi => {
            const khoiTrim = khoi.trim();
            const nv = danhSachNhanVien.find(n => {
                const tenEscape = n.ten.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
                return new RegExp(`^Fos\\s+${tenEscape}(?=\\s|$)`, 'i').test(khoiTrim);
            });
            if (nv) { nv.baoCao = khoiTrim; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, khoiTrim); }
        });
        modalDanNhieuBaoCao.hide(); hienThiDanhSachNhanVien(); luuVaoBoNhoTam();
        hienThiThongBao("Đã xử lý xong báo cáo hàng loạt.");
    });

    $('#nut-tao-bao-cao').on('click', () => thucHienTaoBaoCao());

    $('#nut-sao-chep').on('click', function() {
        const $btn = $(this);
        navigator.clipboard.writeText($('#vung-ket-qua-bao-cao').val()).then(() => {
            hienThiThongBao('Đã sao chép báo cáo vào bộ nhớ tạm!');
            $btn.html('<i class="fa-solid fa-check"></i> Đã chép').addClass('btn-success').removeClass('btn-primary');
            setTimeout(() => $btn.html('<i class="fa-regular fa-copy"></i> Sao chép').removeClass('btn-success').addClass('btn-primary'), 2000);
        });
    });

    // --- LOGIC XEM LỊCH SỬ ---
    const $modalLichSu = $('#modal-xem-bao-cao-cu');
    $modalLichSu.on('show.bs.modal', async () => {
        const $select = $('#chon-ngay-lich-su');
        $select.html('<option value="">-- Đang tải danh sách... --</option>');
        $('#vung-ket-qua-bao-cao-cu').val("");

        try {
            // Lấy danh sách ngày có báo cáo (giới hạn 30 ngày gần nhất)
            const dsNgay = await thucHienGoiApi('report?h={"$fields":{"ngayBaoCao":1}}&h={"$orderby":{"ngayBaoCao":-1}}&max=30');
            if (dsNgay && dsNgay.length > 0) {
                let html = '<option value="">-- Chọn ngày cần xem --</option>';
                dsNgay.forEach(item => {
                    html += `<option value="${item.ngayBaoCao}">${dinhDangNgayHienThi(item.ngayBaoCao)}</option>`;
                });
                $select.html(html);
            } else {
                $select.html('<option value="">Không có báo cáo nào</option>');
            }
        } catch (e) {
            $select.html('<option value="">Lỗi tải dữ liệu</option>');
        }
    });

    $('#chon-ngay-lich-su').on('change', async function() {
        const ngay = $(this).val();
        if (!ngay) {
            $('#vung-ket-qua-bao-cao-cu').val("");
            return;
        }

        hienThiTaiTrang("Đang tải báo cáo ngày " + dinhDangNgayHienThi(ngay));
        try {
            const ketQua = await thucHienGoiApi(`report?q={"ngayBaoCao":"${ngay}"}`);
            if (ketQua && ketQua.length > 0) {
                const textBaoCao = reconstructReportText(ketQua[0]);
                $('#vung-ket-qua-bao-cao-cu').val(textBaoCao);
            }
        } catch (e) {
            hienThiThongBao("Lỗi khi tải báo cáo chi tiết", "error");
        } finally {
            anTaiTrang();
        }
    });

    $('#nut-sao-chep-lich-su').on('click', function() {
        const val = $('#vung-ket-qua-bao-cao-cu').val();
        if (!val) return;
        navigator.clipboard.writeText(val).then(() => {
            hienThiThongBao('Đã sao chép báo cáo lịch sử!');
        });
    });

    // KHỞI CHẠY
    khoiTaoGiaoDien(); 
    xayDungMenuGiaoDien(); 
    taiDuLieuTuServer(); 
});

/* --- HỆ THỐNG GIAO DIỆN SỬ DỤNG BIẾN CSS --- */

:root {
    --bg-gradient: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
    --bg-image: none;
    --card-bg: rgba(255, 255, 255, 0.8);
    --text-primary: #1c1c1e;
    --text-secondary: #636366;
    --main-title-color: #1c1c1e;
    --accent-blue: #007AFF;
    --accent-green: #34C759;
    --accent-red: #FF3B30;
    --accent-gray: #8E8E93;
    --input-bg: #F2F2F7;
    --input-border: rgba(0, 0, 0, 0.1);
    --btn-fos-bg: #ffffff;
    --btn-fos-border: #e0e0e0;
    --scrollbar-thumb: var(--accent-gray);
    --scrollbar-track: rgba(0, 0, 0, 0.05);
    --close-btn-filter: none;
}

/* --- THEMES DEFINITIONS (16 variations) --- */

/* iOS 18 Dark */
body.theme-ios18-dark {
    --bg-gradient: linear-gradient(135deg, #000000 0%, #1c1c1e 100%);
    --card-bg: rgba(28, 28, 30, 0.95);
    --text-primary: #ffffff;
    --text-secondary: #a0a0a5;
    --main-title-color: #ffffff;
    --input-bg: #2c2c2e;
    --btn-fos-bg: #1c1c1e;
    --btn-fos-border: #3a3a3c;
    --close-btn-filter: invert(1) grayscale(100%) brightness(200%);
}

/* OneUI Samsung Dark */
body.theme-oneui-dark {
    --bg-gradient: linear-gradient(180deg, #121212 0%, #212121 100%);
    --card-bg: rgba(33, 33, 33, 0.98);
    --text-primary: #e0e0e0;
    --text-secondary: #999;
    --accent-blue: #3d5afe;
    --btn-fos-bg: #2a2a2a;
    --btn-fos-border: #333;
    --input-bg: #222;
    --close-btn-filter: invert(1);
}

/* Window 11 Dark */
body.theme-window11-dark {
    --bg-gradient: linear-gradient(135deg, #202020 0%, #1c1c1c 100%);
    --card-bg: rgba(32, 32, 32, 0.9);
    --text-primary: #ffffff;
    --text-secondary: #bbb;
    --accent-blue: #4cc2ff;
    --btn-fos-bg: #2d2d2d;
    --btn-fos-border: #444;
    --input-bg: #1e1e1e;
    --close-btn-filter: invert(1);
}

/* Gaming Zone Dark */
body.theme-gaming-dark {
    --bg-gradient: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%);
    --accent-blue: #00d2ff;
    --accent-green: #39ff14;
    --accent-red: #ff0055;
    --card-bg: rgba(0, 0, 0, 0.85);
    --text-primary: #00ffcc;
    --text-secondary: #00ccaa;
    --input-bg: #0a0a1a;
    --close-btn-filter: invert(1) hue-rotate(180deg);
}

/* Chic & Modern Dark */
body.theme-chic-dark {
    --bg-gradient: linear-gradient(to right, #434343 0%, #000000 100%);
    --card-bg: #1a1a1a;
    --text-primary: #ffffff;
    --text-secondary: #ccc;
    --accent-blue: #d4af37;
    --input-bg: #222;
    --close-btn-filter: invert(1);
}

/* --- ÉP MÀU CHỮ CHO TẤT CẢ PHẦN TỬ --- */
h1, h2, h3, h4, h5, h6, 
.card-title, .modal-title, .form-label, 
.main-title, strong, b, .fs-5 {
    color: var(--text-primary) !important;
}

body, p, span, li, a:not(.btn), label {
    color: var(--text-primary);
}

.text-muted, .subtitle-text, .status-detail, #thoi-gian-build-text {
    color: var(--text-secondary) !important;
}

/* --- BASE UI STYLES --- */

#lop-phu-tai-trang {
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    background: rgba(0, 0, 0, 0.7);
    backdrop-filter: blur(10px);
    display: none; 
    flex-direction: column;
    justify-content: center;
    align-items: center;
    z-index: 9999;
    color: white;
}

body {
    font-family: 'Poppins', sans-serif;
    background-color: var(--bg-gradient);
    background-image: var(--bg-image), var(--bg-gradient);
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: var(--text-primary);
    transition: background 0.4s ease, color 0.4s ease;
    min-height: 100vh;
}

/* Settings Button */
.settings-container {
    position: fixed;
    top: 25px;
    right: 25px;
    z-index: 1100;
}

#nut-cai-dat {
    cursor: pointer;
    font-size: 1.5rem;
    color: var(--accent-blue);
