const DANH_SACH_GIAO_DIEN = {
    'ios18': 'iOS 18',
    'oneui': 'OneUI',
    'window11': 'Window 11',
    'pastel': 'Pastel Dream',
    'nature': 'Serene Nature',
    'gaming': 'Gaming Zone',
    'carbon': 'Carbon Fiber',
    'chic': 'Chic & Modern',
};

export const xayDungMenuGiaoDien = () => {
    const menu = $('#menu-giao-dien-chon');
    if (!menu.length) return;
    menu.empty();
    for (const ma in DANH_SACH_GIAO_DIEN) {
        const ten = DANH_SACH_GIAO_DIEN[ma];
        menu.append(`
            <li class="dropdown-submenu">
                <a class="dropdown-item dropdown-toggle" href="javascript:void(0)">${ten}</a>
                <ul class="dropdown-menu shadow border-0">
                    <li><a class="dropdown-item lua-chon-giao-dien" href="#" data-theme="${ma}" data-mode="light">Chế độ Sáng</a></li>
                    <li><a class="dropdown-item lua-chon-giao-dien" href="#" data-theme="${ma}" data-mode="dark">Chế độ Tối</a></li>
                </ul>
            </li>
        `);
    }
};

export const apDungGiaoDien = (tenLopGiaoDien) => {
    const danhSachLop = $('body').attr('class')?.split(' ') || [];
    for (let lop of danhSachLop) {
        if (lop.startsWith('theme-')) {
            $('body').removeClass(lop);
        }
    }
    $('body').addClass(tenLopGiaoDien);
};

export const luuCauHinhGiaoDien = (luaChon) => {
    localStorage.setItem('cau_hinh_giao_dien', luaChon);
};

export const apDungGiaoDienNgauNhien = () => {
    const danhSachMa = Object.keys(DANH_SACH_GIAO_DIEN);
    const maNgauNhien = danhSachMa[Math.floor(Math.random() * danhSachMa.length)];
    const cheDoNgauNhien = Math.random() < 0.5 ? 'light' : 'dark';
    const lopGiaoDienNgauNhien = `theme-${maNgauNhien}-${cheDoNgauNhien}`;
    apDungGiaoDien(lopGiaoDienNgauNhien);
};

export const khoiTaoGiaoDien = () => {
    const cauHinhCu = localStorage.getItem('cau_hinh_giao_dien') || 'theme-ios18-light';
    if (cauHinhCu === 'random') {
        apDungGiaoDienNgauNhien();
    } else {
        apDungGiaoDien(cauHinhCu);
    }
};

import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';
import { hienThiThongBao, hienThiTaiTrang, anTaiTrang, dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien } from './theme.js';
import { thucHienGoiApi, ghiNhanTuongTacApi, lamMoiThongKeCsdl, datCheDoUngDung, layCheDoUngDung } from './api.js';
import { kiemTraTenTrongBaoCao, taoCauTrucGuiBaoCao } from './report.js';
import { initUIHandlers } from './ui.js';

export const state = {
    danhSachNhanVien: [],
    baoCaoLichSuGanNhat: null,
    nhanVienHienTai: null,
    nhanVienCanXoa: null
};

export const capNhatWidgetDb = (trucTuyen, slNv, slBaoCao, slTruyCap) => {
    const $cham = $('#cham-trang-thai-db');
    const $chu = $('#chu-trang-thai-db');
    if (trucTuyen) {
        $cham.removeClass('offline').addClass('online');
        $chu.text('RestDB Online');
    } else {
        $cham.removeClass('online').addClass('offline');
        $chu.text('Offline Mode');
    }
    if (slNv !== null) $('#so-luong-nv-db').text(`NV: ${slNv}`);
    if (slBaoCao !== null) $('#so-luong-bao-cao-db').text(`Rpt: ${slBaoCao}`);
    if (slTruyCap !== null) $('#luong-truy-cap-api').text(`(${slTruyCap})`);
};

export const hienThiDanhSachNhanVien = () => {
    const $vungDsNv = $('#vung-danh-sach-nv');
    if (state.danhSachNhanVien.length === 0) {
        $vungDsNv.html('<div class="text-center py-3 text-muted">Danh sách trống.</div>');
        return;
    }

    let html = '<div class="row g-2">';
    state.danhSachNhanVien.forEach(nv => {
        let lopNut = 'nut-ten-nv btn';
        if (nv.kiemTraTen === false) lopNut += ' sai-ten';
        else if (nv.trangThai === 'Đã báo cáo') lopNut += ' da-bao-cao';
        else if (nv.trangThai === 'Off') lopNut += ' nghi';

        html += `
            <div class="col-6">
                <div class="input-group shadow-sm" style="border-radius: 0.75rem; overflow: hidden;">
                    <button class="${lopNut}" data-nv-ten="${nv.ten}" title="${nv.ten}">${nv.ten}</button>
                    <button class="btn nut-sua-nv nut-sua-nhanh-nv" data-nv-ten="${nv.ten}"><i class="fa-solid fa-pen-to-square"></i></button>
                    <button class="btn nut-xoa-nv nut-xoa-nv-kich-hoat" data-nv-id="${nv._id}" data-nv-ten="${nv.ten}"><i class="fa-solid fa-trash-can"></i></button>
                </div>
            </div>
        `;
    });
    html += '</div>';
    $vungDsNv.html(html);

    const daBaoCao = state.danhSachNhanVien.filter(nv => nv.trangThai !== 'Chưa báo cáo').length;
    $('#nut-tao-bao-cao').html(`Tạo & Lưu Báo Cáo (${daBaoCao}/${state.danhSachNhanVien.length})`);
};

export const luuVaoBoNhoTam = () => {
    const data = {
        ngay: dinhDangNgayISO(new Date()),
        duLieuNv: state.danhSachNhanVien.map(n => ({ _id: n._id, baoCao: n.baoCao, trangThai: n.trangThai, kiemTraTen: n.kiemTraTen })),
        vanBanKetQua: $('#vung-ket-qua-bao-cao').val()
    };
    localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify(data));
};

export const taiDuLieuTuServer = async () => {
    hienThiTaiTrang("Đang tải danh sách FOS...");
    try {
        ghiNhanTuongTacApi().catch(() => {});
        const duLieuGoc = await thucHienGoiApi('nhanvien?h={"$orderby":{"Ten":1}}');
        datCheDoUngDung('online');
        state.danhSachNhanVien = duLieuGoc.map(item => ({
            _id: item._id, ten: item.Ten, gioiTinh: item.GioiTinh,
            chiTieu: parseInt(item.ChiTieu, 10) || 50, baoCao: '',
            trangThai: 'Chưa báo cáo', kiemTraTen: null
        }));

        // Cập nhật giao diện danh sách NV
        hienThiDanhSachNhanVien();

        // Khôi phục dữ liệu từ bộ nhớ tạm ngay lập tức
        const tam = JSON.parse(localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO) || '{}');
        if (tam.ngay === dinhDangNgayISO(new Date())) {
            tam.duLieuNv.forEach(itemTam => {
                const nv = state.danhSachNhanVien.find(n => n._id === itemTam._id);
                if (nv) { nv.baoCao = itemTam.baoCao; nv.trangThai = itemTam.trangThai; nv.kiemTraTen = itemTam.kiemTraTen; }
            });
            if(tam.vanBanKetQua) $('#vung-ket-qua-bao-cao').val(tam.vanBanKetQua);
            hienThiDanhSachNhanVien();
        }

        // ẨN LOADING TẠI ĐÂY để người dùng thao tác được ngay
        anTaiTrang();

        // Các tác vụ nền khác chạy sau khi đã mở khóa UI
        lamMoiThongKeCsdl(capNhatWidgetDb).catch(() => {});
        await khoiPhuPhienLamViec();
    } catch (error) {
        datCheDoUngDung('offline');
        hienThiThongBao("Chế độ ngoại tuyến", "info");
        anTaiTrang();
    }
};

export const khoiPhuPhienLamViec = async () => {
    const homNay = dinhDangNgayISO(new Date());
    try {
        const bc = await thucHienGoiApi(`report?q={"ngayBaoCao":"${homNay}"}`);
        if (bc.length > 0) {
            bc[0].baoCaoFOS.forEach(item => {
                const nv = state.danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
                if (nv && nv.baoCao === '') {
                    nv.trangThai = (item.OFF === 0 || item.OFF === '0') ? 'Đã báo cáo' : 'Off';
                    nv.baoCao = item.rawReport || `Fos ${item.tenNhanVien} ${nv.trangThai === 'Off' ? 'OFF' : ''}`;
                }
            });
            hienThiDanhSachNhanVien();
        }
        const cu = await thucHienGoiApi(`report?q={"ngayBaoCao":{"$lt":"${homNay}"}}&h={"$orderby":{"ngayBaoCao":-1}}&max=1`);
        if (cu.length > 0) {
            state.baoCaoLichSuGanNhat = cu[0];
            state.baoCaoLichSuGanNhat.duLieuNvLichSu = cu[0].baoCaoFOS.map(i => ({ ten: i.tenNhanVien, mtdMC: i.chiSoHieuSuat.saleTrongThang }));
        }
    } catch (e) {}
};

export const thucHienTaoBaoCao = async (chiXem = false) => {
    state.danhSachNhanVien.sort((a, b) => b.chiTieu - a.chiTieu);
    hienThiDanhSachNhanVien();
    const ngayHienThi = dinhDangNgayHienThi(new Date());
    let tMC = 0, tNTB = 0, tETB = 0, nvActive = 0, tPos = 0, tAE = 0;
    let dsChiTiet = [];
    const mapLs = new Map();
    if (state.baoCaoLichSuGanNhat?.duLieuNvLichSu) state.baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => mapLs.set(n.ten, n));

    state.danhSachNhanVien.forEach(nv => {
        const icon = nv.gioiTinh === 'Nữ' ? '👵' : '👨';
        const bc = nv.baoCao;
        let mtd = trichXuatSoLieu(bc, 'MTD MC');
        let ntb = trichXuatSoLieu(bc, 'NTB'), etb = trichXuatSoLieu(bc, 'ETB');
        let mcNay = ntb + etb;
        if (mcNay === 0) mcNay = trichXuatSoLieu(bc, ['Tổng MC', 'MC']);
        if ((nv.trangThai === 'Off' || mcNay === 0) && mtd === 0 && state.baoCaoLichSuGanNhat) {
            const ls = mapLs.get(nv.ten); mtd = ls ? (ls.mtdMC || 0) : 0;
        }
        if (nv.trangThai === 'Off') {
            const m = bc.match(/^Fos\s+\S+\s+(.*)$/i);
            dsChiTiet.push(`${icon}${nv.ten}: ${(m && m[1]) ? m[1].toUpperCase() : 'OFF'}/${mtd}/${nv.chiTieu}`);
        } else {
            nvActive++; tMC += mcNay; tNTB += ntb; tETB += etb;
            tPos += trichXuatSoLieu(bc, 'Pos'); tAE += trichXuatSoLieu(bc, ['AE+', 'AE Plus']);
            dsChiTiet.push(`${icon}${nv.ten}: ${mcNay}/${mtd}/${nv.chiTieu}`);
        }
    });

    const nsbqNTB = (nvActive > 0) ? (tNTB / nvActive).toFixed(2) : '0.00';
    const nsbqETB = (nvActive > 0) ? (tETB / nvActive).toFixed(2) : '0.00';
    const res = `TNH ngày ${ngayHienThi}\n🔥${state.danhSachNhanVien.length} FOS – ${tMC} MC\n✅NTB: ${tNTB}\n✅NSBQ NTB: ${nsbqNTB}\n✅ETB: ${tETB}\n✅NSBQ ETB: ${nsbqETB}\n✅AE+: ${tAE}\n✅Pos: ${tPos}/${state.danhSachNhanVien.length * 3}\n\n⭐️Active ${nvActive}/${state.danhSachNhanVien.length}\n${dsChiTiet.join('\n')}`;
    $('#vung-ket-qua-bao-cao').val(res);

    if (!chiXem && layCheDoUngDung() === 'online') {
        const cauTruc = taoCauTrucGuiBaoCao(state.danhSachNhanVien, state.baoCaoLichSuGanNhat, { tongFOS: state.danhSachNhanVien.length, tongMC: tMC, tongNTB: tNTB, nsbqNTB, tongETB: tETB, nsbqETB, tongPosThucHien: tPos, posChiTieu: state.danhSachNhanVien.length * 3, activeFOS: nvActive, tongAEPlus: tAE });
        $('#chi-bao-dang-luu').css('display', 'flex');
        try {
            const check = await thucHienGoiApi(`report?q={"ngayBaoCao":"${cauTruc.ngayBaoCao}"}`);
            if (check.length > 0) await thucHienGoiApi(`report/${check[0]._id}`, 'PUT', cauTruc);
            else await thucHienGoiApi('report', 'POST', cauTruc);
            lamMoiThongKeCsdl(capNhatWidgetDb);
        } catch(e) {} finally { setTimeout(() => $('#chi-bao-dang-luu').fadeOut(), 1000); }
    }
};

export const reconstructReportText = (reportObj) => {
    if (!reportObj) return "";
    const tk = reportObj.tongKetToanDoi;
    let ds = reportObj.baoCaoFOS.map(item => {
        const nv = state.danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
        const icon = nv ? (nv.gioiTinh === 'Nữ' ? '👵' : '👨') : '👤';
        const val = (item.OFF !== 0 && item.OFF !== "0") ? (item.OFF === 1 || item.OFF === "1" ? "OFF" : item.OFF) : `${item.chiSoHieuSuat.saleHomNay}/${item.chiSoHieuSuat.saleTrongThang}`;
        return `${icon}${item.tenNhanVien}: ${val}/${item.chiSoHieuSuat.chiTieu}`;
    });
    return `TNH ngày ${dinhDangNgayHienThi(reportObj.ngayBaoCao)}\n🔥${tk.tongSoFOS} FOS – ${tk.tongSoMC} MC\n✅NTB: ${tk.tongSoNTB}\n✅NSBQ: ${tk.NSBQ_NTB}\n✅ETB: ${tk.tongSoETB}\n✅AE+: ${tk.tongSoAEPlus}\n✅Pos: ${tk.tyLePOS}\n\n⭐️Active ${tk.tyLeActiveFOS}\n${ds.join('\n')}`;
};

$(() => {
    khoiTaoGiaoDien();
    xayDungMenuGiaoDien();
    taiDuLieuTuServer();
    initUIHandlers();
});

@import "./themes.css";

/* --- ÉP MÀU CHỮ --- */
h1, h2, h3, h4, h5, h6, 
.card-title, .modal-title, .form-label, 
.main-title, strong, b, .fs-5 {
    color: var(--text-primary) !important;
}

body, p, span, li, a:not(.btn), label {
    color: var(--text-primary);
}

.text-muted, .subtitle-text, .status-detail, #thoi-gian-build-text {
    color: var(--text-secondary) !important;
}

/* --- UI BASE --- */
#lop-phu-tai-trang {
    position: fixed; top: 0; left: 0;
    width: 100%; height: 100%;
    background: rgba(0, 0, 0, 0.7);
    backdrop-filter: blur(10px);
    display: none; flex-direction: column;
    justify-content: center; align-items: center;
    z-index: 9999; color: white;
}

body {
    font-family: 'Poppins', sans-serif;
    background-color: var(--bg-gradient);
    background-image: var(--bg-image), var(--bg-gradient);
    background-size: cover; background-position: center; background-attachment: fixed;
    color: var(--text-primary);
    transition: background 0.4s ease, color 0.4s ease;
    min-height: 100vh;
}

.settings-container { position: fixed; top: 25px; right: 25px; z-index: 1100; }

#nut-cai-dat {
    cursor: pointer; font-size: 1.5rem; color: var(--accent-blue);
    background: var(--card-bg); width: 50px; height: 50px;
    display: flex; align-items: center; justify-content: center;
    border-radius: 50%; box-shadow: 0 8px 32px rgba(0,0,0,0.15);
    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    backdrop-filter: blur(10px); border: 1px solid rgba(255, 255, 255, 0.1);
}
#nut-cai-dat:hover { transform: rotate(90deg) scale(1.1); background: rgba(255,255,255,0.9); }

/* --- DROPDOWN & SUBMENU FIX --- */
.dropdown-menu {
    border-radius: 1rem; padding: 0.5rem;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: var(--card-bg); backdrop-filter: blur(25px);
    box-shadow: 0 15px 45px rgba(0,0,0,0.2) !important;
    min-width: 200px;
}

.dropdown-item {
    border-radius: 0.6rem; padding: 0.6rem 1rem;
    color: var(--text-primary) !important;
    display: flex; align-items: center;
    justify-content: space-between;
}
.dropdown-item:hover { background-color: rgba(0, 122, 255, 0.1); color: var(--accent-blue) !important; }

/* CSS hỗ trợ Menu đa cấp (Submenu) */
.dropdown-submenu { position: relative; }

.dropdown-submenu > .dropdown-menu {
    top: 0;
    right: 100%; /* Đẩy sang bên trái vì nút nằm bên phải màn hình */
    left: auto;
    margin-top: -5px;
    margin-right: 0px; /* Sát mép để không bị mất hover */
    display: none;
}

/* Pseudo-element tạo "vùng đệm" vô hình bắc cầu giữa cha và con */
.dropdown-submenu > .dropdown-menu::before {
    content: "";
    position: absolute;
    top: 0;
    right: -15px; /* Vùng đệm lấn sang mục cha 15px */
    width: 20px;
    height: 100%;
    z-index: -1;
}

.dropdown-submenu:hover > .dropdown-menu {
    display: block;
}

/* Đổi mũi tên chỉ sang trái cho submenu */
.dropdown-submenu > .dropdown-toggle::after {
    display: inline-block;
    margin-left: 0.5rem;
    vertical-align: middle;
    content: "";
    border-top: .3em solid transparent;
    border-right: .3em solid;
    border-bottom: .3em solid transparent;
    border-left: 0;
}

.modal-header .btn-close { filter: var(--close-btn-filter); }

.form-control, .form-select {
    background-color: var(--input-bg);
    color: var(--text-primary);
    border: 1px solid var(--input-border);
}

.card, .modal-content {
    background: var(--card-bg);
    backdrop-filter: blur(25px) saturate(200%);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 1.5rem;
}

#vung-danh-sach-nv {
    max-height: 420px; overflow-y: auto;
    padding: 12px; margin-bottom: 20px;
    border-radius: 1.25rem; background: rgba(0,0,0,0.03);
}

.nut-ten-nv {
    background-color: var(--btn-fos-bg);
    border: 1px solid var(--btn-fos-border);
    color: var(--text-primary);
    flex: 1; text-align: left; font-weight: 600;
    border-radius: 0.75rem 0 0 0.75rem !important;
    padding: 10px 15px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.nut-ten-nv.da-bao-cao { background-color: var(--accent-green) !important; color: white !important; }
.nut-ten-nv.nghi { background-color: var(--accent-gray) !important; color: white !important; text-decoration: line-through; opacity: 0.8; }
.nut-ten-nv.sai-ten { background-color: var(--accent-red) !important; color: white !important; }

.nut-sua-nv { background-color: var(--accent-blue); color: white; width: 44px; border: none; }
.nut-xoa-nv { background-color: var(--accent-red); color: white; border-radius: 0 0.75rem 0.75rem 0 !important; width: 44px; border: none; }

/* DB Status Widget Tinh chỉnh */
.db-status-widget {
    position: fixed; bottom: 15px; left: 15px;
    background: var(--card-bg); padding: 12px 18px; border-radius: 18px;
    font-size: 0.7rem; z-index: 1000; box-shadow: 0 10px 30px rgba(0,0,0,0.12);
    backdrop-filter: blur(20px); border: 1px solid rgba(255, 255, 255, 0.15);
    display: flex; flex-direction: column; gap: 6px;
    min-width: 240px;
}

.status-header, .status-detail {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 8px;
    line-height: 1;
}

.status-divider {
    width: 1px;
    height: 12px;
    background-color: var(--text-secondary);
    opacity: 0.2;
}

.status-dot { height: 8px; width: 8px; border-radius: 50%; display: inline-block; margin-right: 6px; flex-shrink: 0; }
.status-dot.online { background-color: var(--accent-green); box-shadow: 0 0 8px var(--accent-green); }
.status-dot.offline { background-color: var(--accent-red); box-shadow: 0 0 8px var(--accent-red); }

#chi-bao-dang-luu {
    position: fixed; bottom: 85px; right: 20px;
    z-index: 2000; background: var(--accent-blue); padding: 12px 24px;
    border-radius: 50px; color: white; display: none; align-items: center; gap: 10px;
}

import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';
import { hienThiThongBao, hienThiTaiTrang, anTaiTrang, dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien } from './theme.js';
import { thucHienGoiApi, ghiNhanTuongTacApi, lamMoiThongKeCsdl, datCheDoUngDung, layCheDoUngDung } from './api.js';
import { kiemTraTenTrongBaoCao, taoCauTrucGuiBaoCao } from './report.js';
import { initUIHandlers } from './ui.js';

export const state = {
    danhSachNhanVien: [],
    baoCaoLichSuGanNhat: null,
    nhanVienHienTai: null,
    nhanVienCanXoa: null
};

export const capNhatWidgetDb = (trucTuyen, slNv, slBaoCao, slTruyCap) => {
    const $cham = $('#cham-trang-thai-db');
    const $chu = $('#chu-trang-thai-db');
    if (trucTuyen) {
        $cham.removeClass('offline').addClass('online');
        $chu.text('RestDB Online');
    } else {
        $cham.removeClass('online').addClass('offline');
        $chu.text('Offline Mode');
    }
    if (slNv !== null) $('#so-luong-nv-db').text(`NV: ${slNv}`);
    if (slBaoCao !== null) $('#so-luong-bao-cao-db').text(`Rpt: ${slBaoCao}`);
    if (slTruyCap !== null) $('#luong-truy-cap-api').text(`(${slTruyCap})`);
};

export const hienThiDanhSachNhanVien = () => {
    const $vungDsNv = $('#vung-danh-sach-nv');
    if (state.danhSachNhanVien.length === 0) {
        $vungDsNv.html('<div class="text-center py-3 text-muted">Danh sách trống.</div>');
        return;
    }

    let html = '<div class="row g-2">';
    state.danhSachNhanVien.forEach(nv => {
        let lopNut = 'nut-ten-nv btn';
        if (nv.kiemTraTen === false) lopNut += ' sai-ten';
        else if (nv.trangThai === 'Đã báo cáo') lopNut += ' da-bao-cao';
        else if (nv.trangThai === 'Off') lopNut += ' nghi';

        html += `
            <div class="col-6">
                <div class="input-group shadow-sm" style="border-radius: 0.75rem; overflow: hidden;">
                    <button class="${lopNut}" data-nv-ten="${nv.ten}" title="${nv.ten}">${nv.ten}</button>
                    <button class="btn nut-sua-nv nut-sua-nhanh-nv" data-nv-ten="${nv.ten}"><i class="fa-solid fa-pen-to-square"></i></button>
                    <button class="btn nut-xoa-nv nut-xoa-nv-kich-hoat" data-nv-id="${nv._id}" data-nv-ten="${nv.ten}"><i class="fa-solid fa-trash-can"></i></button>
                </div>
            </div>
        `;
    });
    html += '</div>';
    $vungDsNv.html(html);

    const daBaoCao = state.danhSachNhanVien.filter(nv => nv.trangThai !== 'Chưa báo cáo').length;
    $('#nut-tao-bao-cao').html(`Tạo & Lưu Báo Cáo (${daBaoCao}/${state.danhSachNhanVien.length})`);
};

export const luuVaoBoNhoTam = () => {
    const data = {
        ngay: dinhDangNgayISO(new Date()),
        duLieuNv: state.danhSachNhanVien.map(n => ({ _id: n._id, baoCao: n.baoCao, trangThai: n.trangThai, kiemTraTen: n.kiemTraTen })),
        vanBanKetQua: $('#vung-ket-qua-bao-cao').val()
    };
    localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify(data));
};

export const taiDuLieuTuServer = async () => {
    hienThiTaiTrang("Đang tải danh sách FOS...");
    try {
        ghiNhanTuongTacApi().catch(() => {});
        const duLieuGoc = await thucHienGoiApi('nhanvien?h={"$orderby":{"Ten":1}}');
        datCheDoUngDung('online');
        state.danhSachNhanVien = duLieuGoc.map(item => ({
            _id: item._id, ten: item.Ten, gioiTinh: item.GioiTinh,
            chiTieu: parseInt(item.ChiTieu, 10) || 50, baoCao: '',
            trangThai: 'Chưa báo cáo', kiemTraTen: null
        }));

        hienThiDanhSachNhanVien();

        const tam = JSON.parse(localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO) || '{}');
        if (tam.ngay === dinhDangNgayISO(new Date())) {
            tam.duLieuNv.forEach(itemTam => {
                const nv = state.danhSachNhanVien.find(n => n._id === itemTam._id);
                if (nv) { nv.baoCao = itemTam.baoCao; nv.trangThai = itemTam.trangThai; nv.kiemTraTen = itemTam.kiemTraTen; }
            });
            if(tam.vanBanKetQua) $('#vung-ket-qua-bao-cao').val(tam.vanBanKetQua);
            hienThiDanhSachNhanVien();
        }

        anTaiTrang();

        lamMoiThongKeCsdl(capNhatWidgetDb).catch(() => {});
        await khoiPhuPhienLamViec();
    } catch (error) {
        datCheDoUngDung('offline');
        hienThiThongBao("Chế độ ngoại tuyến", "info");
        anTaiTrang();
    }
};

export const khoiPhuPhienLamViec = async () => {
    const homNay = dinhDangNgayISO(new Date());
    try {
        const bc = await thucHienGoiApi(`report?q={"ngayBaoCao":"${homNay}"}`);
        if (bc.length > 0) {
            bc[0].baoCaoFOS.forEach(item => {
                const nv = state.danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
                if (nv && nv.baoCao === '') {
                    nv.trangThai = (item.OFF === 0 || item.OFF === '0') ? 'Đã báo cáo' : 'Off';
                    nv.baoCao = item.rawReport || `Fos ${item.tenNhanVien} ${nv.trangThai === 'Off' ? 'OFF' : ''}`;
                }
            });
            hienThiDanhSachNhanVien();
        }
        const cu = await thucHienGoiApi(`report?q={"ngayBaoCao":{"$lt":"${homNay}"}}&h={"$orderby":{"ngayBaoCao":-1}}&max=1`);
        if (cu.length > 0) {
            state.baoCaoLichSuGanNhat = cu[0];
            state.baoCaoLichSuGanNhat.duLieuNvLichSu = cu[0].baoCaoFOS.map(i => ({ ten: i.tenNhanVien, mtdMC: i.chiSoHieuSuat.saleTrongThang }));
        }
    } catch (e) {}
};

export const thucHienTaoBaoCao = async (chiXem = false) => {
    state.danhSachNhanVien.sort((a, b) => b.chiTieu - a.chiTieu);
    hienThiDanhSachNhanVien();
    const ngayHienThi = dinhDangNgayHienThi(new Date());
    let tMC = 0, tNTB = 0, tETB = 0, nvActive = 0, tPos = 0, tAE = 0;
    let dsChiTiet = [];
    const mapLs = new Map();
    if (state.baoCaoLichSuGanNhat?.duLieuNvLichSu) state.baoCaoLichSuGanNhat.duLieuNvLichSu.forEach(n => mapLs.set(n.ten, n));

    state.danhSachNhanVien.forEach(nv => {
        const icon = nv.gioiTinh === 'Nữ' ? '👵' : '👨';
        const bc = nv.baoCao;
        let mtd = trichXuatSoLieu(bc, 'MTD MC');
        let ntb = trichXuatSoLieu(bc, 'NTB'), etb = trichXuatSoLieu(bc, 'ETB');
        let mcNay = ntb + etb;
        if (mcNay === 0) mcNay = trichXuatSoLieu(bc, ['Tổng MC', 'MC']);
        if ((nv.trangThai === 'Off' || mcNay === 0) && mtd === 0 && state.baoCaoLichSuGanNhat) {
            const ls = mapLs.get(nv.ten); mtd = ls ? (ls.mtdMC || 0) : 0;
        }
        if (nv.trangThai === 'Off') {
            const m = bc.match(/^Fos\s+\S+\s+(.*)$/i);
            dsChiTiet.push(`${icon}${nv.ten}: ${(m && m[1]) ? m[1].toUpperCase() : 'OFF'}/${mtd}/${nv.chiTieu}`);
        } else {
            nvActive++; tMC += mcNay; tNTB += ntb; tETB += etb;
            tPos += trichXuatSoLieu(bc, 'Pos'); tAE += trichXuatSoLieu(bc, ['AE+', 'AE Plus']);
            dsChiTiet.push(`${icon}${nv.ten}: ${mcNay}/${mtd}/${nv.chiTieu}`);
        }
    });

    const nsbqNTB = (nvActive > 0) ? (tNTB / nvActive).toFixed(2) : '0.00';
    const nsbqETB = (nvActive > 0) ? (tETB / nvActive).toFixed(2) : '0.00';
    const res = `TNH ngày ${ngayHienThi}\n🔥${state.danhSachNhanVien.length} FOS – ${tMC} MC\n✅NTB: ${tNTB}\n✅NSBQ NTB: ${nsbqNTB}\n✅ETB: ${tETB}\n✅NSBQ ETB: ${nsbqETB}\n✅AE+: ${tAE}\n✅Pos: ${tPos}/${state.danhSachNhanVien.length * 3}\n\n⭐️Active ${nvActive}/${state.danhSachNhanVien.length}\n${dsChiTiet.join('\n')}`;
    $('#vung-ket-qua-bao-cao').val(res);

    if (!chiXem && layCheDoUngDung() === 'online') {
        const cauTruc = taoCauTrucGuiBaoCao(state.danhSachNhanVien, state.baoCaoLichSuGanNhat, { tongFOS: state.danhSachNhanVien.length, tongMC: tMC, tongNTB: tNTB, nsbqNTB, tongETB: tETB, nsbqETB, tongPosThucHien: tPos, posChiTieu: state.danhSachNhanVien.length * 3, activeFOS: nvActive, tongAEPlus: tAE });
        $('#chi-bao-dang-luu').css('display', 'flex');
        try {
            const check = await thucHienGoiApi(`report?q={"ngayBaoCao":"${cauTruc.ngayBaoCao}"}`);
            if (check.length > 0) await thucHienGoiApi(`report/${check[0]._id}`, 'PUT', cauTruc);
            else await thucHienGoiApi('report', 'POST', cauTruc);
            lamMoiThongKeCsdl(capNhatWidgetDb);
        } catch(e) {} finally { setTimeout(() => $('#chi-bao-dang-luu').fadeOut(), 1000); }
    }
};

export const reconstructReportText = (reportObj) => {
    if (!reportObj) return "";
    const tk = reportObj.tongKetToanDoi;
    let ds = reportObj.baoCaoFOS.map(item => {
        const nv = state.danhSachNhanVien.find(n => n.ten === item.tenNhanVien);
        const icon = nv ? (nv.gioiTinh === 'Nữ' ? '👵' : '👨') : '👤';
        const chiTieu = item.chiSoHieuSuat.chiTieu;
        const mtd = item.chiSoHieuSuat.saleTrongThang;

        let val;
        if (item.OFF !== 0 && item.OFF !== "0") {
            const lyDo = (item.OFF === 1 || item.OFF === "1") ? "OFF" : item.OFF;
            val = lyDo;
        } else {
            val = item.chiSoHieuSuat.saleHomNay;
        }

        return `${icon}${item.tenNhanVien}: ${val}/${mtd}/${chiTieu}`;
    });
    return `TNH ngày ${dinhDangNgayHienThi(reportObj.ngayBaoCao)}\n🔥${tk.tongSoFOS} FOS – ${tk.tongSoMC} MC\n✅NTB: ${tk.tongSoNTB}\n✅NSBQ: ${tk.NSBQ_NTB}\n✅ETB: ${tk.tongSoETB}\n✅AE+: ${tk.tongSoAEPlus}\n✅Pos: ${tk.tyLePOS}\n\n⭐️Active ${tk.tyLeActiveFOS}\n${ds.join('\n')}`;
};

$(() => {
    khoiTaoGiaoDien();
    xayDungMenuGiaoDien();
    taiDuLieuTuServer();
    initUIHandlers();
});

@import "./themes.css";

/* --- Glow Engine (Inspired by jh3y) --- */
@property --glow-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

:root {
  --glow-size: 300px;
  --glow-speed: 4s;
  --glow-opacity: 0.15;
  --glow-blur: 40px;
}

[data-glow] {
  --border-size: 1px;
  --spotlight-size: var(--glow-size);
  --hue: 210;
  position: relative;
  border-radius: 1.5rem;
}

[data-glow]::before,
[data-glow]::after {
  content: "";
  position: absolute;
  inset: calc(var(--border-size) * -1);
  border: var(--border-size) solid transparent;
  border-radius: inherit;
  background-attachment: fixed;
  background-size: var(--spotlight-size) var(--spotlight-size);
  background-repeat: no-repeat;
  mask: linear-gradient(transparent, transparent), linear-gradient(white, white);
  mask-clip: padding-box, border-box;
  mask-composite: intersect;
  pointer-events: none;
}

/* Biểu đồ phát sáng viền */
[data-glow]::before {
  background-image: radial-gradient(
    circle at var(--x, 0) var(--y, 0),
    var(--accent-blue) 0%,
    transparent 50%
  );
  z-index: 1;
}

/* Quầng sáng phía sau */
[data-glow] > [data-glow-child] {
  position: relative;
  z-index: 2;
  border-radius: inherit;
  background: var(--card-bg);
  backdrop-filter: blur(25px) saturate(200%);
  height: 100%;
}

/* --- ÉP MÀU CHỮ --- */
h1, h2, h3, h4, h5, h6, .main-title, .card-title, .modal-title, .form-label, strong, b {
    color: var(--text-primary) !important;
}

body, p, span, li, a:not(.btn), label {
    color: var(--text-primary);
}

.text-muted, .subtitle-text, .status-detail {
    color: var(--text-secondary) !important;
}

/* --- UI BASE --- */
#lop-phu-tai-trang {
    position: fixed; top: 0; left: 0;
    width: 100%; height: 100%;
    background: rgba(0, 0, 0, 0.7);
    backdrop-filter: blur(10px);
    display: none; flex-direction: column;
    justify-content: center; align-items: center;
    z-index: 9999; color: white;
}

body {
    font-family: 'Poppins', sans-serif;
    background-color: var(--bg-gradient);
    background-image: var(--bg-image), var(--bg-gradient);
    background-size: cover; background-position: center; background-attachment: fixed;
    color: var(--text-primary);
    transition: background 0.5s ease, color 0.3s ease;
    min-height: 100vh;
    margin: 0;
}

.settings-container { position: fixed; top: 25px; right: 25px; z-index: 1100; }

#nut-cai-dat {
    cursor: pointer; font-size: 1.5rem; color: var(--accent-blue);
    background: var(--card-bg); width: 50px; height: 50px;
    display: flex; align-items: center; justify-content: center;
    border-radius: 50%; box-shadow: 0 8px 32px rgba(0,0,0,0.15);
    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    backdrop-filter: blur(10px); border: 1px solid rgba(255, 255, 255, 0.1);
}
#nut-cai-dat:hover { transform: rotate(90deg) scale(1.1); }

/* --- DROPDOWN & SUBMENU --- */
.dropdown-menu {
    border-radius: 1rem; padding: 0.5rem;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: var(--card-bg); backdrop-filter: blur(25px);
    box-shadow: 0 15px 45px rgba(0,0,0,0.2) !important;
    min-width: 200px;
}

.dropdown-item {
    border-radius: 0.6rem; padding: 0.6rem 1rem;
    color: var(--text-primary) !important;
    display: flex; align-items: center; justify-content: space-between;
}
.dropdown-item:hover { background-color: rgba(0, 122, 255, 0.1); color: var(--accent-blue) !important; }

.dropdown-submenu { position: relative; }
.dropdown-submenu > .dropdown-menu {
    top: 0; right: 100%; left: auto;
    margin-top: -5px; margin-right: 0px;
    display: none;
}
.dropdown-submenu > .dropdown-menu::before {
    content: ""; position: absolute;
    top: 0; right: -15px; width: 20px; height: 100%;
}
.dropdown-submenu:hover > .dropdown-menu { display: block; }

.dropdown-submenu > .dropdown-toggle::after {
    display: inline-block; margin-left: 0.5rem; vertical-align: middle;
    content: ""; border-top: .3em solid transparent; border-right: .3em solid;
    border-bottom: .3em solid transparent; border-left: 0;
}

.form-control, .form-select {
    background-color: var(--input-bg);
    color: var(--text-primary) !important;
    border: 1px solid var(--input-border);
    border-radius: 0.75rem;
}

.card, .modal-content {
    background: transparent;
    border: none;
    border-radius: 1.5rem;
}

#vung-danh-sach-nv {
    max-height: 450px; overflow-y: auto;
    padding: 12px; margin-bottom: 20px;
    border-radius: 1.25rem; background: rgba(0,0,0,0.03);
}

.nut-ten-nv {
