const getZodiac = (day, month) => {
    const signs = ["Ma Kết", "Bảo Bình", "Song Ngư", "Bạch Dương", "Kim Ngưu", "Song Tử", "Cự Giải", "Sư Tử", "Xử Nữ", "Thiên Bình", "Bọ Cạp", "Nhân Mã"];
    const lastDays = [19, 18, 20, 19, 20, 20, 22, 22, 22, 22, 21, 21];
    return day > lastDays[month - 1] ? signs[month % 12] : signs[month - 1];
};

const getChineseZodiac = (year) => {
    const animals = ["Tý", "Sửu", "Dần", "Mão", "Thìn", "Tỵ", "Ngọ", "Mùi", "Thân", "Dậu", "Tuất", "Hợi"];
    // Offset for 1900 which was a Year of the Rat (Tý)
    return animals[(year - 1900) % 12];
};

const animateValue = (id, start, end, duration) => {
    const obj = document.getElementById(id);
    if (!obj) return;
    let startTimestamp = null;
    const step = (timestamp) => {
        if (!startTimestamp) startTimestamp = timestamp;
        const progress = Math.min((timestamp - startTimestamp) / duration, 1);
        obj.innerHTML = Math.floor(progress * (end - start) + start).toString();
        if (progress < 1) {
            window.requestAnimationFrame(step);
        }
    };
    window.requestAnimationFrame(step);
};

$(function() {
    // Thiết lập ngày tối đa là hôm nay
    const today = new Date().toISOString().split('T')[0];
    $('#input-birthdate').attr('max', today);

    $('#btn-calculate').on('click', function() {
        const birthDateVal = $('#input-birthdate').val();
        if (!birthDateVal) {
            hienThiThongBao("Vui lòng chọn ngày sinh!", "error");
            return;
        }

        const birthDate = new Date(birthDateVal);
        const now = new Date();

        let years = now.getFullYear() - birthDate.getFullYear();
        let months = now.getMonth() - birthDate.getMonth();
        let days = now.getDate() - birthDate.getDate();

        if (days < 0) {
            months--;
            const lastMonth = new Date(now.getFullYear(), now.getMonth(), 0);
            days += lastMonth.getDate();
        }

        if (months < 0) {
            years--;
            months += 12;
        }

        // Tính sinh nhật kế tiếp
        let nextBirthday = new Date(now.getFullYear(), birthDate.getMonth(), birthDate.getDate());
        if (nextBirthday < now) {
            nextBirthday.setFullYear(now.getFullYear() + 1);
        }
        const diffTime = Math.abs(nextBirthday.getTime() - now.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        // Hiển thị
        $('#result-section').hide().removeClass('d-none').fadeIn(500);

        animateValue("res-years", 0, years, 1000);
        animateValue("res-months", 0, months, 1000);
        animateValue("res-days", 0, days, 1000);

        $('#res-zodiac').text(getZodiac(birthDate.getDate(), birthDate.getMonth() + 1));
        $('#res-chinese').text(getChineseZodiac(birthDate.getFullYear()));
        $('#res-next').text(`${diffDays} ngày nữa`);

        hienThiThongBao("Đã tính toán xong!");
    });

    $('#btn-random-theme').on('click', function() {
        const t = THEMES[Math.floor(Math.random() * THEMES.length)];
        $('body').attr('class', `py-4 theme-${t.id}-${t.mode}`);
    });
});

