// Sử dụng jQuery thuần để xử lý logic
declare var $: any;

$(function() {
    console.log("Age Calculator Ready");

    const getZodiac = (day: number, month: number) => {
        const zodiacSigns = [
            "Ma Kết", "Bảo Bình", "Song Ngư", "Bạch Dương", "Kim Ngưu", "Song Tử", 
            "Cự Giải", "Sư Tử", "Xử Nữ", "Thiên Bình", "Bọ Cạp", "Nhân Mã"
        ];
        const lastDays = [19, 18, 20, 19, 20, 20, 22, 22, 22, 22, 21, 21];
        return day > lastDays[month - 1] ? zodiacSigns[month % 12] : zodiacSigns[month - 1];
    };

    $('#btn-calc').on('click', function() {
        const birthDateVal = $('#birth-date').val();

        if (!birthDateVal) {
            alert("Vui lòng chọn ngày sinh!");
            return;
        }

        const birthDate = new Date(birthDateVal);
        const today = new Date();

        if (birthDate > today) {
            alert("Ngày sinh không thể lớn hơn ngày hiện tại!");
            return;
        }

        let years = today.getFullYear() - birthDate.getFullYear();
        let months = today.getMonth() - birthDate.getMonth();
        let days = today.getDate() - birthDate.getDate();

        // Xử lý nếu số ngày âm
        if (days < 0) {
            months--;
            const lastMonth = new Date(today.getFullYear(), today.getMonth(), 0);
            days += lastMonth.getDate();
        }

        // Xử lý nếu số tháng âm
        if (months < 0) {
            years--;
            months += 12;
        }

        // Hiển thị kết quả với hiệu ứng
        $('#results').fadeOut(100, function() {
            $('#val-years').text(years);
            $('#val-months').text(months);
            $('#val-days').text(days);

            const zodiac = getZodiac(birthDate.getDate(), birthDate.getMonth() + 1);
            $('#zodiac-name').text(zodiac);

            $(this).fadeIn(400);
        });
    });

    // Giới hạn ngày chọn tối đa là hôm nay
    const todayStr = new Date().toISOString().split('T')[0];
    $('#birth-date').attr('max', todayStr);
});

