        const mapLs = new Map();
        if (baoCaoLichSuGanNhat?.duLieuNvLichSu) baoCaoLichSuGanNhat.duLieuNvLichSu.forEach((n: any) => mapLs.set(n.ten, n));

        danhSachNhanVien.forEach(nv => {
            const icon = nv.gioiTinh === 'Nữ' ? '👵' : '👨';
            const bc = nv.baoCao || '';
            let mtd = trichXuatSoLieu(bc, 'MTD MC');
            let ntb = trichXuatSoLieu(bc, 'NTB'), etb = trichXuatSoLieu(bc, 'ETB');
            let mcNay = ntb + etb;
            if (mcNay === 0) mcNay = trichXuatSoLieu(bc, ['Tổng MC', 'MC']);

            if ((nv.trangThai === 'Off' || mcNay === 0) && mtd === 0 && baoCaoLichSuGanNhat) {
                const ls = mapLs.get(nv.ten); mtd = ls ? (ls.mtdMC || 0) : 0;
            }

            if (nv.trangThai === 'Off') {
                const m = bc.match(/^Fos\s+\S+\s+(.*)$/i);
                dsChiTiet.push(`${icon}${nv.ten}: ${(m && m[1]) ? m[1].toUpperCase() : 'OFF'}/${mtd}/${nv.chiTieu}`);
            } else {
                nvActive++; tMC += mcNay; tNTB += ntb; tETB += etb;
                tPos += trichXuatSoLieu(bc, 'Pos'); tAE += trichXuatSoLieu(bc, ['AE+', 'AE Plus']);
                dsChiTiet.push(`${icon}${nv.ten}: ${mcNay}/${mtd}/${nv.chiTieu}`);
            }
        });

        const nsbqNTB = (nvActive > 0) ? (tNTB / nvActive).toFixed(2) : '0.00';
        const res = `TNH ngày ${ngayHienThi}\n🔥${danhSachNhanVien.length} FOS – ${tMC} MC\n✅NTB: ${tNTB}\n✅NSBQ: ${nsbqNTB}\n✅ETB: ${tETB}\n✅AE+: ${tAE}\n✅Pos: ${tPos}/${danhSachNhanVien.length * 3}\n\n⭐️Active ${nvActive}/${danhSachNhanVien.length}\n${dsChiTiet.join('\n')}`;

        $('#vung-ket-qua-bao-cao').val(res);
        luuVaoBoNhoTam();

        if (layCheDoUngDung() === 'online') {
            $('#chi-bao-dang-luu').css('display', 'flex').fadeIn();
            const cauTruc = {
                ngayBaoCao: dinhDangNgayISO(new Date()),
                tongKetToanDoi: { tongSoFOS: danhSachNhanVien.length, tongSoMC: tMC, tongSoNTB: tNTB, NSBQ_NTB: parseFloat(nsbqNTB), tongSoETB: tETB, NSBQ_ETB: (tETB/nvActive || 0), tongSoAEPlus: tAE, tyLePOS: `${tPos}/${danhSachNhanVien.length * 3}`, tyLeActiveFOS: `${nvActive}/${danhSachNhanVien.length}` },
                baoCaoFOS: danhSachNhanVien.map(nv => ({ tenNhanVien: nv.ten, OFF: nv.trangThai === 'Off' ? 1 : 0, chiSoHieuSuat: { saleHomNay: nv.trangThai === 'Off' ? 0 : (trichXuatSoLieu(nv.baoCao, 'NTB') + trichXuatSoLieu(nv.baoCao, 'ETB')), saleTrongThang: trichXuatSoLieu(nv.baoCao, 'MTD MC'), chiTieu: nv.chiTieu }, rawReport: nv.baoCao }))
            };
            try {
                const queryExist = encodeURIComponent(`{"ngayBaoCao":"${cauTruc.ngayBaoCao}"}`);
                const check = await thucHienGoiApi(`report?q=${queryExist}`);
                if (check.length > 0) await thucHienGoiApi(`report/${check[0]._id}`, 'PUT', cauTruc);
                else await thucHienGoiApi('report', 'POST', cauTruc);
                hienThiThongBao("Đã lưu báo cáo lên Server");
                lamMoiThongKeCsdl();
            } catch(e) { hienThiThongBao("Lỗi khi lưu server", "error"); }
            finally { setTimeout(() => $('#chi-bao-dang-luu').fadeOut(), 1000); }
        }
    };

    // --- BINDING EVENTS ---
    $('#nut-tao-bao-cao').on('click', thucHienTaoBaoCao);
    $('#nut-sao-chep').on('click', () => {
        const val = $('#vung-ket-qua-bao-cao').val();
        if (val) navigator.clipboard.writeText(val).then(() => hienThiThongBao("Đã sao chép!"));
    });

    $('body').on('click', '.nut-ten-nv', function(this: any) {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { 
            $('#modalDanBaoCaoLabel').text(`Báo cáo: ${nhanVienHienTai}`); 
            $('#noi-dung-bao-cao-nhap').val(nv.baoCao); 
            modalDanBaoCao.show(); 
        }
    });

    $('#nut-luu-bao-cao-don').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const nd = $('#noi-dung-bao-cao-nhap').val();
            nv.baoCao = nd; nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, nd);
            hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide();
        }
    });

    $('#nut-danh-dau-off').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) { nv.baoCao = `Fos ${nv.ten} OFF`; nv.trangThai = 'Off'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanBaoCao.hide(); }
    });

    $('#vung-danh-sach-nv').on('click', '.nut-sua-nhanh-nv', function(this: any) {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const bc = nv.baoCao;
            $('#ntb-sua').val(trichXuatSoLieu(bc, 'NTB')); $('#etb-sua').val(trichXuatSoLieu(bc, 'ETB'));
            $('#pos-sua').val(trichXuatSoLieu(bc, 'Pos')); $('#aeplus-sua').val(trichXuatSoLieu(bc, 'AE+'));
            $('#mtd-sua').val(trichXuatSoLieu(bc, 'MTD MC'));
            modalSuaBaoCao.show();
        }
    });

    $('#nut-xac-nhan-sua-bao-cao').on('click', () => {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            const n = parseInt($('#ntb-sua').val() as string) || 0, e = parseInt($('#etb-sua').val() as string) || 0;
            nv.baoCao = `Fos ${nv.ten}\nNTB: ${n}\nETB: ${e}\nAE+: ${$('#aeplus-sua').val()}\nPos: ${$('#pos-sua').val()}\nMTD MC: ${$('#mtd-sua').val()}`;
            nv.trangThai = 'Đã báo cáo'; hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalSuaBaoCao.hide();
        }
    });

    $('#nut-xu-ly-nhieu-bao-cao').on('click', () => {
        const txt = $('#noi-dung-nhieu-bao-cao-nhap').val() as string;
        txt.split(/(?=^Fos\s)/im).forEach(khoi => {
            const nv = danhSachNhanVien.find(n => new RegExp(`^Fos\\s+${n.ten}`, 'i').test(khoi.trim()));
            if (nv) { nv.baoCao = khoi.trim(); nv.trangThai = 'Đã báo cáo'; kiemTraTenTrongBaoCao(nv, khoi.trim()); }
        });
        hienThiDanhSachNhanVien(); luuVaoBoNhoTam(); modalDanNhieuBaoCao.hide();
    });

    $('#nut-xem-bao-cao-cu-kich-hoat').on('click', () => modalLichSu.show());

    $('#nut-luu-nv-moi').on('click', async () => {
        const ten = ($('#ten-nv-modal').val() as string).trim(), gt = $('#gioi-tinh-nv-modal').val(), ct = $('#chi-tieu-nv-modal').val();
        if (ten) {
            try { await thucHienGoiApi('nhanvien', 'POST', { Ten: ten, GioiTinh: gt, ChiTieu: ct }); modalThemNv.hide(); taiDuLieuTuServer(); }
            catch (e: any) { hienThiThongBao("Lỗi thêm NV", 'error'); }
        }
    });

    $('#vung-danh-sach-nv').on('click', '.nut-xoa-nv-kich-hoat', function(this: any) {
        nhanVienCanXoa = { id: $(this).data('nv-id'), ten: $(this).data('nv-ten') };
        $('#noi-dung-xac-nhan-xoa').text(`Xoá vĩnh viễn ${nhanVienCanXoa.ten}?`);
        modalXacNhanXoa.show();
    });

    $('#nut-xac-nhan-xoa-vinh-vien').on('click', async () => {
        try { await thucHienGoiApi(`nhanvien/${nhanVienCanXoa.id}`, 'DELETE'); taiDuLieuTuServer(); modalXacNhanXoa.hide(); }
        catch (e: any) { hienThiThongBao("Lỗi khi xoá", 'error'); }
    });

    // Theme & Khởi động
    $('body').attr('class', 'py-4 theme-ios18-light');
    taiDuLieuTuServer();
});

:root {
    --primary-color: #007AFF;
    --primary-hover: #0056b3;
    --bg-light: #f5f7fa;
    --card-bg-light: rgba(255, 255, 255, 0.7);
    --text-light: #1d1d1f;
    --input-bg-light: #f2f2f7;

    --bg-dark: #000000;
    --card-bg-dark: rgba(28, 28, 30, 0.7);
    --text-dark: #f5f5f7;
    --input-bg-dark: #1c1c1e;
}

body {
    font-family: 'Inter', sans-serif;
    transition: background-color 0.3s ease, color 0.3s ease;
    overflow-x: hidden;
}

body.theme-light {
    background-color: var(--bg-light);
    color: var(--text-light);
}

body.theme-dark {
    background-color: var(--bg-dark);
    color: var(--text-dark);
}

/* Background Blobs */
.background-blobs {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
    overflow: hidden;
}

.blob {
    position: absolute;
    width: 400px;
    height: 400px;
    border-radius: 50%;
    filter: blur(80px);
    opacity: 0.4;
    animation: move 20s infinite alternate;
}

.blob-1 {
    background: #007AFF;
    top: -100px;
    right: -100px;
}

.blob-2 {
    background: #FF2D55;
    bottom: -100px;
    left: -100px;
}

@keyframes move {
    from { transform: translate(0, 0); }
    to { transform: translate(100px, 100px); }
}

/* Glass Card */
.glass-card {
    backdrop-filter: blur(25px);
    -webkit-backdrop-filter: blur(25px);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 2rem;
    width: 100%;
    max-width: 500px;
}

body.theme-light .glass-card {
    background: var(--card-bg-light);
}

body.theme-dark .glass-card {
    background: var(--card-bg-dark);
    border: 1px solid rgba(255, 255, 255, 0.1);
}

/* Form Elements */
.custom-input-group {
    border-radius: 1rem;
    overflow: hidden;
    transition: background-color 0.3s ease;
}

body.theme-light .custom-input-group {
    background-color: var(--input-bg-light);
}

body.theme-dark .custom-input-group {
    background-color: var(--input-bg-dark);
}

.form-control:focus {
    box-shadow: none;
}

/* Results */
.result-box {
