}

@media (max-width: 576px) {
    .glass-card {
        margin: 15px;
    }
}

/**
 * Tính toán tuổi dựa trên ngày sinh
 * @param {string} birthDateStr - Chuỗi ngày định dạng YYYY-MM-DD
 * @returns {object} Kết quả năm, tháng, ngày và tổng số ngày
 */
export const calculateAge = (birthDateStr) => {
    const today = new Date();
    const birthDate = new Date(birthDateStr);

    let years = today.getFullYear() - birthDate.getFullYear();
    let months = today.getMonth() - birthDate.getMonth();
    let days = today.getDate() - birthDate.getDate();

    // Điều chỉnh nếu ngày hiện tại nhỏ hơn ngày sinh trong tháng
    if (days < 0) {
        months--;
        // Lấy số ngày của tháng trước
        const lastMonth = new Date(today.getFullYear(), today.getMonth(), 0);
        days += lastMonth.getDate();
    }

    // Điều chỉnh nếu tháng hiện tại nhỏ hơn tháng sinh
    if (months < 0) {
        years--;
        months += 12;
    }

    // Tính tổng số ngày đã sống
    const diffTime = Math.abs(today.getTime() - birthDate.getTime());
    const totalDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    return { years, months, days, totalDays };
};

