};

export const apDungGiaoDien = (className) => {
    $('body').attr('class', 'py-4 ' + className);
};

export const luuCauHinhGiaoDien = (className) => {
    localStorage.setItem('theme_preference', className);
};

export const apDungGiaoDienNgauNhien = () => {
    const t = THEMES[Math.floor(Math.random() * THEMES.length)];
    const m = Math.random() > 0.5 ? 'light' : 'dark';
    apDungGiaoDien(`theme-${t.id}-${m}`);
};

import { thucHienGoiApi, lamMoiThongKeCsdl, ghiNhanTuongTacApi } from './api.js';
import { dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu, hienThiThongBao } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien, apDungGiaoDien, luuCauHinhGiaoDien } from './theme.js';
import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';

$(function() {
    let danhSachNhanVien = [];
    let nhanVienHienTai = null;

    // Khởi tạo giao diện
    khoiTaoGiaoDien();
    xayDungMenuGiaoDien();
    $('#hien-thi-ngay').text(dinhDangNgayHienThi(new Date()));

    const hienThiDanhSachNhanVien = () => {
        const $vung = $('#vung-danh-sach-nv');
        if (danhSachNhanVien.length === 0) {
            $vung.html('<div class="text-center py-4 text-muted small w-100">Không có dữ liệu nhân viên.</div>');
            return;
        }

        let html = '';
        danhSachNhanVien.forEach(nv => {
            let lopNut = 'btn w-100 text-start py-2 px-3 rounded-4 shadow-sm nut-ten-nv mb-2';
            if (nv.trangThai === 'Đã báo cáo') lopNut += ' btn-reported';
            else if (nv.trangThai === 'Off') lopNut += ' btn-off';
            else lopNut += ' btn-light';

            html += `
                <div class="col-6 col-md-4 col-lg-3">
                    <button class="${lopNut}" data-nv-ten="${nv.ten}">
                        <div class="fw-bold small mb-0">${nv.ten}</div>
                        <div class="small opacity-50" style="font-size: 0.7rem;">${nv.trangThai}</div>
                    </button>
                </div>
            `;
        });
        $vung.html(html);
    };

    const taiDuLieuServer = async () => {
        try {
            // Mã hóa hint orderby cho RestDB
            const hint = encodeURIComponent('{"Ten":1}');
            const data = await thucHienGoiApi(`nhanvien?h={"$orderby":${hint}}`);

            if (data && Array.isArray(data)) {
                danhSachNhanVien = data.map(i => ({
                    _id: i._id,
                    ten: i.Ten,
                    gioiTinh: i.GioiTinh,
                    chiTieu: parseInt(i.ChiTieu) || 50,
                    trangThai: 'Chưa báo cáo',
                    baoCao: ''
                }));
            }

            // Khôi phục từ bộ nhớ tạm
            const tamStr = localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO);
            if (tamStr) {
                const tam = JSON.parse(tamStr);
                if (tam.ngay === dinhDangNgayISO(new Date())) {
                    tam.duLieuNv?.forEach(t => {
                        const nv = danhSachNhanVien.find(n => n._id === t._id);
                        if (nv) {
                            nv.trangThai = t.trangThai;
                            nv.baoCao = t.baoCao;
                        }
                    });
                }
            }

            hienThiDanhSachNhanVien();

            lamMoiThongKeCsdl((ok, slNv, slBc, access) => {
                const $dot = $('#cham-trang-thai-db');
                $dot.removeClass('online offline').addClass(ok ? 'online' : 'offline');
                $('#chu-trang-thai-db').text(ok ? 'RestDB Connected' : 'Disconnected');
                $('#so-luong-nv-db').text(`NV: ${slNv}`);
                $('#so-luong-bao-cao-db').text(`BC: ${slBc}`);
                $('#luong-truy-cap-api').text(`(${access})`);
            });

            ghiNhanTuongTacApi();
        } catch (e) {
            console.error("Lỗi tải dữ liệu:", e);
            hienThiThongBao("Lỗi kết nối server", "error");
        } finally {
            $('#lop-phu-tai-trang').fadeOut();
        }
    };

    // Events
    $(document).on('click', '.nut-ten-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            $('#modalDanBaoCaoLabel').text(`Báo cáo: ${nhanVienHienTai}`);
            $('#noi-dung-bao-cao-nhap').val(nv.baoCao || '');
            const modal = new bootstrap.Modal(document.getElementById('modal-dan-bao-cao'));
            modal.show();
        }
    });

    $('#nut-luu-bao-cao-don').on('click', function() {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            nv.baoCao = $('#noi-dung-bao-cao-nhap').val();
            nv.trangThai = 'Đã báo cáo';
            hienThiDanhSachNhanVien();
            bootstrap.Modal.getInstance(document.getElementById('modal-dan-bao-cao')).hide();
            hienThiThongBao(`Đã cập nhật ${nv.ten}`);
            luuTamLocalStorage();
        }
    });

    $('#nut-danh-dau-off').on('click', function() {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            nv.baoCao = `Fos ${nv.ten} OFF`;
            nv.trangThai = 'Off';
            hienThiDanhSachNhanVien();
            bootstrap.Modal.getInstance(document.getElementById('modal-dan-bao-cao')).hide();
            luuTamLocalStorage();
        }
    });

    const luuTamLocalStorage = () => {
        localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify({
            ngay: dinhDangNgayISO(new Date()),
            duLieuNv: danhSachNhanVien.map(n => ({ _id: n._id, trangThai: n.trangThai, baoCao: n.baoCao }))
        }));
    };

    $('#nut-tao-bao-cao').on('click', function() {
        let tMC = 0, tNTB = 0, tETB = 0, tPos = 0, tAE = 0, active = 0;
        let details = [];

        danhSachNhanVien.forEach(nv => {
            const bc = nv.baoCao || '';
            const n = trichXuatSoLieu(bc, 'NTB');
            const e = trichXuatSoLieu(bc, 'ETB');
            const mtd = trichXuatSoLieu(bc, 'MTD MC');
            const mc = n + e || trichXuatSoLieu(bc, 'MC');

            if (nv.trangThai === 'Off') {
                details.push(`- ${nv.ten}: OFF (${mtd}/${nv.chiTieu})`);
            } else {
                active++; tMC += mc; tNTB += n; tETB += e;
                tPos += trichXuatSoLieu(bc, 'Pos');
                tAE += trichXuatSoLieu(bc, 'AE+');
                details.push(`- ${nv.ten}: ${mc}/${mtd}/${nv.chiTieu}`);
            }
        });

        const res = `BÁO CÁO FOS ${dinhDangNgayHienThi(new Date())}\n` +
                    `Tổng MC: ${tMC} | NTB: ${tNTB} | ETB: ${tETB}\n` +
                    `AE+: ${tAE} | Pos: ${tPos}\n` +
                    `Hoạt động: ${active}/${danhSachNhanVien.length}\n\n` +
                    `CHI TIẾT:\n${details.join('\n')}`;

        $('#vung-ket-qua-bao-cao').val(res);
        hienThiThongBao("Đã tổng hợp báo cáo!");
        luuTamLocalStorage();
    });

    $('#nut-sao-chep').on('click', function() {
        const val = $('#vung-ket-qua-bao-cao').val();
        if (val) {
            navigator.clipboard.writeText(val).then(() => hienThiThongBao("Đã sao chép vào bộ nhớ tạm"));
        }
    });

    $(document).on('click', '.lua-chon-giao-dien', function(e) {
        e.preventDefault();
        const theme = $(this).data('theme');
        const mode = $(this).data('mode');
        const className = `theme-${theme}-${mode}`;
        apDungGiaoDien(className);
        luuCauHinhGiaoDien(className);
    });

    // Khởi động
    taiDuLieuServer();
});

import { thucHienGoiApi, lamMoiThongKeCsdl, ghiNhanTuongTacApi, datCheDoUngDung } from './api.js';
import { dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu, hienThiThongBao } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien, apDungGiaoDien, luuCauHinhGiaoDien } from './theme.js';
import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';

$(function() {
    let danhSachNhanVien = [];
    let nhanVienHienTai = null;

    // Khởi tạo giao diện ban đầu
    khoiTaoGiaoDien();
    xayDungMenuGiaoDien();
    $('#hien-thi-ngay').text(dinhDangNgayHienThi(new Date()));

    const hienThiDanhSachNhanVien = () => {
        const $vung = $('#vung-danh-sach-nv');
        if (danhSachNhanVien.length === 0) {
            $vung.html('<div class="text-center py-4 text-muted small w-100">Không có dữ liệu nhân viên.</div>');
            return;
        }

        let html = '';
        danhSachNhanVien.forEach(nv => {
            let lopNut = 'btn w-100 text-start py-2 px-3 rounded-4 shadow-sm nut-ten-nv mb-2';
            if (nv.trangThai === 'Đã báo cáo') lopNut += ' btn-reported';
            else if (nv.trangThai === 'Off') lopNut += ' btn-off';
            else lopNut += ' btn-light';

            html += `
                <div class="col-6 col-md-4 col-lg-3">
                    <button class="${lopNut}" data-nv-ten="${nv.ten}">
                        <div class="fw-bold small mb-0 text-truncate">${nv.ten}</div>
                        <div class="small opacity-50" style="font-size: 0.7rem;">${nv.trangThai}</div>
                    </button>
                </div>
            `;
        });
        $vung.html(html);
    };

    const taiDuLieuTuFileLocal = async () => {
        try {
            const response = await fetch('fos.txt');
            if (!response.ok) throw new Error("Không tìm thấy file fos.txt");
            const text = await response.text();

            // Format: Tên|Giới tính|Chỉ tiêu
            const lines = text.split('\n').filter(line => line.trim() !== '');
            const localData = lines.map((line, index) => {
                const parts = line.split('|');
                return {
                    _id: `local_${index}`,
                    ten: parts[0]?.trim() || 'No Name',
                    gioiTinh: parts[1]?.trim() || 'Nam',
                    chiTieu: parseInt(parts[2]) || 50,
                    trangThai: 'Chưa báo cáo',
                    baoCao: ''
                };
            });

            if (localData.length > 0) {
                danhSachNhanVien = localData;
                datCheDoUngDung('offline');
                hienThiThongBao("Đang sử dụng dữ liệu dự phòng từ fos.txt", "error");
                khoiPhucDuLieuTam();
                hienThiDanhSachNhanVien();
                capNhatWidgetTrangThai(false, localData.length, 0, 0);
            }
        } catch (error) {
            console.error("Lỗi tải file local:", error);
            hienThiThongBao("Không thể tải danh sách nhân viên!", "error");
        }
    };

    const khoiPhucDuLieuTam = () => {
        const tamStr = localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO);
        if (tamStr) {
            const tam = JSON.parse(tamStr);
            if (tam.ngay === dinhDangNgayISO(new Date())) {
                tam.duLieuNv?.forEach(t => {
                    const nv = danhSachNhanVien.find(n => n.ten === t.ten); // Tìm theo tên vì ID local có thể khác ID server
                    if (nv) {
                        nv.trangThai = t.trangThai;
                        nv.baoCao = t.baoCao;
                    }
                });
            }
        }
    };

    const capNhatWidgetTrangThai = (ok, slNv, slBc, access) => {
        const $dot = $('#cham-trang-thai-db');
        $dot.removeClass('online offline').addClass(ok ? 'online' : 'offline');
        $('#chu-trang-thai-db').text(ok ? 'RestDB Online' : 'Local Mode');
        $('#so-luong-nv-db').text(`NV: ${slNv}`);
        $('#so-luong-bao-cao-db').text(`BC: ${slBc}`);
        $('#luong-truy-cap-api').text(`(${access})`);
    };

    const taiDuLieuServer = async () => {
        try {
            const hint = encodeURIComponent('{"Ten":1}');
            const data = await thucHienGoiApi(`nhanvien?h={"$orderby":${hint}}`);

            if (data && Array.isArray(data)) {
                danhSachNhanVien = data.map(i => ({
                    _id: i._id,
                    ten: i.Ten,
                    gioiTinh: i.GioiTinh,
                    chiTieu: parseInt(i.ChiTieu) || 50,
                    trangThai: 'Chưa báo cáo',
                    baoCao: ''
                }));
                datCheDoUngDung('online');
                khoiPhucDuLieuTam();
                hienThiDanhSachNhanVien();

                lamMoiThongKeCsdl((ok, slNv, slBc, access) => {
                    capNhatWidgetTrangThai(ok, slNv, slBc, access);
                });
                ghiNhanTuongTacApi();
            } else {
                throw new Error("Dữ liệu server trống");
            }
        } catch (e) {
            console.warn("Server lỗi, chuyển sang chế độ dự phòng:", e);
            await taiDuLieuTuFileLocal();
        } finally {
            $('#lop-phu-tai-trang').fadeOut();
        }
    };

    // Events
    $(document).on('click', '.nut-ten-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            $('#modalDanBaoCaoLabel').text(`Báo cáo: ${nhanVienHienTai}`);
            $('#noi-dung-bao-cao-nhap').val(nv.baoCao || '');
            const modal = new bootstrap.Modal(document.getElementById('modal-dan-bao-cao'));
            modal.show();
        }
    });

    $('#nut-luu-bao-cao-don').on('click', function() {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            nv.baoCao = $('#noi-dung-bao-cao-nhap').val();
            nv.trangThai = 'Đã báo cáo';
            hienThiDanhSachNhanVien();
            bootstrap.Modal.getInstance(document.getElementById('modal-dan-bao-cao')).hide();
            hienThiThongBao(`Đã cập nhật ${nv.ten}`);
            luuTamLocalStorage();
        }
    });

    $('#nut-danh-dau-off').on('click', function() {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            nv.baoCao = `Fos ${nv.ten} OFF`;
            nv.trangThai = 'Off';
            hienThiDanhSachNhanVien();
            bootstrap.Modal.getInstance(document.getElementById('modal-dan-bao-cao')).hide();
            luuTamLocalStorage();
        }
    });

    const luuTamLocalStorage = () => {
        localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify({
            ngay: dinhDangNgayISO(new Date()),
            duLieuNv: danhSachNhanVien.map(n => ({ ten: n.ten, trangThai: n.trangThai, baoCao: n.baoCao }))
        }));
    };

    $('#nut-tao-bao-cao').on('click', function() {
        let tMC = 0, tNTB = 0, tETB = 0, tPos = 0, tAE = 0, active = 0;
        let details = [];

        danhSachNhanVien.forEach(nv => {
            const bc = nv.baoCao || '';
            const n = trichXuatSoLieu(bc, 'NTB');
            const e = trichXuatSoLieu(bc, 'ETB');
            const mtd = trichXuatSoLieu(bc, 'MTD MC');
            const mc = n + e || trichXuatSoLieu(bc, 'MC');

            if (nv.trangThai === 'Off') {
                details.push(`- ${nv.ten}: OFF (${mtd}/${nv.chiTieu})`);
            } else if (nv.trangThai === 'Đã báo cáo') {
                active++; tMC += mc; tNTB += n; tETB += e;
                tPos += trichXuatSoLieu(bc, 'Pos');
                tAE += trichXuatSoLieu(bc, 'AE+');
                details.push(`- ${nv.ten}: ${mc}/${mtd}/${nv.chiTieu}`);
            } else {
                details.push(`- ${nv.ten}: Chưa báo cáo`);
            }
        });

        const res = `BÁO CÁO FOS ${dinhDangNgayHienThi(new Date())}\n` +
                    `Tổng MC: ${tMC} | NTB: ${tNTB} | ETB: ${tETB}\n` +
                    `AE+: ${tAE} | Pos: ${tPos}\n` +
                    `Hoạt động: ${active}/${danhSachNhanVien.length}\n\n` +
                    `CHI TIẾT:\n${details.join('\n')}`;

        $('#vung-ket-qua-bao-cao').val(res);
        hienThiThongBao("Đã tổng hợp báo cáo!");
        luuTamLocalStorage();
    });

    $('#nut-sao-chep').on('click', function() {
        const val = $('#vung-ket-qua-bao-cao').val();
        if (val) {
            navigator.clipboard.writeText(val).then(() => hienThiThongBao("Đã sao chép vào bộ nhớ tạm"));
        }
    });

    $(document).on('click', '.lua-chon-giao-dien', function(e) {
        e.preventDefault();
        const theme = $(this).data('theme');
        const mode = $(this).data('mode');
        const className = `theme-${theme}-${mode}`;
        apDungGiaoDien(className);
        luuCauHinhGiaoDien(className);
    });

    // Bắt đầu quy trình tải dữ liệu
    taiDuLieuServer();
});

import { DUONG_DAN_CSDL, TIEU_DE_TRUY_VAN } from './config.js';
import { dinhDangNgayISO } from './utils.js';

let cheDoUngDung = 'online';

export const datCheDoUngDung = (cheDo) => {
    cheDoUngDung = cheDo;
};

export const layCheDoUngDung = () => {
    return cheDoUngDung;
};

export const thucHienGoiApi = async (diemCuoi, phuongThuc = 'GET', duLieu = null, timeout = 5000) => {
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeout);

    const tuyChon = {
        method: phuongThuc,
        headers: TIEU_DE_TRUY_VAN,
        signal: controller.signal
    };

    if (duLieu) {
        tuyChon.body = JSON.stringify(duLieu);
    }

    const url = `${DUONG_DAN_CSDL}/${diemCuoi}`;

    try {
        const phanHoi = await fetch(url, tuyChon);
        clearTimeout(id);

        if (!phanHoi.ok) {
            const noiDungLoi = await phanHoi.text();
            throw new Error(`Lỗi API: ${phanHoi.status} - ${noiDungLoi}`);
        }
        return await phanHoi.json();
    } catch (error) {
        clearTimeout(id);
        console.error("Lỗi Fetch API:", error.name === 'AbortError' ? 'Timeout kết nối' : error.message);
        throw error;
    }
};

export const ghiNhanTuongTacApi = async () => {
    if (cheDoUngDung === 'offline') return;

    const homNayStr = dinhDangNgayISO(new Date());

    try {
        const danhSachCaiDat = await thucHienGoiApi(`setting?max=1`, 'GET', null, 3000);

        if (danhSachCaiDat && danhSachCaiDat.length > 0) {
            const caiDat = danhSachCaiDat[0];
            let soLuotMoi = (caiDat.connectionCount || 0) + 1;

            if (caiDat.date !== homNayStr) {
                soLuotMoi = 1;
            }

            if (window.$) $('#luong-truy-cap-api').text(`(${soLuotMoi})`);

            await thucHienGoiApi(`setting/${caiDat._id}`, 'PUT', { 
                connectionCount: soLuotMoi,
                date: homNayStr 
            }, 3000);
        } else {
             if (window.$) $('#luong-truy-cap-api').text(`(1)`);
            await thucHienGoiApi('setting', 'POST', {
                connectionCount: 1,
                date: homNayStr
            }, 3000);
        }
    } catch (e) {
        console.warn("Ghi nhận tương tác thất bại:", e);
    }
};

export const lamMoiThongKeCsdl = async (hamCapNhatWidget) => {
    try {
        const headers = TIEU_DE_TRUY_VAN;
        const queryReport = encodeURIComponent('{}');
        const hint = encodeURIComponent('{"$fields":{"_id":1}}');

        // Sử dụng Promise.all để lấy thông số nhanh hơn
        const [resReport, resNv, resSet] = await Promise.all([
            fetch(`${DUONG_DAN_CSDL}/report?q=${queryReport}&h=${hint}`, { headers }).then(r => r.json()),
            fetch(`${DUONG_DAN_CSDL}/nhanvien?q=${queryReport}&h=${hint}`, { headers }).then(r => r.json()),
            fetch(`${DUONG_DAN_CSDL}/setting?max=1`, { headers }).then(r => r.json())
        ]);

        let soLuotKetNoi = 0;
        if(resSet && resSet.length > 0) {
            const c = resSet[0];
            if (c.date === dinhDangNgayISO(new Date())) {
                 soLuotKetNoi = c.connectionCount || 0;
            }
        }

        if (hamCapNhatWidget) {
            hamCapNhatWidget(true, resNv.length, resReport.length, soLuotKetNoi);
        }
    } catch (e) {
        console.warn("Lấy thống kê DB thất bại", e);
        if (hamCapNhatWidget) hamCapNhatWidget(false, 0, 0, 0);
    }
};

import { thucHienGoiApi, lamMoiThongKeCsdl, ghiNhanTuongTacApi, datCheDoUngDung } from './api.js';
import { dinhDangNgayHienThi, dinhDangNgayISO, trichXuatSoLieu, hienThiThongBao } from './utils.js';
import { khoiTaoGiaoDien, xayDungMenuGiaoDien, apDungGiaoDien, luuCauHinhGiaoDien } from './theme.js';
import { KHOA_BO_NHO_TAM_CUC_BO } from './config.js';

$(function() {
    let danhSachNhanVien = [];
    let nhanVienHienTai = null;

    // Khởi tạo giao diện ban đầu
    khoiTaoGiaoDien();
    xayDungMenuGiaoDien();
    $('#hien-thi-ngay').text(dinhDangNgayHienThi(new Date()));

    const hienThiDanhSachNhanVien = () => {
        const $vung = $('#vung-danh-sach-nv');
        if (danhSachNhanVien.length === 0) {
            $vung.html('<div class="text-center py-5 text-muted small w-100">Không có dữ liệu nhân viên. Vui lòng kiểm tra file fos.txt hoặc kết nối mạng.</div>');
            return;
        }

        let html = '';
        danhSachNhanVien.forEach(nv => {
            let lopNut = 'btn w-100 text-start py-2 px-3 rounded-4 shadow-sm nut-ten-nv mb-2';
            if (nv.trangThai === 'Đã báo cáo') lopNut += ' btn-reported';
            else if (nv.trangThai === 'Off') lopNut += ' btn-off';
            else lopNut += ' btn-light';

            html += `
                <div class="col-6 col-md-4 col-lg-3">
                    <button class="${lopNut}" data-nv-ten="${nv.ten}">
                        <div class="fw-bold small mb-0 text-truncate">${nv.ten}</div>
                        <div class="small opacity-50" style="font-size: 0.7rem;">${nv.trangThai}</div>
                    </button>
                </div>
            `;
        });
        $vung.html(html);
    };

    const taiDuLieuTuFileLocal = async () => {
        try {
            // Thêm timestamp để tránh cache trình duyệt khi sửa file txt
            const phienBan = new Date().getTime();
            const response = await fetch(`fos.txt?v=${phienBan}`);

            if (!response.ok) throw new Error("Không tìm thấy file fos.txt trên host");

            const text = await response.text();
            if (!text.trim()) throw new Error("File fos.txt trống");

            const lines = text.split('\n').filter(line => line.trim() !== '');
            const localData = lines.map((line, index) => {
                const parts = line.split('|');
                return {
                    _id: `local_${index}`,
                    ten: parts[0]?.trim() || 'Fos Member',
                    gioiTinh: parts[1]?.trim() || 'Nam',
                    chiTieu: parseInt(parts[2]) || 50,
                    trangThai: 'Chưa báo cáo',
                    baoCao: ''
                };
            });

            if (localData.length > 0) {
                danhSachNhanVien = localData;
                datCheDoUngDung('offline');
                khoiPhucDuLieuTam();
                hienThiDanhSachNhanVien();
                capNhatWidgetTrangThai(false, localData.length, 0, 0);
                hienThiThongBao("Đã kích hoạt chế độ dự phòng (OFFLINE)", "error");
            }
        } catch (error) {
            console.error("Lỗi Fallback:", error);
            hienThiThongBao("Lỗi: Không thể tải danh sách nhân viên từ bất kỳ nguồn nào!", "error");
            hienThiDanhSachNhanVien(); // Hiển thị thông báo trống
        }
    };

    const khoiPhucDuLieuTam = () => {
        try {
            const tamStr = localStorage.getItem(KHOA_BO_NHO_TAM_CUC_BO);
            if (tamStr) {
                const tam = JSON.parse(tamStr);
                const homNay = dinhDangNgayISO(new Date());
                if (tam.ngay === homNay) {
                    tam.duLieuNv?.forEach(t => {
                        const nv = danhSachNhanVien.find(n => n.ten.toLowerCase() === t.ten.toLowerCase());
                        if (nv) {
                            nv.trangThai = t.trangThai;
                            nv.baoCao = t.baoCao;
                        }
                    });
                }
            }
        } catch (e) {
            console.warn("Không thể khôi phục bộ nhớ tạm", e);
        }
    };

    const capNhatWidgetTrangThai = (ok, slNv, slBc, access) => {
        const $dot = $('#cham-trang-thai-db');
        $dot.removeClass('online offline').addClass(ok ? 'online' : 'offline');
        $('#chu-trang-thai-db').text(ok ? 'RestDB Online' : 'Local Mode');
        $('#so-luong-nv-db').text(`NV: ${slNv}`);
        $('#so-luong-bao-cao-db').text(`BC: ${slBc}`);
        $('#luong-truy-cap-api').text(`(${access})`);
    };

    const taiDuLieuServer = async () => {
        try {
            // Thử kết nối server với timeout 5s
            const data = await thucHienGoiApi(`nhanvien?h=${encodeURIComponent('{"$orderby":{"Ten":1}}')}`, 'GET', null, 5000);

            if (data && Array.isArray(data) && data.length > 0) {
                danhSachNhanVien = data.map(i => ({
                    _id: i._id,
                    ten: i.Ten,
                    gioiTinh: i.GioiTinh,
                    chiTieu: parseInt(i.ChiTieu) || 50,
                    trangThai: 'Chưa báo cáo',
                    baoCao: ''
                }));
                datCheDoUngDung('online');
                khoiPhucDuLieuTam();
                hienThiDanhSachNhanVien();

                // Các tác vụ thống kê không cần await để tránh làm chậm UI
                lamMoiThongKeCsdl((ok, slNv, slBc, access) => {
                    capNhatWidgetTrangThai(ok, slNv, slBc, access);
                });
                ghiNhanTuongTacApi();
            } else {
                throw new Error("Dữ liệu server không khả dụng");
            }
        } catch (e) {
            console.warn("Kết nối server thất bại, đang thử đọc fos.txt...", e.message);
            await taiDuLieuTuFileLocal();
        } finally {
            $('#lop-phu-tai-trang').fadeOut(300);
        }
    };

    // --- Các sự kiện tương tác ---

    $(document).on('click', '.nut-ten-nv', function() {
        nhanVienHienTai = $(this).data('nv-ten');
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            $('#modalDanBaoCaoLabel').text(`Báo cáo: ${nhanVienHienTai}`);
            $('#noi-dung-bao-cao-nhap').val(nv.baoCao || '');
            const modal = new bootstrap.Modal(document.getElementById('modal-dan-bao-cao'));
            modal.show();
        }
    });

    $('#nut-luu-bao-cao-don').on('click', function() {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            nv.baoCao = $('#noi-dung-bao-cao-nhap').val();
            nv.trangThai = nv.baoCao.trim() ? 'Đã báo cáo' : 'Chưa báo cáo';
            hienThiDanhSachNhanVien();
            bootstrap.Modal.getInstance(document.getElementById('modal-dan-bao-cao')).hide();
            hienThiThongBao(`Đã cập nhật ${nv.ten}`);
            luuTamLocalStorage();
        }
    });

    $('#nut-danh-dau-off').on('click', function() {
        const nv = danhSachNhanVien.find(n => n.ten === nhanVienHienTai);
        if (nv) {
            nv.baoCao = `Fos ${nv.ten} OFF`;
            nv.trangThai = 'Off';
            hienThiDanhSachNhanVien();
            bootstrap.Modal.getInstance(document.getElementById('modal-dan-bao-cao')).hide();
            hienThiThongBao(`${nv.ten} đã OFF`);
            luuTamLocalStorage();
        }
    });

    const luuTamLocalStorage = () => {
        localStorage.setItem(KHOA_BO_NHO_TAM_CUC_BO, JSON.stringify({
            ngay: dinhDangNgayISO(new Date()),
            duLieuNv: danhSachNhanVien.map(n => ({ ten: n.ten, trangThai: n.trangThai, baoCao: n.baoCao }))
        }));
    };

    $('#nut-tao-bao-cao').on('click', function() {
        let tMC = 0, tNTB = 0, tETB = 0, tPos = 0, tAE = 0, active = 0;
        let details = [];

        danhSachNhanVien.forEach(nv => {
            const bc = nv.baoCao || '';
            const n = trichXuatSoLieu(bc, 'NTB');
            const e = trichXuatSoLieu(bc, 'ETB');
            const mtd = trichXuatSoLieu(bc, 'MTD MC');
            const mc = n + e || trichXuatSoLieu(bc, 'MC');

            if (nv.trangThai === 'Off') {
                details.push(`- ${nv.ten}: OFF (${mtd}/${nv.chiTieu})`);
            } else if (nv.trangThai === 'Đã báo cáo') {
                active++; tMC += mc; tNTB += n; tETB += e;
                tPos += trichXuatSoLieu(bc, 'Pos');
                tAE += trichXuatSoLieu(bc, 'AE+');
                details.push(`- ${nv.ten}: ${mc}/${mtd}/${nv.chiTieu}`);
            } else {
                details.push(`- ${nv.ten}: Chưa báo cáo`);
            }
        });

        const res = `BÁO CÁO FOS ${dinhDangNgayHienThi(new Date())}\n` +
                    `Tổng MC: ${tMC} | NTB: ${tNTB} | ETB: ${tETB}\n` +
                    `AE+: ${tAE} | Pos: ${tPos}\n` +
                    `Hoạt động: ${active}/${danhSachNhanVien.length}\n\n` +
                    `CHI TIẾT:\n${details.join('\n')}`;

        $('#vung-ket-qua-bao-cao').val(res);
        hienThiThongBao("Đã tổng hợp báo cáo!");
        luuTamLocalStorage();
    });

    $('#nut-sao-chep').on('click', function() {
        const val = $('#vung-ket-qua-bao-cao').val();
        if (val) {
            navigator.clipboard.writeText(val).then(() => hienThiThongBao("Đã sao chép vào bộ nhớ tạm"));
        } else {
            hienThiThongBao("Chưa có nội dung để sao chép", "error");
        }
    });

    $(document).on('click', '.lua-chon-giao-dien', function(e) {
        e.preventDefault();
        const theme = $(this).data('theme');
        const mode = $(this).data('mode');
        const className = `theme-${theme}-${mode}`;
        apDungGiaoDien(className);
        luuCauHinhGiaoDien(className);
    });

    // Khởi động ứng dụng
    taiDuLieuServer();
});
